INSERT INTO public.products (id, name, slug, description, price, compare_at_price, sku, image_url, category_id, brand, in_stock, stock_quantity, featured, is_new, is_best_seller, tags, rating, review_count, specs) VALUES
('b2000000-0000-0000-0000-000000000001', 'Certified AllTrek All Season Tire For Passenger & CUV', 'certified-alltrek-all-season-tire-for-passenger-cuv', 'Enhanced grip and braking performance in wet conditions due to silica compound. A comfortable ride due to enhanced 4-channel grooves. Road rated 96.5, with a score of 100 on dry traction and fuel economy. It’s best to take off your winter tires when the outside temperature is consistently at 7 degrees Celsius or higher. The softer compound in Winter Tires is designed for cold weather usage and will wear faster in warmer temperatures.. Wheels sold separately', 49.99, NULL, '0043000P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0063003/205-55r16-91v-certified-alltrek-3fd49efa-561a-4cb4-889e-2a76bc2bfbb2-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Certified', true, 23, false, false, false, '{}', 4.3367, 790, '{"width":215,"aspect_ratio":75,"rim_diameter":15,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":620,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000002', 'General Evertrek GT All Season Tire For Passenger & CUV', 'general-evertrek-gt-all-season-tire-for-passenger-cuv', 'Equipped with traction ridges to enhance grip in snowy conditions. Flatter design to improve stability and treadlife. Visual tread indicators display real time tread wear conditions. Traction ridges to increase snow grip. Wheels sold separately', 49.99, NULL, '0042034P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0042034/p175-70r14-84t-general-evertrek-gt-15576930000--c1a27e22-cf99-42db-9d11-cac1eca9a1af-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'General Tire', true, 17, false, false, false, '{}', 4.4085, 563, '{"width":235,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":660,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000003', 'MotoMaster Performance Edge Ultra High Performance All Season Tire for Passenger Cars', 'motomaster-performance-edge-ultra-high-performance-all-season-tire-for-passenger', 'Provides excellent cornering ability while offering enhanced braking to ensure exceptional control and responsiveness. Delivers Advanced Traction in both wet and dry weather. Delivers a secure ride on straight and curvy roads. Circumferential Grooves with a multi-siping design aids in water evacuation resulting in reduced braking distance on wet roads. Wheels sold separately', 216.99, NULL, '0063098P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0063098/p205-55r16-91w-motomaster-performance-edge-a150ff0b-1d36-4c0b-865e-b3bf54c901d0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'MotoMaster', true, 34, false, false, false, '{}', 4.3953, 86, '{"width":285,"aspect_ratio":35,"rim_diameter":20,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":639,"traction":"AA","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000004', 'MotoMaster Hydra Edge Plus All Season Tire', 'motomaster-hydra-edge-plus-all-season-tire', 'Improved traction and reduced hydroplaning risk with Hydra Control Technology (HCT) for confident wet handling. Proven four-groove design channels rain and slush, updated with larger outer voids and a fully voided center rib for added traction. Outstanding grip, comfort, and tread durability from a next‑generation rubber compound. Quieter, smoother ride with reduced road noise thanks to a multi‑pitch tread with staggered lugs. Sharper steering and greater high‑speed stability through a high‑tension cap ply. Wheels sold separately', 49.99, NULL, '0059516P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0078634/p225-65r17-motomaster-hydra-edge-plus-4ab0acc6-5c46-4152-95f9-1c47621158f9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'MotoMaster', true, 31, false, false, false, '{}', 4.7789, 95, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":677,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000005', 'MotoMaster Hydra Edge Tire for Passenger', 'motomaster-hydra-edge-tire-for-passenger', 'Features a new rubber tread compound with improved uniform load distribution. Advanced Silicon Formula (Solution Polymerized Styrene Butadiene (SSBR)) delivers increased grip for excellent cornering performance. Hydra Control technology (HCT) unleashes an exquisite combination of material and design for superior braking and traction on wet surfaces. Enhanced tire durability and tread wear performance with 120,000km limited mileage rating. Ensure compatibility with your vehicle before purchase. Road rated 98.1 overall: wet traction 100/100, dry traction 97.8/100, comfort/road noise 88.7/100, fuel economy 96.2/100. HCT maximizes contact with wet road surfaces by combining the SSBR compound''s flexibility with a symmetrical tread pattern that channels water evenly across the contact patch. The uniform load distribution promotes even wear across the tread face, extending usable tire life (assuming proper inflation)', 49.99, NULL, '0042054P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0063071/p205-55r16-91h-motomaster-hydra-edge-b5ce3ed1-77a9-4320-abba-cdc0a70d2ae1-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'MotoMaster', true, 39, false, false, false, '{}', 4.2966, 418, '{"width":275,"aspect_ratio":45,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":698,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000006', 'MotoMaster Hydra Edge Tour Tire for CUV', 'motomaster-hydra-edge-tour-tire-for-cuv', 'Superior wet handling due to Hydra Control Technology (HCT) which results in an improvement in overall traction and reduced risk of hydroplaning. Cornering ability is enhanced due to advanced silicone formula (Solution Polymerized Styrene Butadiene (SSBR) providing increased cornering grip. Experience greater high speed stability and an improved braking grip with larger tread block and improved central tread block design. See improved tread life a result of larger tread block designs helping to ensure uniform load distribution. Improved wet weather traction due to innovative siping design that evacuates more water from the tire surface. Wheels sold separately', 49.99, NULL, '0063010P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0072021/225-65r17-102h-motomaster-hydra-edge-tour-d10dfa65-ba19-4a9e-a90c-e5aa9b3f531c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'MotoMaster', true, 31, false, false, false, '{}', 4.2209, 851, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":678,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000007', 'Michelin Defender 2 All Season Tire For Passenger & CUV', 'michelin-defender-2-all-season-tire-for-passenger-cuv', 'Features durable construction. Quiet and comfortable ride. All-season safety. Wheels sold separately. EV ready. Supported by the Michelin Promise Plan of a 60-day satisfaction guarantee, roadside assistance, and a 80,000-mileage warranty', 49.99, NULL, '5081008P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5081008/245-50r20-102h-102h-michelin-defender-2-03296--2498ff63-a123-4f59-a95a-f992124d13c1-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Michelin', true, 37, false, false, false, '{}', 4.7073, 1418, '{"width":255,"aspect_ratio":70,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":643,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000008', 'Continental UltimateContact All Season Tire for Passenger Car and CUV', 'continental-ultimatecontact-all-season-tire-for-passenger-car-and-cuv', 'Offers reduced rolling resistance. Visual indicators on the tread provide performance feedback on optimized driving condition and vehicle alignment status. EV compatible sidewall marking indicates the tire''s suitability for electric vehicle applications. Designed to reduce environmental impact.', 49.99, NULL, '0053032P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0053032/p195-65r15-91h-continental-ultimate-contact-15572060000--732fef00-4af0-40b1-ad8c-73ae768a3e15-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Continental', true, 33, false, false, false, '{}', 4.6561, 157, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":697,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000009', 'Cooper Endeavor Plus™ All-Season Tire For Passenger & CUV', 'cooper-endeavor-plus-all-season-tire-for-passenger-cuv', 'Ensures even treadwear for extended tire life. Offers balanced performance for enhanced traction in various weather conditions. Engineered for a quiet and comfortable driving experience. Wheels are sold separately. Wheels sold separately', 49.99, NULL, '0081604P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/0081700/235-65r17-cooper-endeavor-plus-90000039852--3ac9a86a-e1b2-4335-8480-e2dd61e1ef9d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Cooper', true, 12, false, false, false, '{}', 4.9231, 13, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":681,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000000a', 'Goodyear Wrangler SR-A All Season Tire For Truck & SUV', 'goodyear-wrangler-sr-a-all-season-tire-for-truck-suv', 'Aggressive tread pattern for excellent on/off-road traction. Exclusive wet traction compound for superior traction on wet roads. Wide circumferential grooves enhance water flow for improved grip in rain. It’s best to take off your winter tires when the outside temperature is consistently at 7 degrees Celsius or higher. This is because the rubber compound in All Season Tires is better suited for warmer temperatures and to provide better grip to the road. The softer compound in Winter Tires is designed for cold weather usage and will wear faster in warmer temperatures.. Goodyear Wrangler Wheels sold separately', 49.99, NULL, '0052465P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/0052000/p265-75r15-112s-goodyear-wrangler-sr-a-7f64f991-f13d-4d6b-bc64-882770b701ab-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Goodyear', true, 16, false, false, false, '{}', 3.9301, 529, '{"width":265,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":658,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000000b', 'MotoMaster Hydra Edge HD All Season Tire for Truck & SUV', 'motomaster-hydra-edge-hd-all-season-tire-for-truck-suv', 'Hydra Control Technology (HCT) is a proven leader when it comes to wet surface traction and reduced risk of hydroplaning. Lateral groove angles optimized with SPPS noise simulation technology. 3D siping on all lug blocks contribute to higher tread rigidity promoting tread uniformity. Wheels sold separately. Provides increased ride comfort and promotes low road noise. Outstanding handling and stability', 49.99, NULL, '0063095P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0063096/p245-75r16-motomaster-hydra-edge-hd-c4826b23-2506-4c03-a8a2-ab30e2d23b6b-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'MotoMaster', true, 35, false, true, true, '{}', 4.2069, 58, '{"width":235,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":650,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000000c', 'Pirelli Scorpion AS Plus 3 All Season Tire for CUV, SUV and Truck', 'pirelli-scorpion-as-plus-3-all-season-tire-for-cuv-suv-and-truck', 'Horizontal 3D sipes in the shoulders. Zag central sipes and deep sipes - Zig zag sipes are longer than straight ones. Innovative materials that extend tire working range to severe winter conditions. Improved braking in all weather conditions and snow handling. Additional vertical sipes which work together with the horizontal 3D sipes. Reduced aquaplanning. Enhanced wet handling and braking. Strong mileage improvement, no compromises on wet. Wheels sold separately', 49.99, NULL, '4082217P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4082219/225-65r17-102h-scorpion-as-plus-3-3917400--06c5715c-f05c-4d53-8e42-ebd9ce275f17-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Pirelli', true, 38, false, true, false, '{}', 4.7632, 38, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":671,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000000d', 'Uniroyal Tiger Paw Touring All Season Passenger & CUV Tires', 'uniroyal-tiger-paw-touring-all-season-passenger-cuv-tires', 'Sizes available for most passenger cars, CUVs and small to medium SUVs. An affordable, cost-effective, all-season tire. Tread life guaranteed up to 75,000 miles (120,000 km). Wheels sold separately', 49.99, NULL, '0080054P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2080742/225-65r17-uniroyal-tiger-paw-touring-a-s-26161--c07ddb05-d83b-4a1a-ae61-e8cf92413a34-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Uniroyal', true, 15, false, true, false, '{}', 4.0495, 101, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":628,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000000e', 'Pirelli Cinturato P8 All Season SUV Tire for CUV and SUV', 'pirelli-cinturato-p8-all-season-suv-tire-for-cuv-and-suv', 'STABLE AND PRECISE HANDLING - The reinforced shoulder blocks and transversal grooves on central ribs provide enhanced stability. INCREASED CONTROL - The high density tread sipes and internal shoulder blocks provide excellent all-season grip. HIGHER MILEAGE - Compound materials developed with optimized polymer blend promote a long-lasting experience', 49.99, NULL, '0074938P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0074938/225-65r17-pirelli-p8-cinturato-suv-dbd679a7-ea6d-4125-b3cf-f4cb7e24b6c0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Pirelli', true, 28, false, false, false, '{}', 4.6512, 86, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":674,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000000f', 'Yokohama Avid Ascend GT All Season Tire For Passenger & CUV', 'yokohama-avid-ascend-gt-all-season-tire-for-passenger-cuv', 'Triple 3D sipes and an ultra-square contact patch produce even, long wear that retains its all-season traction over the life of the tire. All-new TriBlend compound and an asymmetric groove arrangement that deliver extra grip on wet and snowy roads. 3D sipes and a notched block tread design produce more grip for true all-season traction. Wheels sold separately', 49.99, NULL, '4087053P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4087063/205-55r16-91h-ascend-gt-110132711--3a18c074-eb79-4d0f-82fa-b52e00193a93-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 34, false, false, false, '{}', 4.6517, 178, '{"width":225,"aspect_ratio":75,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":672,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000010', 'Yokohama Geolandar CV G058 All Season Tire For Passenger & CUV', 'yokohama-geolandar-cv-g058-all-season-tire-for-passenger-cuv', 'With its exceptional wet and winter grip, the long-lasting GEOLANDAR CV G058 is designed to provide true all-season confidence, no matter the weather. Engineered to deliver confidence of drivers of crossovers and midsized SUVs. Multi-pitch tread pattern designed to give you a quiet driving experience. Wheels sold separately', 49.99, NULL, '3086635P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/3086635/215-65r16-98h-geolandar-cv-g058-1e4ba195-26ed-4ca2-87a6-9e10002d6f4c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 21, false, false, false, '{}', 4.6667, 9, '{"width":265,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":680,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000011', 'Firestone Destination LE3 All-Season Tire For Truck & SUV', 'firestone-destination-le3-all-season-tire-for-truck-suv', 'TRACTIONTECH™ TECHNOLOGY - provides more consistent wear over longer tire life vs the DEST LE2. HYDRO-GRIP™ TECHNOLOGY - for enhanced water evacuation from contact patch under wet conditions. FULL-DEPTH 3D SIPES - for enhanced snow traction and improved performance throughout the tire’s limited warranty. Wheels sold separately. Highway rated', 49.99, NULL, '3085677P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3085677/215-75r15-100t-destination-le3-005343--5e5a2dae-480c-41f5-88f7-263de87121b4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Firestone', true, 21, false, true, false, '{}', 4.6206, 535, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":650,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000012', 'Cooper ProControl™ All Season Tire for Passenger & CUV', 'cooper-procontrol-all-season-tire-for-passenger-cuv', 'The Cooper ProControl™ All-Season Tire is designed to wear evenly for crisp handling at every turn. Engineered to take on water while maintaining grip. Armor Belt Technology utilizes steel belts to help provide the stiffness and strength needed for a crisp steering response. Sipes widen as the tire wears to help maintain grip on the road allowing water/snow to clear the tread. Stronger materials added for extended tread life. Wheels sold separately', 49.99, NULL, '5082801P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5083207/235-65r17-104h-cooper-procontrol-166484021--7c42e6af-7f74-4ef3-84cf-2139b8a042b9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Cooper Tires', true, 12, false, false, false, '{}', 4.9091, 11, '{"width":285,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":628,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000013', 'BFGoodrich Advantage Control All Season Tire For Passenger & CUV', 'bfgoodrich-advantage-control-all-season-tire-for-passenger-cuv', 'The BF Goodrich Advantage Control All Season Tire For Passenger & CUV features improved braking performance on wet roads. Stops 8 feet shorter in the wet than leading competitive tires1 and 13 feet shorter in the wet than the BFGoodrich® Advantage™ T/A® Sport tire. Active Sipe and Aqua-Flume™ Technology work together with an advanced all-season compound to provide better traction in wet conditions. A MORE ENJOYABLE RIDE: New tread pattern and tire design help the Advantage™ Control™ tire score better overall for subjective noise than a leading competitor. ADVANCED MILEAGE: Full-depth tread features help maintain consistent performance and look throughout the life of the tire. Wheels sold separately', 49.99, NULL, '2080523P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3080725/205-65r15-99h-xl-bfg-advantage-control-71973--91accde2-caee-49e9-b557-82d182f0ff59-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'BFGoodrich', true, 29, false, true, false, '{}', 4.2731, 238, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":632,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000014', 'Goodyear Assurance All Season Tire For Passenger & CUV', 'goodyear-assurance-all-season-tire-for-passenger-cuv', 'Goodyear Assurance All Season Tire features wide tread grooves to help evacuate water and slush for enhanced wet traction. Tread pattern reduces road noise for a quieter ride. The large stable shoulder blocks improve dry and wet handling. Wheels sold separately', 49.99, NULL, '2083601P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4089107/245-60r18-105h-sl-assurance-all-season-407819374--91a54c6b-0281-419c-b92e-160b0f9ece2a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Goodyear', true, 25, false, false, false, '{}', 4.3674, 969, '{"width":295,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":699,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000015', 'Pirelli Scorpion™ Zero All Season Tire for Passenger & CUV', 'pirelli-scorpion-zero-all-season-tire-for-passenger-cuv', 'The high sipe density provides an excellent grip and traction in all conditions. The optimized tread design with curved grooves and bridges provides noticeable noise reduction. Four longitudinal grooves and lower tread depth improve water expulsion and dry braking performance. Wheels sold separately', 49.99, NULL, '4082545P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/4082545/245-45r20-103v-xl-szroas-vol-ncs-2739400--47527b8f-18f8-4fb6-8880-0579c98d8d5a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Pirelli', true, 20, false, false, false, '{}', 5, 7, '{"width":285,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":652,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000016', 'Dynamo UHP801 Performance Tire For Passenger & CUV', 'dynamo-uhp801-performance-tire-for-passenger-cuv', 'Dynamo UHP801 is an ultra high-performance All-Season Tire, designed for uncompromising performance under all weather conditions. Designed for high-speed performance, cornering and braking, the UHP801 lets you get the most out of your car in all-season. Optimized to deliver a balance between ultra-high performance needs and comfort of everyday driving in all weather conditions. Special silica blends maximize grip and handling stability in dry while maintaining outstanding wear characteristics. Wheels sold separately', 49.99, NULL, '0071031P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0071031/205-50r17-93w-dynamo-uhp801-ade63540-f286-4ca3-beb2-1a01f14e94b8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Dynamo', true, 21, false, false, false, '{}', 4.0714, 84, '{"width":275,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":627,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000017', 'Michelin Defender LTX M/S 2 All Season Tire For Truck & SUV', 'michelin-defender-ltx-m-s-2-all-season-tire-for-truck-suv', 'Offers the increased tread life that today''s drivers expect. Supports all-season safety and great fuel efficiency. Piano Acoustic Tuning smooths out tire noise and disturbances for a quiet and comfortable drive. Combines Michelin EverTread 2.0 compound with full-depth SipeLock sipes for reliable traction in demanding conditions throughout the life of the tire. Wheels sold separately', 547.99, NULL, '0074955P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0074955/265-70r17-116t-michelin-defender-ltx-m-s-2-21308--d61dd33c-0352-4c12-89d6-706709fb6a2c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Michelin', true, 19, false, false, false, '{}', 4.6303, 468, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":649,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000018', 'Bridgestone Alenza Prestige All-Season Tire For Truck & SUV', 'bridgestone-alenza-prestige-all-season-tire-for-truck-suv', 'Designed for SUV and truck drivers. Delivers a whisper-quiet ride, minimizing road noise for a more comfortable and peaceful driving experience, even on highways. Bridgestone''s proprietary PeakLife™ polymer resists premature and irregular treadwear, ensuring comfort, longevity, and precise wet performance. The tire’s advanced tread pattern helps reduce the risk of hydroplaning, providing enhanced stability and confidence on wet roads. QuietTrack™ technology is engineered to reduce road noise and provide a smoother ride for an overall quieter, more refined driving experience. PeakLife™ polymer is a proprietary material that helps resist uneven wear, delivering consistent performance and longevity throughout the tire’s life. ENLITEN™ technology suite enhances the tire''s sustainability, durability, and efficiency, making it a long-lasting and eco-friendly choice for drivers. Wheels sold separately', 49.99, NULL, '5088001P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5088001/235-65r17-104h-bridgestone-alenza-prestige-014059--90a2e4af-c043-426a-9547-21a30f0594e7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 25, false, false, false, '{}', 4.5, 2, '{"width":285,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":672,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000019', 'Yokohama AVID S34FV Tire', 'yokohama-avid-s34fv-tire', 'The AVID Ascend has tread block bridges to reduce tread movement for even treadwear and reduced noise. Adaptive 3D sipes deliver true all-season power, while promoting longer wear. Exclusive advanced compound technology contributes to low rolling resistance, and long tread life', 49.99, NULL, '4088551P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088551/p205-60r16-avid-s34fv-110193239--85558521-f6b4-455b-b473-342861455780-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 21, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":40,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":678,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000001a', 'Pirelli Cinturato P7™ All-Season Plus III Tire', 'pirelli-cinturato-p7-all-season-plus-iii-tire', 'Features additional vertical sipes and horizontal 3D sipes for improved snow handling and braking in all weather conditions. Zig zag sipes for enhanced handling in wet conditions, reduced aquaplaning and braking. Features innovative materials for better performance in severe winter conditions and strong mileage improvement', 49.99, NULL, '4080482P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4080482/205-50r17-93h-cinturato-p7-all-season-plus-3-3914400--22a212e3-4fd2-4506-bd0f-c668bf80fe95-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Pirelli', true, 18, false, false, false, '{}', 3.5, 10, '{"width":225,"aspect_ratio":50,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":623,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000001b', 'BFGoodrich Advantage Control HT All Season Truck & SUV Tire', 'bfgoodrich-advantage-control-ht-all-season-truck-suv-tire', 'Gives you the peace of mind to roam confidently. Specifically designed for large CUVs, full-size SUVs and pickups. Designed to deliver all-season traction and everyday control. The BFGoodrich Advantage Control HT tire is backed by 150 years of brand credibility. Wheels sold separately', 49.99, NULL, '5087216P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5087216/235-70r17-109t-bfgoodrich-advantage-control-ht-28852--ea5d218e-9539-4f5a-8962-32e4cabd457b-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'BFGoodrich', true, 19, false, false, false, '{}', 4.2, 5, '{"width":245,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":672,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000001c', 'Yokohama Avid Ascend LX All Season Tire For Passenger & CUV', 'yokohama-avid-ascend-lx-all-season-tire-for-passenger-cuv', 'Wide Circumferential Grooves: Four wide circumferential grooves provide reliable wet braking while lateral grooves help evacuate water and improve hydroplaning resistance. Optimized Contact Area: A wider, flatter contour provides a large footprint that evenly distributes pressure to combat uneven wear and improve treadlife. Multi-Pitch Design: An offset tread design staggered in a five-block sequence helps reduce pattern and road noise for a comfortable, smooth ride. Wheels sold separately', 49.99, NULL, '4088967P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088967/185-60r15-84h-avid-ascend-lx-110132801--ecd2235c-135a-470b-998b-1080f917d9cb-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 11, false, false, false, '{}', 4.641, 156, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":679,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000001d', 'Goodyear Eagle Sport All-Season Tire For Passenger & CUV', 'goodyear-eagle-sport-all-season-tire-for-passenger-cuv', 'The proven asymmetric tread offers both responsive handling and exceptional all-season grip. An innovative tread compound that delivers outstanding wet and dry performance, with enhanced grip in ice and snow. Full-depth sipes help create biting edges for confident grip as the tire wears. The rim protector helps defend against accidental curb damage', 49.99, NULL, '0051000P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5080425/p225-40r18-92h-goodyear-eagle-sport-a-s-109157382--2104df29-def2-42aa-bfa3-ad97e40effd7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Goodyear', true, 39, false, false, false, '{}', 4.5033, 769, '{"width":215,"aspect_ratio":75,"rim_diameter":15,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":632,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000001e', 'Goodyear Assurance ComfortDrive® Tire for Passenger & CUV', 'goodyear-assurance-comfortdrive-tire-for-passenger-cuv', 'Inserts smooth bumps and reduce vibrations. Optimized AquaChannel® Grooves - Next generation of symmetrically balanced grooves evacuate water and reduce hydroplaning for enhanced wet performance. Noise-reducing tread pattern - Adaptive Tread Design balances stiffness with design sequence to deliver lower noise levels and promotes even treadwear. Complex interlocking features - Located in every rib to deliver secure traction and smooth responsiveness', 49.99, NULL, '2081807P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2081807/goodyear-assurance-comfort-drive-255-50r20-413037582--0d096d91-03a6-4e3a-b3e5-35216fe91cbc-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Goodyear', true, 34, false, false, false, '{}', 3.9565, 69, '{"width":265,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":679,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000001f', 'Bridgestone Turanza EverDrive Tire For Passenger & CUV', 'bridgestone-turanza-everdrive-tire-for-passenger-cuv', 'All-season touring tire. Outstanding longevity. Quiet comfortable ride. Confident handling in wet and winter conditions. Next-generation compound designed to protect against irregular and premature wear. ENLITEN Technology with advanced compounds for long-lasting performance, new structural components for a quiet and comfortable ride, rolling resistance technology for exceptional fuel efficiency, and renewable materials used in manufacturing. Wheels sold separately. Multi-Pitch Tread Patternhelps reduce road noise and minimize vibration for a comfortable, quiet drive. New Pattern Designevacuates water and winter slush away for confident control', 49.99, NULL, '5087407P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5087407/205-55r16-94v-bridgestone-turanza-everdrive-019363--fe8196d8-d961-4151-845e-97516f859d65-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 39, false, false, false, '{}', 5, 2, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":678,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000020', 'Pirelli P ZERO All Season Plus 3 Tire', 'pirelli-p-zero-all-season-plus-3-tire', 'The newest Pirelli ultra high-performance replacement tire for driving enthusiasts. Dedicated to premium cars, it provides high levels of handling and braking in several weather conditions. Increased stiffness due to wider contact surface with the road. Additional flow for water evacuation. Improved snow grip performance. High density to increase the snow retention area', 49.99, NULL, '5082339P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5082348/225-45r18-95y-pirelli-pzero-all-season-plus-3-4083800--447077cd-9988-4efb-80e9-8684ee3df2de-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Pirelli', true, 28, false, true, false, '{}', 5, 6, '{"width":255,"aspect_ratio":60,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":682,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000021', 'Uniroyal Laredo HT All Season Tire for Truck & SUV', 'uniroyal-laredo-ht-all-season-tire-for-truck-suv', 'The Uniroyal Laredo HT Tire is designed for confidence on the road, whether it''s a highway commute, a long road trip or a downtown drive. Designed to offer a quiet, comfortable highway ride with all-season performance for year-round driving. Wheels sold separately', 49.99, NULL, '5082992P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5082992/235-70r16-109t-uniroyal-laredo-ht-63960--e0555706-ec4d-4595-be01-c7d2293dcf7f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Uniroyal', true, 31, false, false, false, '{}', 4.4444, 9, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":658,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000022', 'Kumho Crugen HT51 All Season Tire For Truck & SUV', 'kumho-crugen-ht51-all-season-tire-for-truck-suv', 'Kumho Crugen HT51 offers improved tread life with an optimal block shape of 4 channel symmetric layout. With 3D sipe application, braking performance on snow covered roads, and grip force have been maximized. Reinforced stable driving straight ahead performance and traction performance, handling performance through center block stiffening design. Wheels sold separately', 49.99, NULL, '3084266P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/3084266/225-70-r15-t04l-crugen-ht51-2234883--cb0a8b58-b038-47ed-a8bc-7a3fbb162f12-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Kumho', true, 28, false, false, false, '{}', 4.5, 2, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":653,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000023', 'Continental TrueContact Tour 54 All Season Tire For Passenger & CUV', 'continental-truecontact-tour-54-all-season-tire-for-passenger-cuv', 'Eco Plus Technology for reduced rolling resistance. Comfort Ride Technology provides a more comfortable ride and a quiet ride due to pattern and construction improvements. Visual indicators on the tread provide performance feedback on optimized driving condition performance and vehicle alignment status. EV compatible sidewall marking indicate the tires suitability for electric vehicle applications. Wheels sold separately. Extended tread life. Proven traction in light snow', 49.99, NULL, '5083753P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5083798/205-55r17-91h-continental-truecontact-tour-54-15579340000--8ff92d99-ac5e-4241-a367-065403a5e23f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Continental', true, 27, false, false, false, '{}', 4, 11, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":631,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000024', 'Cooper Cobra Instinct All Season Tire for Passenger & CUV', 'cooper-cobra-instinct-all-season-tire-for-passenger-cuv', 'Built for any season. Asymmetric tread pattern enables agile traction and handling no matter the season. Striking sidewall styling paired with a rim protector helps guard wheels from damage. Get improved grip on wet roads, enabled by sweeping tread grooves. Stronger, lightweight design for enhanced responsiveness. Wheels sold separately', 49.99, NULL, '5083102P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5083105/225-40zr18-92y-cooper-cobra-instinct-160111025--6b73b733-04bc-41f5-958a-94bf8ae730e0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Cooper Tires', true, 27, false, false, true, '{}', NULL, NULL, '{"width":285,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":692,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000025', 'Cooper Endeavor All Season Touring Tire', 'cooper-endeavor-all-season-touring-tire', 'Contemporary tread design. A trusted and proven design evenly distributes the rubber when it contacts the road. Excellent wet performance and dry handling. 65,000 mile limited treadwear warranty. Designed for drivers of all types of coupes, sedans and crossover vehicles. Has circumferential grooves that evacuate water, slush, and snow to improve wet traction and handling in light snow. Wheels sold separately', 49.99, NULL, '0081731P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0081731/235-45r18-cooper-endeavor-90000040225--9ff83925-be99-4851-9914-dedd95d2fce7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Cooper Tires', true, 14, false, false, false, '{}', NULL, NULL, '{"width":205,"aspect_ratio":55,"rim_diameter":16,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":633,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000026', 'Pirelli Cinturato P9™ AS Tire', 'pirelli-cinturato-p9-as-tire', 'Delivers excellent stability and control in both wet and dry conditions, with a focus on handling and aquaplaning performance. Ensures greater durability and enhanced safety, enabled by a robust compound with high tearing resistance. Reduces fuel consumption and increases efficiency through low rolling resistance. Wheels sold separately', 49.99, NULL, '0069550P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/1087698/p235-60r18-pirelli-cinturato-p9-as-4472300--77ebaea0-94b4-4f13-9456-60408085bdb2-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Pirelli', true, 16, false, false, true, '{}', 4.6, 10, '{"width":255,"aspect_ratio":60,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":698,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000027', 'Michelin LTX M/S 2 All Season Tire For Truck & SUV', 'michelin-ltx-m-s-2-all-season-tire-for-truck-suv', 'Innovative design reduces the risk of hydroplaning for safer driving. Multiple lateral grooves efficiently evacuate water. The built-in steel belt ensures incredible durability and strength to handle heavy loads. Wheels sold separately. 3D sipes enhance grip for better traction', 49.99, NULL, '0080215P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0080011/lt285-75r16126-123r-ec276c13-b17e-4ca3-8c21-352133bfa5d1-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Unknown', true, 25, false, false, false, '{}', 4.6216, 3351, '{"width":265,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":643,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000028', 'Firestone FT140 All-Season Replacement Tire for Passenger & CUV', 'firestone-ft140-all-season-replacement-tire-for-passenger-cuv', 'An all season replacement tire. Four deep tread grooves that accentuate its grip and driving capabilities. Excellent performance in wet and dry conditions. Wheels sold separately', 49.99, NULL, '3084813P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3082394/215-50r17-91h-fires-firestone-000265--3c7f8525-b20e-4b12-b2f7-2d497cab0be4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Firestone', true, 22, false, false, false, '{}', 4.5, 2, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":679,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000029', 'Continental ContiCrossContact LX All Season Tire For Truck & CUV', 'continental-conticrosscontact-lx-all-season-tire-for-truck-cuv', 'Continental ContiCrossContact LX Sport Tire delivers a smooth, comfortable ride while allowing for quick responses on the road. Asymmetric tread design provides high traction performance on wet, dry and snow covered roads. Delivers prolonged tread life for greater fuel economy and long wear. The Tri-Net Silica Tread Compound allows it to adjust to road conditions and improves traction. Wheels sold separately', 49.99, NULL, '2080170P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2080170/215-70r16-100h-crosscontact-lx-sport-3540830000--93234509-bf2a-417e-9d4b-655532ab5764-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Continental', true, 26, false, false, false, '{}', 2.625, 8, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":672,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000002a', 'Continental TerrainContact H/T All Season Tire, Highway Rated', 'continental-terraincontact-h-t-all-season-tire-highway-rated', 'TractionPlus technology providing robust durability, excellent wet performance and a quiet ride. Traction grooves for better snow grip when you need it most. Interlocking sipes for stable handling and braking when you need it and great all-season grip throughout the life of the tire. Full depth sipes aid in snow and ice traction while providing the comfort and traction needed in wet and dry conditions the rest of the year. Full depth sipes aid in snow and ice traction. Provides the comfort and traction needed in wet and dry conditions the rest of the year.. Interlocking sipes for stable handling and braking when you need it and great all-season grip throughout the life of the tire', 49.99, NULL, '4088811P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088811/225-60r17-99h-terraincontact-h-t-15571750000--13ca49a5-69af-4249-bca3-2348d2ddbc77-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Continental', true, 39, false, false, false, '{}', 5, 1, '{"width":245,"aspect_ratio":55,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":648,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000002b', 'Goodyear Assurance MaxLife 2 All-Season Tire for Passenger & CUV', 'goodyear-assurance-maxlife-2-all-season-tire-for-passenger-cuv', 'Goodyear’s longest lasting tire lets you drive more miles between replacements, thanks to advanced TredLife™ Technology and a durable tread compound built for up to 85,000 miles of performance. Tire delivers confident all-season control with four deep tread channels and solid shoulder blocks that help maintain traction in rain and light snow. A built-in Wear Gauge® makes it easy to monitor tread depth, so you always know how much life your tires have left. Designed to deliver a quiet, comfortable ride with even tread wear that helps reduce road noise over time. Whether you''re commuting or heading out on a weekend trip, this tire offers dependable performance to help keep life rolling smoothly. Wheels sold separately', 49.99, NULL, '5087549P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5087549/195-65r15-91h-goodyear-assurance-maxlife-2-110489702--f677b0b2-fb73-4514-88e0-4caad13c31cb-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Goodyear', true, 37, false, false, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":687,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000002c', 'Laufenn X Fit HT All Season Tire For Truck & SUV', 'laufenn-x-fit-ht-all-season-tire-for-truck-suv', 'Laufenn X FIT HT provides SUV and light truck drivers with excellent handling performance and a reliable, comfortable driving experience - at all times. 2-in-1 block shoulder design. Long mileage tread compound. Snow kerf. Stone ejectors. Secures stability during cornering. Long tread life. Optimal performance in all weather conditions. Prevents stone drilling and improves grip. Wheels sold separately', 49.99, NULL, '4089566P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/4089566/215-70r16-100h-x-fit-ht-1019688--e0068b7d-34bc-4f20-b085-f82444d7607a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Laufenn', true, 13, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":644,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000002d', 'Hankook Dynapro HP2 All Season Performance Tire for Passenger & CUV', 'hankook-dynapro-hp2-all-season-performance-tire-for-passenger-cuv', 'Hankook Dynapro HP2 Tire is a high-performance all-season tire for SUV''s which feature straight 4-channel waterway tread which resists hydroplaning. High loading silica compound improves dry and wet traction and lowers rolling resistance. Aqua slant sipes and groove provides an improved handling in wet and dry conditions by locking together for greater rigidity. Wheels sold separately', 49.99, NULL, '4080218P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2086929/hankook-dynapro-hp2-235-60r18h-1025244--9d3db73e-0f2a-46f1-8946-b0fd814070a7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Hankook', true, 16, false, false, false, '{}', 2, 4, '{"width":225,"aspect_ratio":75,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":667,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000002e', 'Hankook Ventus S1 Noble2 Performance Tire For Passenger & CUV', 'hankook-ventus-s1-noble2-performance-tire-for-passenger-cuv', 'Hankook Ventus S1 Noble2 Tire is a premium ultra performance all-season tire that is a perfect fit for passenger vehicles. New silica tread compound improves wet grip and lower rolling resistance. Advanced aqua hydro block design was developed through 3D hydroplaning simulation to provide highly efficient wet braking. Straight rib block applied to the outside of the tire helps to prevent road noise and increase cornering grip. Wide 2 steel belt ensures optimal tread stiffness for improved handling performance. Wheels sold separately', 49.99, NULL, '4080109P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2082257/215-50zr17-xl-95w-hankook-ventus-v12-evo-1008172--167ed0c5-13b8-4cac-bd03-96dce8c43424-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Hankook', true, 21, false, false, false, '{}', 1, 1, '{"width":255,"aspect_ratio":70,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":673,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000002f', 'Kumho Road Venture AT52 All Season Tire for Truck & SUV', 'kumho-road-venture-at52-all-season-tire-for-truck-suv', 'Designed for use with Jeeps, SUVs, and light trucks. This tire offers rugged off-road performance. Suitable for year-round use, it offers reliable traction on both dry and wet roads. Utilizes a five-pitch block variation to minimize road noise for a quieter ride. The tire features a cut-and-chip resistant tread compound for long-lasting performance. The symmetric tread pattern balances off-road capabilities with on-road comfort and even wear. Wheels sold separately', 49.99, NULL, '5081899P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5081934/-235-75r15-kumho-road-venture-at52-2289873--d40a1d5e-bc26-49ae-a221-e4bb8a00caec-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Kumho', true, 21, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":659,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000030', 'Firestone Affinity AS All-Season Tire for Passenger & CUV', 'firestone-affinity-as-all-season-tire-for-passenger-cuv', 'All-season traction with proven polymer compound for dependable wet and dry traction. Noise-silencing grooves engineered for a quiet enjoyable ride. Tread compound built to defend against uneven and premature wear. Wheels sold separately', 49.99, NULL, '5087311P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5087311/215-55r17-98v-firestone-affinity-as-018954--62a46764-043f-4e56-81ca-f85bc9f52956-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Firestone', true, 18, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":651,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000031', 'General Tire Grabber H/T All-Season Tires for Light Trucks & SUVs', 'general-tire-grabber-h-t-all-season-tires-for-light-trucks-suvs', 'A long-lasting all-season touring tire for crossovers, light trucks, and SUVs. Developed for year-round traction. Enhanced wet braking, rolling resistance, and up to 15% better tread life than the predecessor, General Grabber HTS60 tire. EV Compatible. Comes with Replacement Tire Monitor and Visual Alignment Indicators, which aid in detecting tire wear. Wheels sold separately', 49.99, NULL, '5086519P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5086521/-ev225-75r16-104s-general-grabber-h-t-04493350000--e8e01a59-d395-4109-b40e-dd133ca7eea8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'General Tire', true, 30, false, true, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":648,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
