('b2000000-0000-0000-0000-000000000033', 'Bridgestone Alenza 001 All-Season Performance Tire For Passenger & CUV', 'bridgestone-alenza-001-all-season-performance-tire-for-passenger-cuv', 'Superior driving performance throughout the year. Enhanced comfort and precise steering. Reliable safety on both wet and dry roads. Wheels are not included', 49.99, NULL, '3084674P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5081028/275-45r20-110yy-bridgestone-alenza-001-rft-012265--abfc6b66-a6e3-4c15-8ab1-5e9d4daa89b5-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 28, false, true, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":651,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000034', 'Michelin Primacy XC All Season Tire for Passenger & CUV', 'michelin-primacy-xc-all-season-tire-for-passenger-cuv', 'Fuel-efficient design. All-new tread design gives your 4x4 truck the appearance that it deserves. Michelin Comfort Control Technology uses computer-optimized design and precision manufacturing to offer greatly reduced vibrations and road noise. Latest generation of tread compounds delivers low rolling resistance, helping to reduce CO2 emissions. Wheels sold separately. Ideal for everyday driving, balancing performance and comfort seamlessly. Durable rubber compound ensures longevity and resistance to wear. Excellent grip on highway surfaces, enhancing overall driving safety and performance', 49.99, NULL, '4083191P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0080865/-michelin-primacy-xc-265-60r18-21293--c433d658-6e65-4a7c-9582-dcc721738c34-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Michelin', true, 36, false, false, false, '{}', 2.8462, 91, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":622,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000035', 'Goodyear Eagle F1 SuperSport Tire', 'goodyear-eagle-f1-supersport-tire', 'Designed for dry road conditions, the Goodyear Eagle F1 SuperSport features innovative compounds and advanced Goodyear technologies for better tracking and wet performance. The tread pattern and the tire shoulder is designed to provide responsive directional change with effective control when engaging corners. Delivers exceptional wet braking and wet handling performance', 49.99, NULL, '5080454P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3086041/255-35zr20-97y-eag-f1-supersportna0-d4baf59a-a004-4fb1-93f5-ffd1823da09a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Goodyear', true, 20, false, false, true, '{}', NULL, NULL, '{"width":205,"aspect_ratio":65,"rim_diameter":16,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":639,"traction":"AA","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000036', 'Continental ProContact RX SSR Tire', 'continental-procontact-rx-ssr-tire', 'All-season tire for year-round use. Enhanced responsiveness with large block structures. Optimized construction for original equipment. Noise reduction with blocking rib on shoulder block', 49.99, NULL, '2083154P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2083154/255-35r18-90v-fr-procontact-rx-ssr-15495360000--14918767-b810-41f8-b0c4-379cf25f8e63-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Continental', true, 26, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":653,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000037', 'Goodyear Wrangler Territory® HT All Season Tire for Truck & SUV', 'goodyear-wrangler-territory-ht-all-season-tire-for-truck-suv', 'Designed in conjunction with your vehicle to help it meet your expectations. Its reinforced construction gives strength and durability to tackle the demands of your day, every day. Territory® HT provides a smooth and quiet ride with responsive handling. Wheels sold separately', 49.99, NULL, '5083188P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5083188/255-65r17-110t-goodyear-wrangler-territory-ht-827017973--8fa74461-702a-4faf-b4e2-a9b41d115324-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Goodyear', true, 18, false, false, false, '{}', 5, 3, '{"width":265,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":681,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
