('b2000000-0000-0000-0000-000000000039', 'Bridgestone Turanza EV All-Season Tire For Passenger & CUV', 'bridgestone-turanza-ev-all-season-tire-for-passenger-cuv', 'Grand touring tire, specifically designed to complement the unique dynamics of electric vehicles. The Turanza EV is engineered to elevate your EV experience with excellent tread life, minimal ride noise and confident wet grip. Wheels sold separately', 49.99, NULL, '5083023P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5084699/-ev255-35r21-98w-bridgestone-turanza-ev-014280--fb0f601f-f999-4f32-a93e-2f52bc8c10f6-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 22, false, false, false, '{}', 2.8333, 6, '{"width":285,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":682,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
