('b2000000-0000-0000-0000-00000000003b', 'Laufenn X FIT HP All Season Tire for Truck & SUV', 'laufenn-x-fit-hp-all-season-tire-for-truck-suv', 'The Laufenn X Fit HP is a specialized tire for on-road SUV/CUV. Delivers outstanding wet performance and handling. Quiet and comfortable ride. Wheels sold separately', 49.99, NULL, '5082219P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5082230/235-60r17-102h-hankook-x-fit-hp-1031072--4cde6394-2e1c-4176-8afa-d7b904a019d9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Laufenn', true, 18, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":630,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000003c', 'Goodyear Eagle F1 Asymmetric All-Season Tire', 'goodyear-eagle-f1-asymmetric-all-season-tire', 'Goodyear Eagle F1 Asymmetric All-Season Tire offers enhanced wet and dry traction in any season. TredLock technology - microgrooves help provide biting edges for commanding wet traction and grip in turns. Proven asymmetric tire tread for precise, race-inspired handling on wet or dry roads. Dry handling zone puts more rubber on the road for superb dry traction and handling. Wheels sold separately', 49.99, NULL, '2088567P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2088568/235-50r18-97w-eagle-f1-asym-all-season-104207357--1e0f038c-4a59-43d8-a365-d858c1236c78-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Goodyear', true, 26, false, false, false, '{}', 4.3383, 201, '{"width":225,"aspect_ratio":50,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":688,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
