('b2000000-0000-0000-0000-00000000003e', 'Michelin Defender LTX M/S 2 All Season Tire For Truck & SUV - Flotation', 'michelin-defender-ltx-m-s-2-all-season-tire-for-truck-suv-flotation', 'Completely redesigned to meet the needs of today''s modern pick-up trucks and full size SUVs. Offers the increased tread life that drivers expect. All-season safety. Great fuel efficiency. Wheels sold separately', 49.99, NULL, '5084433P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5084433/35x12-50r22-121s-michelin-defender-ltx-m-s-2-45795--2c60152b-c02c-4554-8f56-107215524f3d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Michelin', true, 34, false, false, false, '{}', 4.6388, 371, '{"width":285,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":632,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000003f', 'Bridgestone Dueler H/L 400 All Season Tire for Passenger & CUV', 'bridgestone-dueler-h-l-400-all-season-tire-for-passenger-cuv', 'A premium all-season tire designed for SUVs, CUVs, and light trucks. Designed to offer a longer tread life, thanks to its durable construction and advanced compound. Optimized tread blocks help to reduce road noise and provide a smooth and comfortable ride. Wheels sold separately. Available in a variety of sizes', 49.99, NULL, '3080984P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3080984/255-50r19xl-107h-due-110169--c34f3e33-e77c-4a1d-bad1-c62c90ad8175-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 28, false, false, false, '{}', 3.5138, 109, '{"width":295,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":685,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000040', 'Bridgestone Dueler H/T 685 All Season Tire For Truck & SUV', 'bridgestone-dueler-h-t-685-all-season-tire-for-truck-suv', 'Thick tread design for enhanced durability. Engineered with heavy-duty steel belts and 2-ply polyester construction for towing and carrying heavy loads. Wide grooves help push water away from the tire, which helps reduce the risk of hydroplaning. Wheels sold separately. Multi-directional tread pattern enhances overall performance', 406.99, NULL, '3083742P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3083742/245-75r17-112t-duele-003348--27f58fdb-a6c5-4f54-a257-da73bcada80f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 26, false, false, false, '{}', 2.871, 31, '{"width":285,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":650,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000041', 'Nexen NPriz RH7 All Season Tire For Passenger & CUV', 'nexen-npriz-rh7-all-season-tire-for-passenger-cuv', 'The Nexen N''Priz RH7 Tire provides comfort with great directional driving stability thanks to an advanced center rib block design. At higher speeds, the shoulder block design, combined with 3-divison and 4-division designs, function to boost cornering and steering control - even with heavier loads. Wet weather driving is made safer due to 4 straight wide grooves that channel water outward. Wheels sold separately', 49.99, NULL, '3082288P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3082288/225-55r18-97h-npriz-12817nxk--8d45962e-cf43-42f4-90b7-45b41470099d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Nexen', true, 37, false, false, false, '{}', 3.6667, 3, '{"width":265,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":678,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000042', 'Michelin e.Primacy All Season Tire For Gas, Electric & Hybrid Vehicles', 'michelin-e-primacy-all-season-tire-for-gas-electric-hybrid-vehicles', 'Specifically designed for electric, hybrid, or low fuel consumption vehicles. Premium, long-lasting tire. Ideal partner for eco-friendly and economical driving. Refined performance. Quiet by design. Go the distance. Wheels sold separately', 49.99, NULL, '5086696P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5088906/265-45r21-108h-michelin-e-primacy-all-season-94281--99dc20b3-1fbd-4b41-916e-0ece747a50e9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Michelin', true, 34, false, false, false, '{}', 3.1798, 178, '{"width":225,"aspect_ratio":45,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":646,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000043', 'Kelly Edge Sport A/S Tire for Passenger & CUV', 'kelly-edge-sport-a-s-tire-for-passenger-cuv', 'Provides you with superior handling, traction, and enhanced tread wear. Compared to its predecessor, Kelly Edge Sport delivers improved wet handling as well as wet and dry stopping.. Asymmetric tread patterns is designed with diversified elements to help enable enhanced all-season handling. Sweeping circumferential grooves within the tread design help channel water, slush and snow away for better traction on wet roads. Contoured edge design helps reduce road noise and enhance tread life. Wheels sold separately', 49.99, NULL, '5083186P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5083186/225-40r19-93y-kelly-edge-sport-356469090--bd22ffe8-4593-4b12-925e-30c32a524420-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Kelly Tires', true, 30, false, false, false, '{}', 5, 3, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":648,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000044', 'Michelin Primacy LTX Tire', 'michelin-primacy-ltx-tire', 'Ideally suited for drivers looking to maximize fuel efficiency with a quiet and comfortable ride. Michelin uses its latest generation of tread compounds to deliver low rolling resistance, helping to improve fuel economy and reduce CO2 emissions. Michelin Comfort Control Technology uses computer-optimized design and precision manufacturing to offer greatly reduced vibrations and road noise. MaxTouch Construction maximizes the tire''s contact with the road and evenly distributes the forces of acceleration, braking and cornering, resulting in longer wear. All-season tire. EV ready. Wheels sold separately', 49.99, NULL, '0080863P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0080863/michelin-primacy-ltx-245-50r20-64338--4931b930-228b-42ad-ac53-81dd65064c1c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Michelin', true, 31, false, true, false, '{}', 2.76, 75, '{"width":265,"aspect_ratio":60,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":677,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000045', 'Falken Wildpeak H/T HT02 All Season Highway Terrain Tire For Truck & SUV', 'falken-wildpeak-h-t-ht02-all-season-highway-terrain-tire-for-truck-suv', 'Rugged highway terrain tire. All-season durability. Rigid tread blocks and rugged upper sidewalls. Advanced 4D nano design and 3D canyon sipe technology demonstrate Falken’s commitment to excellence, and provide the H/T02 with enhanced all-season drivability.. Support for high torque applications and industry leading wet braking performance. Wheels sold separately. Four wide circumferential grooves significantly enhance hydroplaning resistance by evaluating water, helping to maintain secure contact with the road in heavy rain. Silicon-enriched compound provides exceptional wet performance and superior wear life over a wide range of operating temperatures. Optimized thread pattern with three variable pitches positions the thread blocks to provide an exceptional quiet ride', 49.99, NULL, '4089311P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/4089311/235-75r15-109t-wildpeak-h-t-ht02-28824529--462de6ef-1cfe-4c4e-b127-e705bdda45d6-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Falken', true, 10, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":636,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000046', 'Falken Ziex ZE001 A/S All Season Tire For Passenger & CUV', 'falken-ziex-ze001-a-s-all-season-tire-for-passenger-cuv', 'Original Equipment (OE) tire on 2WD and 4WD light and medium crossovers and sport utility vehicles. Aggressive upper sidewall. Comfortable quiet ride. Adaptive constant pressure pattern design,. Hybrid undertread cap ply. Switchback siping. Wheels sold separately', 49.99, NULL, '4088461P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/4088461/225-55r18-98h-as-ziex-ze001-59000330--3b0fc92e-7017-49be-b058-43041a3cf551-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Falken', true, 28, false, false, false, '{}', 3, 2, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":684,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000047', 'Yokohama GEOLANDAR G033 All Season Tire For Passenger & CUV', 'yokohama-geolandar-g033-all-season-tire-for-passenger-cuv', 'Developed by expert engineers, the Yokohama GEOLANDAR G033 Tire is factory fitted to a Mitsubishi Outlander. Specially designed for drivers who travel a lot around the country and have to drive in various weather conditions. Yokohama Original Equipment. Wheels sold separately', 49.99, NULL, '4087573P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/4087573/p215-70r16-99h-g033-110103331--28c94a26-d25f-4c59-8465-628a13a04410-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 23, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":676,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000048', 'BFGoodrich Mud-Terrain T/A KM3 Off-Road Mud Tire For Truck & SUV - Flotation', 'bfgoodrich-mud-terrain-t-a-km3-off-road-mud-tire-for-truck-suv-flotation', 'BFGoodrich Mud Terrain KM3 Tire delivers extreme toughness and traction to take drivers anywhere they want to go. 5% better mud traction - Power through mud and loose soil with the Terrain-Attack tread design. Massive tread blocks are designed to deliver incredible grip from any angle of approach. Mud-Phobic Bars release compacted mud for continued traction. 8% better rock traction - Advanced Krawl-Tek compound that enhances grip on rock and slick surfaces. Linear FlexZone allows the tire to flex and envelop objects in aired-down driving situations. 27% tougher sidewalls - CoreGard Max Technology uses a thick sidewall shield and specialized compound to help guard against sharp objects. Traction-Armor Sidewall Sculpture helps prevent sidewall splitting. Wheels sold separately', 49.99, NULL, '4083972P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/0080845/-bfgoodrich-mud-terrain-t-a-km3-27x11-00r14-33323--e9ad52db-0a81-4d50-be5b-a3bb3ddc4dc3.png', 'a1000000-0000-0000-0000-000000000001', 'BFGoodrich', true, 15, false, true, false, '{}', 4.2959, 811, '{"width":255,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":635,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000049', 'Yokohama PARADA Spec-X PA02 All Season Tire For Passenger & CUV', 'yokohama-parada-spec-x-pa02-all-season-tire-for-passenger-cuv', 'Resistance to Wear: Reinforced shoulder blocks provide stability during cornering and generate more even wear. All Season Traction: Circumferential Center Groove provides outstanding water evacuation. Aggressive directional design increases acceleration and braking capabilities. Wheels sold separately', 49.99, NULL, '4087623P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/4087623/295-35r24-110v-xl-prdaspx-pa02-110100210--458e597c-9af7-4c9a-a4b5-f2205d4c0664.png', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 27, false, false, false, '{}', 5, 3, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":660,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000004a', 'Firestone Transforce HT3 All-Season Tire For Truck & SUV', 'firestone-transforce-ht3-all-season-tire-for-truck-suv', 'Long lasting, reliable wear. Dependable wet traction, even when loaded. Wheels sold seperately. Wheels sold seperately', 49.99, NULL, '5086001P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5086001/-lt215-85r16-115r-firestone-transforce-ht3-013891--56aa7dfc-3045-454e-80e6-75073dd3a609-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Firestone', true, 28, false, false, false, '{}', 5, 1, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":660,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000004b', 'Hankook Dynapro AT-m All Season Tire For Light Truck & SUV', 'hankook-dynapro-at-m-all-season-tire-for-light-truck-suv', 'Hankook Dynapro AT-m Tire is a premium aggressive all-terrain tire for light truck, van and sport utility vehicle. Innovative tread and sidewall design to enhance the style of your vehicle. Developed for high powered pickups. Offers the best grip and acceleration both on-and off-road. Wheels sold separately', 49.99, NULL, '2082577P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2082552/p245-70r16-107s-hankook-dynapro-as-1004359--73ec9e97-b381-4d9d-97ee-43cd768a31c0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Hankook', true, 28, false, false, true, '{}', 4.1538, 13, '{"width":275,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":658,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000004c', 'Kumho Solus TA51 All-Season Tire for Passenger/CUV/SUV', 'kumho-solus-ta51-all-season-tire-for-passenger-cuv-suv', 'Designed for the drivers of coupes, sedans, crossovers, and SUVs. It features ribs in the main channel and grooves that break up and dissipate resonant noise for a quieter ride. Four wide main channel grooves maximize water drainage and reduce hydroplaning in wet conditions. Multi Functionalized Polymers and High Dispersion Silica used in the tread compound improve treadwear and maximize grip in winter conditions. Wheels sold separately', 49.99, NULL, '5082523P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5082523/195-60r15-88h-kumho-solus-ta51-2285293--f29dcdd7-2cda-4ac3-a6d1-9464d3773d07-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Kumho', true, 25, false, false, false, '{}', 1, 1, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":657,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000004d', 'Firestone FR710 All Season Tire For Passenger & CUV', 'firestone-fr710-all-season-tire-for-passenger-cuv', 'The Firestone FR710 is an all-season Tire that features a long-lasting tread compound. Circumferential grooves help channel water out of the footprint area to improve resistance to hydroplaning. All-season tread design contributes to ride comfort. Wheels sold separately', 49.99, NULL, '3081607P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3081554/245-55r18-103w-fireh-5a6da51e-66fd-4ae7-b888-1d14e6f16bd1.png', 'a1000000-0000-0000-0000-000000000001', 'Firestone', true, 22, false, false, false, '{}', 3.6838, 117, '{"width":265,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":658,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000004e', 'Hankook Kinergy XP A/S All-Season Tire for Passenger & CUV', 'hankook-kinergy-xp-a-s-all-season-tire-for-passenger-cuv', 'Premium all-season control and comfort tire. The 3D sipes are placed on the main treads to keep the tire in an optimized shape. The beveled edges generate grip with improved traction on snowy roads. New silica and performance resin compound improves tread wear and snow performance by maintaining its flexibility even in situations where the tire becomes hard. By applying Convex TR (Tread Radius) technology, the Kinergy XP uniformly distributes grounding pressure for each rib block. The knurling technology applied inside the grooves effectively reduces tread pattern noise during road contact without losing the groove''s intended features. Wheels sold separately', 49.99, NULL, '5083343P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5083343/245-45r20v-99v-hankook-kinergy-xp-1032014--48630772-b2ee-46c1-a4c0-c75e3eca6e62-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Hankook', true, 12, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":652,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000004f', 'Bridgestone Turanza 6 All-Season Tire For Passenger & CUV', 'bridgestone-turanza-6-all-season-tire-for-passenger-cuv', 'Ideal for grand touring during summer. Optimized for long-lasting mileage. Enhanced fuel and energy efficiency. Superior grip on both wet and dry surfaces. Wheels are not included', 49.99, NULL, '5082109P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5084686/225-55r18-102y-bridgestone-turanza-6-014130--eec7f764-07a2-4c30-840b-8c3b79806d08-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 19, false, true, false, '{}', 3.875, 24, '{"width":235,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":687,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000050', 'Continental Winter Contact 850P TS Winter Tire for Passenger & CUV', 'continental-winter-contact-850p-ts-winter-tire-for-passenger-cuv', 'Boasts enhanced snow traction due to the tire''s S-GRIP pattern layout. Improved handling on snow due to PrecisionPlus. Better dry handling performance thanks to PowerSipes. Reduced stopping distances via ActiveBand. Wheels sold separately', 49.99, NULL, '2080515P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4080099/-225-55r17-97h-wintercontact-ts-850-p-ao-03539440000--30ba565b-c185-462b-819f-7828c361e311-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Continental', true, 33, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":635,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000051', 'General Tire Grabber HTS60 All-Season Tire For Light Trucks & SUVs', 'general-tire-grabber-hts60-all-season-tire-for-light-trucks-suvs', 'Wheels sold separately. Provides reliable braking on wet roads for added safety. Offers responsive handling on both wet and dry roads for versatility. Long-lasting treadwear for enhanced durability. Low road noise', 49.99, NULL, '0081529P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/0089542/235-70r16-106t-sl-gen-grabber-hts-15485170000--dd0c0c65-9dd6-4267-acfd-3ee8dce4f641-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'General Tire', true, 38, false, false, false, '{}', 4.625, 8, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":643,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000052', 'Nexen CP671 All Season Tire For Passenger & CUV', 'nexen-cp671-all-season-tire-for-passenger-cuv', 'The Nexen CP671 Tire provides high performance with a quiet comfortable ride, designed for all seasons. CP671''s straight wide grooves channel away water to maximize traction and avoid hydroplaning on wet roads. Acceleration is no problem; at high speeds the straight center rib block aides in direction driving and the lateral groove assure reliable traction and braking. Original Equipment for many popular vehicles. Wheels sold separately', 49.99, NULL, '3082246P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3082246/215-70r16-100h-cp671-22914034-7198-4c52-b311-c1fab30d7c9a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Nexen', true, 35, false, false, false, '{}', 4, 4, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":665,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000053', 'Hankook Kinergy GT H436 Tire', 'hankook-kinergy-gt-h436-tire', 'Designed for ultimate dry performance with optimized block sequence and stiffness, the Kinergy GT satisfies the strict performance requirements of automakers. High-grip silica compound and the chamfer edge sipes provide excellent traction in wet and snowy conditions. The Kinergy GT is the perfect touring all-season tire for comfortable driving experience and gives longer tread life. Wheels sold separately. Chamfer sipes maximize snow performance providing consistent grip in snowy conditions', 49.99, NULL, '4086233P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4086245/hankook-kinergy-gt-h436-1018940--d0e8af3b-335a-48a4-b244-b84cdb923317-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Hankook', true, 24, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":40,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":686,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000054', 'Kumho CUV/SUV Crugen HP71 All Season Tire, Highway Rated', 'kumho-cuv-suv-crugen-hp71-all-season-tire-highway-rated', 'Grants a top-tier luxurious feel and quiet ride. Improved level of safety, performance, and longevity. Wide circumferential grooves and micro-serration in tread blocks help to evacuate water, improve wet weather traction, and prevent hydroplaning. Variable Pitch Technology and tread pattern provides a quiet and comfortable ride', 49.99, NULL, '5080194P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5083377/275-45r20-110v-kumho-crugen-hp71-2324773--f57cf58e-e73b-4a7d-8087-bb0f61f84457-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Kumho', true, 19, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":654,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000055', 'Continental ContiCrossContact LX All Season Tire For Truck & SUV', 'continental-conticrosscontact-lx-all-season-tire-for-truck-suv', 'Continental ContiCrossContact LX Tire is a highway tire for light truck, SUV and crossover vehicle applications is designed for luxury, comfort and mileage. Works to delivers a smooth comfortable ride in all conditions. Asymmetric tread pattern is engineered to allow both sides of the tread to perform independently of each other. Tri-Net Silica tread compound adjusts to road conditions, cushions the ride, improves traction, and prolongs tread life for greater fuel economy and long wear. Wheels sold separately', 49.99, NULL, '0089582P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/0089582/255-75r17-115t-sl-cc-11757f7c-306c-41eb-94ee-7b661722c58a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Continental', true, 37, false, false, true, '{}', 1, 1, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":660,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000056', 'Bridgestone Turanza EL400-02 All Season Tire For Passenger & CUV', 'bridgestone-turanza-el400-02-all-season-tire-for-passenger-cuv', 'Ensures a more economical drive. Advanced design enhances performance in both wet and dry conditions. Innovative compound boosts wear resistance and enhances wet traction by increasing tread flexibility. Utilizes noise-cancelling technology to significantly reduce road noise. Wheels sold separately', 49.99, NULL, '3080785P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3080064/p205-60r15-90h-turan-f2b92f4a-4b95-458a-a6c5-c39213a54b4e-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 39, false, false, false, '{}', 3.1658, 199, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":674,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000057', 'Nexen N''Priz AH8 All-Season Tire with Quiet Performance', 'nexen-n-priz-ah8-all-season-tire-with-quiet-performance', 'Delivers a quiet, comfortable ride and exceptional all-season performance. Optimized handling through even block division in the shoulder and thin groove design. Stable riding and comfort performance with grid-style sipe design in the center. Reduced block stress with groove-sipe cross layout. Wheels sold separately', 49.99, NULL, '3082302P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3083732/225-45zr17-91w-n-pri-14198nxk--3f14c09b-bb67-4eb7-b7ad-4329b21a5a5e-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Nexen', true, 32, false, false, false, '{}', NULL, NULL, '{"width":225,"aspect_ratio":55,"rim_diameter":17,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":644,"traction":"AA","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000058', 'Michelin Premier LTX All Season Tire For Passenger & CUV', 'michelin-premier-ltx-all-season-tire-for-passenger-cuv', 'Extreme amounts of silica in the EverGrip™ compound provides exceptional wet grip for everyday handling. Sunflower oil keeps the EverGrip™ compound flexible in low temperatures. Tread blocks and sipes enhance traction in light winter conditions. Wheels sold separately. Provides shorter stopping distances and enhanced fuel efficiency', 49.99, NULL, '2087998P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/2087994/215-70r16-100h-prem-ltx-mi-10769--3aa83089-b758-41d6-b1c0-47d2eedf2b13-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Michelin', true, 23, false, true, false, '{}', 2.0991, 797, '{"width":255,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":676,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000059', 'Pirelli Scorpion Verde Tire for Passenger & CUV', 'pirelli-scorpion-verde-tire-for-passenger-cuv', 'Longer lasting tire that maintains high levels of performance and safety. Made from eco-compatible materials. Minimizes environmental impact, both at the production stages and throughout the life of the tire. The world''s first "Green Performance" summer tire for SUV''s and Crossover vehicles. Wheels sold separately', 49.99, NULL, '0089165P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2084786/235-55r17-11-scorpion-verde-1901400--c9ce6399-0bc7-4454-bd8b-958bdedaab71-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Pirelli', true, 34, false, true, false, '{}', 2.5, 8, '{"width":265,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":652,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000005a', 'Michelin Defender LTX M+S Mud and Snow All Season Tire For Truck & SUV - Flotation', 'michelin-defender-ltx-m-s-mud-and-snow-all-season-tire-for-truck-suv-flotation', 'All-season tire adapts to various weather conditions. Features MaxTouch construction to save up to 250 L of fuel throughout the tire''s life. Fitted for light trucks, SUVs and CUVs. On wet pavement, this tire stops up to 33'' (10 m) shorter than leading competitive tires. Evertread technology increases the durability of the tire in high severity situations like towing. Symmetric tread design with 3D active sipes locks together for better grip in wet and snowy conditions. Wheels sold separately. Computer-optimized tread blocks reduce vibrations and noise. Provides better grip and durability than winter tires in temperatures above 7°C', 49.99, NULL, '2088410P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2088410/31x10-5r15109rdfrltx-70511--c51ab3b2-b1e3-4a74-bbf0-a5e1e6cd96f9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Michelin', true, 34, false, false, false, '{}', 4.5494, 1398, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":629,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000005b', 'Pirelli PZero Nero All Season Tire For Passenger & CUV', 'pirelli-pzero-nero-all-season-tire-for-passenger-cuv', 'Ultra high performance tire. Delivers a combination of quiet ride, precise cornering and superior grip in wet and dry conditions. The asymmetric all-season tread design offers precision handling in all conditions. A solid centre rib gives a constant and consistent contact patch with the road while requiring shorter braking distances. Offers quicker accelerations in both dry and wet conditions. Wheels sold separately', 364.99, NULL, '0089206P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0089200/p235-45zr17-97wxlnra-4fdddffd-3c09-4054-a4be-a3c3615654a6-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Pirelli', true, 22, false, false, false, '{}', 1, 1, '{"width":285,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":649,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000005c', 'Bridgestone Ecopia EP422 All Season Tire For Passenger & CUV', 'bridgestone-ecopia-ep422-all-season-tire-for-passenger-cuv', 'Designed to boost gas mileage by reusing energy and reducing heat. Nanopro-tech improves rolling resistance and contributes to fuel efficiency. Fuel Saver sidewall reduces rolling resistance by reusing energy and cutting heat, unlike traditional sidewalls. Continuous rib maintains traction and helps deliver a quiet ride. Silica improves traction in wet conditions by increasing flexibility of tread compound. Circumferential grooves channel water away to reduce hydroplaning. Wheels sold separately', 49.99, NULL, '3080194P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3080177/225-60r18-100h-ecopi-438aed2a-4bdc-4d7d-908a-d6ece394f8e5-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 28, false, false, false, '{}', 3.8102, 137, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":694,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000005d', 'Kumho Temporary All Season Spare Tire for Passenger & CUV', 'kumho-temporary-all-season-spare-tire-for-passenger-cuv', 'Engineered by dedicated company that only produce exceptional tire that provides the best performance. Made to exceptional performance on road intentionally constructed to provide the best during your ride to your destination. Intended only to be used temporarily during an emergency. NOTE: Required to be inflated to 60 psi and only intended to be used at speeds restricted to 50 mph', 246.99, NULL, '2087325P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2087325/t155-90r18-kumho-temp-spare-2204323--1a171eb9-de66-4e92-97c9-67375d839f67-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Kumho', true, 39, false, false, false, '{}', NULL, NULL, '{"width":215,"aspect_ratio":75,"rim_diameter":15,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":621,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000005e', 'Goodyear Wrangler MT All Season Tire For Truck & SUV - Flotation', 'goodyear-wrangler-mt-all-season-tire-for-truck-suv-flotation', 'Goodyear Wrangler MT Tire is designed for extreme off-road expeditions. DuPont Kevlar reinforced sidewalls help increase sidewall puncture resistance. Hardworking wraparound tread helps to deliver sidewall traction in deep mud, sand, and rocks. Innovative asymmetric tread design helps provide aggressive off-road traction and enhanced handling on the road. Advanced silica rubber for superb off-road and wet traction. Wheels sold separately', 1078.99, NULL, '2085352P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/2085352/37-1250r16-5-123-m-wrangler-mt-743123154--631d078c-89cb-4fee-950c-cf1825fc6dbe-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Goodyear', true, 26, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":699,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000005f', 'Continental Conti4x4Contact All Season Tire For Passenger & CUV', 'continental-conti4x4contact-all-season-tire-for-passenger-cuv', 'The Continental Conti 4x4Contact Tire is specifically designed for SUV vehicles and features offset rows of tread lugs which ensure a particularly quiet and comfortable ride in normal road use. Wide longitudinal and lateral tread grooves protect against aquaplaning. This tire provides improved traction both on the road and in moderate off-road use. Wheels sold separately', 49.99, NULL, '0086266P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/0086810/michelin-ltx-a-t2-275-60r20-114s-36429--53851b45-4997-43de-99f2-69e16e61284c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Continental', true, 14, false, false, false, '{}', 3.6667, 3, '{"width":275,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":670,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000060', 'Continental VanContact A/S All-Season Tire for Passenger & CUV', 'continental-vancontact-a-s-all-season-tire-for-passenger-cuv', 'Continental VanContact A/S Tire provides all season performance for utility vans. Tires are optimized for wet braking and aquaplaning reductions. Rippled structure groove sides combined with step grooves in the middle provide great traction in snowy roads. Stiff ribbon structure with block-to-block connections and a stiff circumferential handling rib. New robust tread compound and an optimized contour helps improve cost savings with lower wear rate, fuel consumption and rolling resistance. Wheels sold separately', 49.99, NULL, '4083247P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-weather-tires/5081981/lt225-75r16-121-120r-conti-vancontact-a-s-ultra-04517800000--7b741d59-2b45-45a4-9243-b2ed6d8478ee-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Continental', true, 25, false, false, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":70,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":649,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000061', 'General Tire Grabber HD All Season Tire For Truck & SUV', 'general-tire-grabber-hd-all-season-tire-for-truck-suv', 'Heavy duty all-season General Tire Grabber HD Tire for commercial light trucks and vans that delivers long even tread list, durability, confident traction and handling. Proven durability and puncture resistant construction, a robust cut and chip resistant compound with ultra-high strength steel belts. Additional rubber gauge added to the sidewall to increase robustness against curbs and other sidewall abrasions. Wheels sold separately', 49.99, NULL, '4082282P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/4082282/195-70r15c-104-102r-grabber-hd-04507230000--11b72de3-19c3-4ed2-bfb2-49ab49991914-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'General Tire', true, 31, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":657,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000062', 'Michelin Premier A/S All Season Tire For Passenger & CUV', 'michelin-premier-a-s-all-season-tire-for-passenger-cuv', 'Reliable option for highway driving and urban commuting. EverGrip™ technology maintains traction by widening rain grooves and opening new grooves as the tire wears. Sunflower oil keeps the EverGrip™ compound flexible in low temperatures. Wheels sold separately. All-season design enhances fuel efficiency', 49.99, NULL, '2083637P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2083612/185-65r15-88h-premier-4a6a92db-538a-41bf-a29e-410c6bf85056-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Michelin', true, 17, false, false, false, '{}', 3.1859, 1764, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":656,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000063', 'Bridgestone Alenza 001 RFT All Season Tire For Passenger & CUV', 'bridgestone-alenza-001-rft-all-season-tire-for-passenger-cuv', 'Stable and reliable touring tire. Delivers improved fuel efficiency all year long. Engineered to maximize the potential on both wet and dry roads. High-level braking performance. Outstanding tire life. The tire comes with a 80,000 mile limited treadwear waranty. Wheels sold separately', 49.99, NULL, '3084667P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5084523/225-50r18-95v-bridgestone-alenza-001-011752--25d489e5-4d99-4170-83b2-0541237c5cd0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 28, false, true, false, '{}', 2, 2, '{"width":275,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":628,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000064', 'Yokohama GEOLANDAR M/T G003 Off-Road Mud Tire For Truck & SUV', 'yokohama-geolandar-m-t-g003-off-road-mud-tire-for-truck-suv', 'On/Off Road Traction: An innovative tread pattern and triple-polymer compound provide outstanding grip wherever you venture, on-road and off. Off-Road Durability: Rock-solid GEO-SHIELD construction is engineered to withstand punishment from even the most brutal trail. Long Tread Life: A new triple polymer compound and a wide flat profile combine for exceptional wear performance. Wheels sold separately', 49.99, NULL, '4087335P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/4087359/33x12-50r18-118q-e-m-t-g003-110133327--6b9b9dd5-4a37-457f-83eb-315ac89088d6-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 39, false, false, false, '{}', 4.7519, 133, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":696,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000065', 'Michelin Agilis HD Z Tire For Truck & SUV', 'michelin-agilis-hd-z-tire-for-truck-suv', 'Delivers rapid water evacuation for strong wet‑road traction, while the aggressive, evolving tread pattern helps maintain driver confidence and consistent performance throughout the tire’s long service life. Provide reliable traction in every wheel position from the first mile to the last. Add an extra layer of defense against stone drilling to help preserve tread integrity. Reduce stone retention to extend casing life and support improved retreadability. Increase durability, minimize downtime, and promote long casing life with exceptional retread performance. Protect the sidewall and shoulder areas from curb damage for added durability. Medium duty tire specifically designed for commercial vehicles, including vans, light truck, bus and RV. Wheels sold separately', 627.99, NULL, '5089115P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5089115/225-70r19-5-128n-michelin-agilis-hd-z-44835--b0d38161-54c9-4bb4-87b9-25765923eaa4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Michelin', true, 20, false, true, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":641,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000066', 'Yokohama Avid S35B Tire', 'yokohama-avid-s35b-tire', 'Passenger all-season tires are for drivers who want a combination of a smooth ride, good wear, durability along with all-season traction, including in light snow. Passenger all-season tires branded with the M+S symbol are often used as Original Equipment (O.E.) on standard coupes, sedans and family vans, as well as some entry-level pickup, crossover and sport utility vehicles. Original Equipment', 49.99, NULL, '4088524P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088524/225-55r17-avid-s35b-110133602--681f1c54-1931-4b6a-91ec-794cb8c7e718-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 10, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":45,"rim_diameter":19,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":621,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000067', 'Yokohama Avid S30B Tire', 'yokohama-avid-s30b-tire', 'The AVID Ascend has tread block bridges to reduce tread movement for even treadwear and reduced noise. Adaptive 3D sipes deliver true all-season power, while promoting longer wear. Exclusive advanced compound technology contributes to low rolling resistance, and long tread life', 224.99, NULL, '4088543P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088543/p205-55r16-avid-s30b-110193228--d6cdb0f9-45d4-4f0a-ba38-eec4576c5c29-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 32, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":648,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000068', 'Falken Ziex CT50 A/S All Season Tire', 'falken-ziex-ct50-a-s-all-season-tire', 'Performance winter traction. Ice braking capability. Winter driving confidence. Highway Rated', 463.99, NULL, '3086339P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3086339/falken-ziex-ct50-a-s-245-50r20-102v-59000020--6dee53f5-b733-4ad8-9811-10fd6327be18-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Falken', true, 30, false, true, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":645,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000069', 'Yokohama ADVAN V105G Tire', 'yokohama-advan-v105g-tire', 'The ADVAN Sport V105 delivers an exceptional driving experience. Wider tread blocks on the outside of the tread enhance dry performance while the increased groove area on the inner portion maximizes wet performance. Variable pitch tread reduces pattern noise offering a quiet and comfortable ride', 486.99, NULL, '4088569P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088569/245-35r19-advan-v105g-110193356--1c3e4d7d-b0ea-46b5-9750-0c2072145aef-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 11, false, true, false, '{}', NULL, NULL, '{"width":225,"aspect_ratio":50,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":640,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000006a', 'Laufenn X FIT Van All-Season Tire for Truck, SUV & Van', 'laufenn-x-fit-van-all-season-tire-for-truck-suv-van', 'The Laufenn X Fit Van tire provides exceptional wet/dry handling and braking performance. Enhanced durability. Longer mileage. Long tread life. Wheels sold separately', 49.99, NULL, '5082246P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5082246/195-75r16-107-105r-hankook-x-fit-van-2020384--00885507-f10f-47af-ba89-ad5de85b5477-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Laufenn', true, 38, false, true, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":70,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":653,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000006b', 'Yokohama Avid S33B All Season Passenger & CUV Tires', 'yokohama-avid-s33b-all-season-passenger-cuv-tires', 'For drivers who want a combination of a smooth ride, good wear, durability. Branded with the M+S symbol, these tires are often used as Original Equipment (O.E.) on standard coupes, sedans and family vans. Made for all-season usage. All-season traction, including in light snow. Also usable on some entry-level pickup, crossover and sport utility vehicles', 49.99, NULL, '4088517P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088517/225-65r17-avid-s33b-110133510--0842bd56-5b8d-4b77-a008-3850e432e657-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 27, false, false, false, '{}', NULL, NULL, '{"width":215,"aspect_ratio":75,"rim_diameter":15,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":681,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000006c', 'Yokohama Advan A83A All Season Passenger & CUV Tires', 'yokohama-advan-a83a-all-season-passenger-cuv-tires', 'For drivers who want a combination of a smooth ride, good wear, durability along with all-season traction, including in light snow. Mud & Snow Rated. Made for all-season usage. Used as Original Equipment (O.E.) on standard coupes, sedans and family vans, as well as some entry-level pickup, crossover and sport utility vehicles', 364.99, NULL, '4088530P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088530/p225-45r19-advan-a83a-110183050--778210c0-945c-49bc-9bfa-aaa94cb25e75-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 30, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":639,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000006d', 'Bridgestone Dueler H/L 422 Plus All Season Tire for SUV, CUV & Minivans', 'bridgestone-dueler-h-l-422-plus-all-season-tire-for-suv-cuv-minivans', 'Long lasting tread with a 110,000 kilometre warranty. Full depth grooves help water evacuation throughout the life of the tire. Optimized tread pattern fights irregular wear. Optimized block design improves braking on wet roads', 319.99, NULL, '5085822P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5085822/245-70r17-110t-duele-70e79931-4a3a-417d-bc44-b119abbc09ba-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 23, false, false, true, '{}', NULL, NULL, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":683,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000006e', 'Goodyear Wrangler AT All Season Tire For Passenger & CUV', 'goodyear-wrangler-at-all-season-tire-for-passenger-cuv', 'Goodyear Wrangler AT Tire offers rugged strength, all-terrain traction and an economical tread design for pickup trucks. All-season tread design helps provide traction in a variety of conditions. Offer excellent on- and off-road traction.. Large tread blocks help provide a stable footprint and confident handling. Wheels sold separately', 335.99, NULL, '2083679P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/2083679/195-75r14-n-an-wrangler-at-740036515--86a6dbd6-47fb-45de-aabe-15d5fe4cbf81-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Goodyear', true, 12, false, true, false, '{}', 3.8182, 11, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":681,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-00000000006f', 'Bridgestone Dueler A/T D693 II Tire', 'bridgestone-dueler-a-t-d693-ii-tire', 'Deeper tread design ensures stability and traction on and off-road for light trucks and SUVs. Enhanced performance with reduced risk of hydroplaning due to GUTT II simulation straight grooves. Longer tire life due to deeper tread grooves. Independent tread blocks, zig-zag sipes & anti-slip shoulder grooves provide better grip and traction. Available in a variety of sizes', 349.99, NULL, '3081192P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/3080003/p215-70r16-99h-duele-000010--d1f7f035-70bf-48c1-9b51-d0cd07529361.png', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 17, false, true, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":669,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000070', 'Hankook Optimo H428 All Season Tire For Passenger & CUV', 'hankook-optimo-h428-all-season-tire-for-passenger-cuv', 'Hankook Optimo H428 Tire is a grand touring all-season tire designed for all-season traction and a smoother ride. Original equipment for Chevrolet Sonic. M+S rated. Wheels sold separately', 49.99, NULL, '2086007P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2086007/p195-65r15-89h-h428-1010108--b557544e-9b8b-4807-8e41-58eb85de4f60.png', 'a1000000-0000-0000-0000-000000000001', 'Hankook', true, 24, false, false, false, '{}', 2.5, 2, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":687,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000071', 'Kumho Winter Craft WP52 Tires Passenger & CUV', 'kumho-winter-craft-wp52-tires-passenger-cuv', 'Reinforced stable driving, traction performance and handling performance through center block stiffening design. With 3D sipe application, braking performance on snow covered roads, and grip force have been maximized. Offers improved tread life with an optimal block shape of 4 channel symmetric layout. Designed for exceptional winter handling with a directional tread designed to clear snow and water quickly', 327.99, NULL, '5080231P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5080231/p275-55r20-111t-kumho-crugen-ht51-2254133--36fe12cb-88de-4fe2-998c-5f502a047641-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Kumho', true, 18, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":693,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000072', 'Yokohama Avid S33D Tire', 'yokohama-avid-s33d-tire', 'Passenger all-season tires are for drivers who want a combination of a smooth ride, good wear, durability along with all-season traction, including in light snow. Passenger all-season tires branded with the M+S symbol are often used as Original Equipment (O.E.) on standard coupes, sedans and family vans, as well as some entry-level pickup, crossover and sport utility vehicles. Original Equipment', 189.99, NULL, '4088516P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088516/p195-65r15-avid-s33d-110133509--94e5b542-ccc9-4376-9247-368dca6b2c2a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 27, false, false, false, '{}', NULL, NULL, '{"width":225,"aspect_ratio":50,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":680,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000073', 'Yokohama AVID S30D Tire', 'yokohama-avid-s30d-tire', 'Passenger All-Season tires are for drivers who want a combination of a smooth ride and good wear. As well as durability along with all-season traction, including in light snow. Passenger All-Season tires branded with the M+S symbol are often used as Original Equipment (O.E.) on standard coupes, sedans and family vans, as well as some entry-level pickup, crossover and sport utility vehicles', 224.99, NULL, '4088550P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088550/p205-55r16-avid-s30d-110193238--94bb0007-9ddf-4917-90be-fad60c07b30d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 32, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":50,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":663,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000074', 'Yokohama Geolandar G91AV Tire', 'yokohama-geolandar-g91av-tire', 'Passenger All-Season tires are for drivers who want a combination of a smooth ride and good wear. As well as durability along with all-season traction, including in light snow. Passenger All-Season tires branded with the M+S symbol are often used as Original Equipment (O.E.) on standard coupes, sedans and family vans, as well as some entry-level pickup, crossover and sport utility vehicles', 273.99, NULL, '4088548P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088548/225-65r17-geolandar-g91av-110193235--3085e6ef-8e42-4725-b457-41f233633827-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 27, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":55,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":686,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000075', 'Yokohama Geolandar G056B Tire', 'yokohama-geolandar-g056b-tire', 'Passenger All-Season tires are for drivers who want a combination of a smooth ride and good wear. As well as durability along with all-season traction, including in light snow. Passenger All-Season tires branded with the M+S symbol are often used as Original Equipment (O.E.) on standard coupes, sedans and family vans, as well as some entry-level pickup, crossover and sport utility vehicles', 361.99, NULL, '4088556P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088556/p255-60r18-geolandar-g056b-110193258--14544021-50dc-4122-afdb-495b274bb8b3-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 38, false, true, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":45,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":669,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000076', 'Bridgestone Dueler H/L 400 MOE All Season  Tire for Passenger & CUV', 'bridgestone-dueler-h-l-400-moe-all-season-tire-for-passenger-cuv', 'A premium all-season tire designed for SUVs, CUVs, and light trucks. Designed to offer a longer tread life, thanks to its durable construction and advanced compound. Optimized tread blocks help to reduce road noise and provide a smooth and comfortable ride. Wheels sold separately. Mud & Snow Rated', 467.99, NULL, '3082328P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3082328/235-50r18-97h-dueler-bridgestone-003774--8406c0f1-ca77-42a3-b96e-f5de5d7ee389-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 37, false, true, false, '{}', NULL, NULL, '{"width":225,"aspect_ratio":75,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"All-Season","runflat":false,"treadwear":661,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000077', 'Yokohama ADVAN A11A Tire', 'yokohama-advan-a11a-tire', 'Superb levels of grip made possible by a unique tread compound. These original equipment YOKOHAMA tires have been designed, tested and tuned to the specific requirements set out by various manufacturers, to give you the best possible driving experience. Reduced noise levels provide a comfortable ride, Good levels of tire wear', 235.99, NULL, '4088536P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4088536/205-50r16-advan-a11a-110193207--ecfd6168-8aa7-4fc3-af40-ea78d2e1334e-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000001', 'Yokohama', true, 37, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":60,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":620,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":60000}'),
('b2000000-0000-0000-0000-000000000078', 'Bridgestone Dueler H/L 33 Tire', 'bridgestone-dueler-h-l-33-tire', 'All season Tire designed for light trucks. As found as Original Equipment on popular vehicles. Confident traction on wet and dry surfaces. Wheels sold separately', 49.99, NULL, '3082326P', '', 'a1000000-0000-0000-0000-000000000001', 'Bridgestone', true, 37, false, false, false, '{}', NULL, NULL, '{"width":215,"aspect_ratio":55,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"All-Season","runflat":false,"treadwear":669,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":60000}')
INSERT INTO public.products (id, name, slug, description, price, compare_at_price, sku, image_url, category_id, brand, in_stock, stock_quantity, featured, is_new, is_best_seller, tags, rating, review_count, specs) VALUES
('b2000000-0000-0000-0000-000000000079', 'Michelin X-Ice® SNOW Winter Tire For Passenger & CUV', 'michelin-x-ice-snow-winter-tire-for-passenger-cuv', 'MaxTouch tread technology maximizes road contact for superior traction and handling. Intelli-Grip technology resists hydroplaning and improves traction on snow, slush and ice. Tread design bites into ice and snow while maintaining flexibility in freezing temperatures for better grip. Designed for a quiet and comfortable ride with great fuel efficiency. Delivers longer tread life over leading competitors for increased value. Wheels sold separately', 49.99, NULL, '0052089P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0052089/-175-65r15-88t-michelin-x-ice-snow-86995--ae4efeae-20ad-435f-8f4e-e3b70fd45f7e-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Michelin', true, 31, false, true, false, '{}', 4.6638, 2112, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":431,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-00000000007a', 'Dynamo DW702 Non-Studdable Winter Tire for Passenger & CUV', 'dynamo-dw702-non-studdable-winter-tire-for-passenger-cuv', 'Tread pattern is made with 100% silica compound for consistent performance in winter weather. Variable pitch design and increased number of lateral grooves and sipes provide greater performance on wet and snowy roads. Tread features optimized pitch sequence and profile that reduces wheel vibrations for fewer noise emissions, even tread wear, and improved steering response. Non-studdable', 49.99, NULL, '0051044P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0061201/-205-55r16-94h-dynamo-dw702-d77080f6-3c07-449a-b8dc-58eb75c2e342-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Dynamo', true, 35, false, false, true, '{}', 4.3235, 102, '{"width":275,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":441,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000007b', 'Bridgestone Blizzak WS90 Winter Tire For Passenger & CUV', 'bridgestone-blizzak-ws90-winter-tire-for-passenger-cuv', 'Confident stopping power on snow and ice. Wheels sold separately. Improved tread pattern featuring 15% more block edges over the Blizzak WS80, the Blizzak WS90 takes wet, snowy and icy performance to the next level. On-off road rating: Highway. 30% more block stiffness in tread pattern for an extra season of wear. Sidewall styling: Blackwall', 49.99, NULL, '4087940P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4087940/245-40r18xl-97h-brs-blizzak-ws90-001116--915a6400-7b5d-44db-90b5-ed6eba326e4c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 38, false, false, false, '{}', 4.643, 479, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":407,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000007c', 'Firestone Winterforce CV Tire for Passenger & CUV', 'firestone-winterforce-cv-tire-for-passenger-cuv', 'Firestone Winterforce CV Tire for Passenger & CUV is certified with the 3-Peak Mountain Snowflake designation with its special cold weather compound and open shoulder slots. Tread design gives you better grip in wintry conditions. Wheels sold separately. Full depth grooveshelp evacuation in deep water and slush. Zig zag sawtooth sipes provide biting edges in snow while maintaining block stiffness. High sipe density biting edges provide additional traction in snow, wet and ice conditions', 256.99, NULL, '4087720P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4087720/-225-75r16c-121r-firestone-winterforce-cv-011490--14d08803-2678-4976-99ab-f9d942fc8180-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Firestone', true, 14, false, false, false, '{}', 5, 1, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":447,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-00000000007d', 'Continental UltimateContact Winter for Passenger & CUV', 'continental-ultimatecontact-winter-for-passenger-cuv', 'Polar plus technology keeps tread compound pliable in cold weather conditions. EV compatible marking with a focus on the needs of electric vehicles while covering all vehicle requirements. 3 peak mountain snowflake for use in severe winter conditions. Wheels sold separately. Silane additive to the rubber improves grip in all road conditions', 49.99, NULL, '0059510P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0059510/-185-65r15-92t-xl-ultimatecontact-winter-03456160000--11dc76f2-5d68-48a4-af46-c1409d6b62b7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 34, false, false, false, '{}', 4.4406, 143, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":457,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000007e', 'Certified WinterTrek Studdable Tire for Passenger & CUV', 'certified-wintertrek-studdable-tire-for-passenger-cuv', 'Winter tread formula allows the tire to maintain elasticity for improved grip in extreme cold weather conditions. Studdable tire features a directional tread pattern and sipe design to greatly improve snow, slush, and water drainage. Stud pattern has been arranged in a calculated variable sequence, along with a new stud hold and pad design that provides maximum grip on ice. Wheels sold separately. Durable construction for long-lasting use', 49.99, NULL, '0031702P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0031702/-155-80r13-79t-certified-wintertrek-ca853d0f-b87b-4f1d-a1bf-09102fb3ef26-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Certified', true, 10, false, true, false, '{}', 4.4603, 680, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":499,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000007f', 'MotoMaster Winter Edge II Tire For Passenger & CUV', 'motomaster-winter-edge-ii-tire-for-passenger-cuv', 'Leader in snow performance with our top marks in the road rated testing program. The optimized soft compound maximizes contact area and provides better grip on icy and snowy roads. With Winter Traction Technology (WTT). Provides superior control stability and minimizes block movement for excellent handling performance. Grip in step shoulder design prevents snow accumulation while braking or accelerating. 3PMSF certified indicates a winter tire that can handle snowy and slippery roads, as well as low temperatures, and meets the minimum requirements for providing snow traction. Directional design and spiral booster structure. Prevents hydroplaning by draining snow and water. Ensures enhanced acceleration. Wheels sold separately', 49.99, NULL, '0044907P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0044907/-175-70r14-t-motomaster-winter-edge-ii-19fbf985-4dcb-4df2-ae4e-84c8551f167c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'MotoMaster', true, 38, false, false, false, '{}', 4.5162, 554, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":452,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000080', 'Bridgestone Blizzak DM V2 Winter Tire for Truck & SUV', 'bridgestone-blizzak-dm-v2-winter-tire-for-truck-suv', 'Engineered for many popular SUVs, CUVs and light trucks on the road today. Delivers improved grip and braking power for increased performance on snow and ice. Optimized contact patch allows greater contact between tire and road surface for increased control in winter conditions. Proprietary multicell compound sheds water from tire surface for solid braking on ice. Aggressive block edges help the tire grip the snow for better traction. Advanced hydrophilic coating helps channel away water reducing the risk of hydroplaning. Wheels sold separately', 49.99, NULL, '3083276P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0069540/-215-70r16-100s-bliz-bridgestone-015828--42d3a2c8-8a6c-4721-bdff-ea517a64d928-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 24, false, false, false, '{}', 4.7812, 393, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":497,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000081', 'Michelin X-Ice® SNOW SUV Winter Tire For Truck & SUV', 'michelin-x-ice-snow-suv-winter-tire-for-truck-suv', 'Michelin X-Ice® SNOW SUV is a winter tire designed for maximum mobility and safety– not just when it’s new, but for seasons to come. WINTER GRIP MADE TO LAST - Long-lasting SNOW performance, excellent snow braking, and improved snow performance. Long-lasting ICE performance, leadership in ice braking. Improved hydroplaning and slush performance. EXCELLENCE IN LONGEVITY - Lasts up to one additional winter than the average of leading competitors. DISCLAIMER: The MICHELIN® X-Ice® SNOW replaces the MICHELIN® X-Ice® Xi3TM and MICHELIN® Latitude® X-Ice® Xi2 TM and is NOT MIXABLE in any combination on the vehicle with any previous X-Ice product line.. Wheels sold separately', 49.99, NULL, '0062176P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0062176/-215-70r16-100t-michelin-x-ice-snow-suv-85800--02c16d51-81cb-48fa-896f-c1ad2af9b294-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Michelin', true, 28, false, false, false, '{}', 4.6996, 1771, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":447,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
