('b2000000-0000-0000-0000-000000000083', 'Continental VikingContact™ 7 Winter Tire for Passenger & CUV', 'continental-vikingcontact-7-winter-tire-for-passenger-cuv', 'Superb grip performance on wintry and wet surfaces. Perfect tracking stability under all wintry conditions. Powerful traction and braking on icy and snowy roads. Wheels sold separately', 49.99, NULL, '4085784P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4085836/205-55r17-95t-vikingcontact-7-03449950000--7d000f23-1d61-4181-8875-e274ec3e87f5-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 34, false, true, false, '{}', 4.4062, 32, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":407,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000084', 'General Altimax Arctic 12 Studdable Winter Tire For Passenger & CUV', 'general-altimax-arctic-12-studdable-winter-tire-for-passenger-cuv', 'An interwoven centre tread with straight siping provides a rigid structure for great steering response and stable dry handling in low winter temperatures. The directional tread design offers exceptional water evacuation and hydroplaning resistance for excellent wet and snow performance. Tire will accept studs for additional winter grip; check with your local store on provincial regulations regarding the use of studs. Multi-angle block edges allows the tire to have gripping edges in all directions for additional lateral traction and maneuverability in snow and ice. Wheels sold separately. Studs sold separately', 49.99, NULL, '4082446P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0051043/-175-65r15-88t-general-altimax-arctic-12-15503110000--b94a4ae5-0899-4e3a-b2b6-358d97ca23cc-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'General Tire', true, 33, false, false, false, '{}', 4.4969, 163, '{"width":255,"aspect_ratio":70,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":415,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000085', 'Firestone Winterforce 2 UV Studdable Tire For Truck & SUV', 'firestone-winterforce-2-uv-studdable-tire-for-truck-suv', 'Winter tire built for pickup trucks, CUV''s, and SUV''s. Certified with the 3-Peak Mountain Snowflake designation. Full depth tread features provides long-lasting performance winter after winter. Wheels sold separately. Special cold weather compound, open shoulder slots, and tread design give you better grip in wintry conditions', 49.99, NULL, '3083652P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3083652/-p265-75r15-112s-wint-firestone-148606--07197f7b-67a1-4660-8133-8216b229a3fd-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Firestone', true, 30, false, true, false, '{}', 4.4, 35, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":475,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
