('b2000000-0000-0000-0000-000000000087', 'Laufenn I FIT Ice Studdable Winter Tire For Passenger & CUV', 'laufenn-i-fit-ice-studdable-winter-tire-for-passenger-cuv', 'Laufenn I FIT Ice is a studdable winter tire that provides dependable performance in snowy and icy road conditions. Advanced stud technology design. Snow slit design. 3D kerf design. Claw edge. Excellent braking on icy surfaces. Enhanced braking and traction in snow and ice conditions. Enhanced handling on snow surfaces. Maximized snow traction. Wheels sold separately', 49.99, NULL, '4089630P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4089630/175-65r14-82t-i-fit-ice-1020071--e7bc1b29-2931-4297-b132-b533d7c7013e-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Laufenn', true, 22, false, false, false, '{}', 1.8, 5, '{"width":275,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":458,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-000000000088', 'Firestone Winterforce 2 Studdable Tire For Passenger & CUV', 'firestone-winterforce-2-studdable-tire-for-passenger-cuv', 'Built for coupes, sedans, wagons and minivans. This tire is certified with the 3-Peak Mountain Snowflake designation. Built with full depth tread features to help give you long-lasting performance winter after winter. Wheels sold separately. Special cold weather compound, open shoulder slots, and tread design give you better grip in wintry conditions', 49.99, NULL, '3083653P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3083653/-185-60r15-84s-winter-firestone-148827--b0a368ec-4c51-4f06-a974-0bec7364aa9c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Firestone', true, 27, false, false, false, '{}', 3.9583, 48, '{"width":265,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":415,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-000000000089', 'Yokohama IceGuard G075 Winter Tire For Passenger & CUV', 'yokohama-iceguard-g075-winter-tire-for-passenger-cuv', 'Designed to deliver strong winter performance for SUVs and crossovers. New directional tread pattern increases contact area providing superior grip on surfaces with snow and ice. Triple 3D sipes enhance stability for optimal winter performance. High-density compound improves overall road contact resulting in longer, more even wear. Advanced low-heat generating under-tread compound increases stability and lowers fuel consumption. Wheels sold separately', 492.99, NULL, '4087451P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4087451/215-70r16-100t-g075-110175100--596f1329-aea7-4878-8d70-a80e53ebd984-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Yokohama', true, 16, false, false, false, '{}', 4.5909, 88, '{"width":235,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":454,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000008a', 'Cooper Discoverer True North Winter Tire For Passenger & CUV', 'cooper-discoverer-true-north-winter-tire-for-passenger-cuv', 'High wet traction for slush-covered roads. Maintains excellent grip on ice and snow. Snow Groove technology with saw-tooth patterns for enhanced snow traction. Coupled silica compound tread for improved ice traction without stud pins. Wheels sold separately', 49.99, NULL, '4084092P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/4084117/265-65r18-114t-discoverer-true-north-90000032426--315da3a6-6299-4c99-89ab-85304f7d8c66-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Cooper Tires', true, 11, false, false, false, '{}', 4.2812, 32, '{"width":255,"aspect_ratio":70,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":423,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000008b', 'BFGoodrich Winter T/A KSI Tire For Passenger & CUV', 'bfgoodrich-winter-t-a-ksi-tire-for-passenger-cuv', 'Better control in winter, whatever the road conditions - wet, snow or ice. Features a new compound which is optimized with more silica for grip in sub-freezing temperatures with stability on warmer winter days. High sipe density with saw toothed groove edges and interlocking 3D sipes maximizes the amount of biting edges and increases the stability of shoulder blocks for snow and ice grip. Serrated shoulder profile provides additional grip in deep snow. Wheels sold separately', 49.99, NULL, '4082231P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4082231/-175-70r14-84t-bfg-winter-t-a-ksi-18359--6e9b51fb-f6b9-4b2e-9415-9f3315509e45-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'BFGoodrich', true, 30, false, false, false, '{}', 4.2934, 242, '{"width":255,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":436,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-00000000008c', 'Firestone Winterforce LT Tire For Truck & SUV', 'firestone-winterforce-lt-tire-for-truck-suv', 'A standout truck tire built for winter performance. High sipe density biting edges provide additional traction in snow, wet and ice conditions. Directional tread design pattern provides dependable traction on snow. Stud pins help promote solid ice traction when installed with optional studs. Pinned for #15 studs to provide extra grip for winter driving. Wheels sold separately', 49.99, NULL, '3082168P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3082175/lt245-75r17-10-118r-246335--f59f6473-80e3-4cb1-ae59-e2fd9506c634-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Firestone', true, 38, false, false, false, '{}', 4.1429, 42, '{"width":275,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":420,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000008d', 'Michelin X-Ice® North 4 Studded Winter Tire For Passenger & CUV', 'michelin-x-ice-north-4-studded-winter-tire-for-passenger-cuv', 'Made for exceptional control in severe Canadian winter conditions. Improved hydroplaning and slush performance. Ultimate snow and ice confidence. Wheels sold separately. Long lasting winter tread. Supported by the Michelin Promise Plan of a 60-day satisfaction guarantee, roadside assistance, and a 6 years standard limited warranty', 49.99, NULL, '3086507P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0080866/-michelin-x-ice-north-4-195-60r15-78169--ce76eedb-9bbc-4169-8f86-51a28b65470f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Michelin', true, 13, false, false, true, '{}', 4.5833, 60, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":446,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-00000000008e', 'Cooper Evolution Studdable Winter Tire For Passenger & CUV', 'cooper-evolution-studdable-winter-tire-for-passenger-cuv', 'Cooper Evolution Winter Tire provides stability and confidence when driving through deep snow. Tre is known to plow through snow, it is also a studdable tire for extremely icy conditions. Designed with the "Sawtooth Circumferential Center Rib" which allows it to have wide contact with the center rib and enhances stability in all weather conditions. Also designed with multi-angle sipe position which enhances ice and wet grip. Features "Snow Groove Technology" with biting edges that traps snow in the tread to provide superior snow-on-snow traction. Studdable holes are strategically placed in order to improve performance when going through extreme icy conditions. Wheels sold separately', 269.99, NULL, '4084124P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4084165/235-55r17-99h-evolution-winter-90000029790--4f4f80b0-1581-40f9-9395-500b892c7517-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Cooper Tires', true, 25, false, false, false, '{}', 4.5, 58, '{"width":225,"aspect_ratio":75,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":477,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000008f', 'GT Radial Champiro WinterPro HP Tire For Passenger & CUV', 'gt-radial-champiro-winterpro-hp-tire-for-passenger-cuv', 'GT Radial Champiro WinterPro HP Tire provides the handling and precision demanded by owners of ultra high performance sports cars, sedans, or coupes during winter conditions. Asymmetric Tread Design: Provides excellent performance during the varied winter conditions. Unique Lateral Cross-Cut Groove: Effectively disperses water and slush and provides more biting angles for improved snow and ice grip. Sunflower Oil Enriched Compound: Increases low temperature traction for improved wet braking and handling, and better snow performance. Wheels sold separately', 49.99, NULL, '3085353P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3085353/-215-60r16xl-99h-gtr-champiro-winterpro-bw-a526--df282308-ca9f-4636-9a24-d5fd6b9b7217-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Giti', true, 26, false, true, false, '{}', 4.6667, 3, '{"width":235,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":467,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000090', 'Goodyear WinterCommand Tire For Passenger & CUV', 'goodyear-wintercommand-tire-for-passenger-cuv', 'Tread patterns with multiple biting edges specially designed for your vehicle help provide starting and stopping power on snow covered roads. Winter Tread Compound maintains flexibility and offers consistent and confident grip at low temperatures. Full-depth zigzag sipes enhance snow and ice grip throughout the life of the tire. Wheels sold separately', 49.99, NULL, '0052094P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0052094/-p195-65r15-91t-goodyear-wintercommand-a13ce521-ef63-4b9a-9c75-8e8485449083-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 37, false, false, false, '{}', 4.5242, 124, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":422,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-000000000091', 'Continental VikingContact 8 Winter Tire For Passenger & CUV', 'continental-vikingcontact-8-winter-tire-for-passenger-cuv', 'Delivers excellent performance in unpredictable winter conditions, thanks to its advanced tread design featuring 3D-sipes, snow edges, and three-layer sipes in the shoulder area. Next-generation Nordic compound technology ensures reliable grip and flexibility across a wide range of winter temperatures, whether it''s icy, snowy, or slushy. The tire’s energy-efficient construction reduces rolling resistance, which helps to improve fuel efficiency and extend battery range, especially important for electric and hybrid vehicles. Tread compound minimizes tire deformation, resulting in significantly less energy loss when driving. An enhanced pattern concept reduces road noise by optimizing the interaction between the tire footprint and lateral grooves, offering a quieter, more comfortable ride. Wheels sold separately', 49.99, NULL, '5087072P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5087079/-235-55r20-105h-xl-continental-vikingcontact-8-03457570000--5335a25d-2417-4be7-bf9e-74201ceb5e6f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 21, false, false, false, '{}', 5, 8, '{"width":285,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":485,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000092', 'Cooper Discoverer Snow Claw Winter Tire For Truck & SUV', 'cooper-discoverer-snow-claw-winter-tire-for-truck-suv', 'Best suited for light trucks and SUVs. Three-Peak Mountain Snowflake (3PMSF) symbol on the tire’s sidewall indicates it’s approved for severe snow and winter weather use. Elastic and soft tread compound allows the tire to maintain consistent performance in extreme cold. Mud & Snow (M+S) rated tire. Wheels sold separately', 49.99, NULL, '3086563P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3086563/265-70r17-115t-snow-claw-80598c2c-6fc4-4fd2-9462-36e2a2d2cded-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Cooper Tires', true, 20, false, false, false, '{}', 4.3667, 30, '{"width":245,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":408,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-000000000093', 'Yokohama iceGuard iG53 Winter Tire For Passenger & CUV', 'yokohama-iceguard-ig53-winter-tire-for-passenger-cuv', 'Yokohama iceGuard iG53 Tire with micro diagonal grooves that deliver optimum ice performance even without a break-in period. Absorptive Tread Compound prevents micro-hydroplaning by removing the water layer from the tire surface area and keep the car connected with the road. 3D sipes avoid uneven deflection of blocks by supporting each other. Delivers excellent ice and snow performance with its maximized actual contact area. Wheels sold separately', 49.99, NULL, '4087536P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4087557/235-55r17-99h-ig53-110115341--a6f330af-9524-40aa-b6a7-62a48ad53d42-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Yokohama', true, 26, false, false, false, '{}', 4.6711, 76, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":477,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000094', 'Pirelli Cinturato Winter WTC2 Tire for Passenger & CUV', 'pirelli-cinturato-winter-wtc2-tire-for-passenger-cuv', 'Premium winter tire for modern sedans, coupes, and CUVs. Interlocking 3D sipes with straight design for increased grip on snow with great improvement in braking performances in all conditions. Staggered V-shaped design with variable grooves'' design for improved snow and aquaplaning performance. Wider and drafted on the shoulder, narrower in the center to enhance handling and reduce aquaplaning. High mileage combined to high level performance in wet and snow conditions. Main grooves chamfers provide second flow for water evacuation to reduce aquaplaning. Wheels sold separately', 49.99, NULL, '5085593P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5085593/-235-45r18-98h-pirelli-cinturato-winter-wtc2-4097100--f6239444-bb51-42a4-9367-b5c9abff0e8e-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 31, false, false, true, '{}', NULL, NULL, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":448,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000095', 'Hankook I Fit Ice Tire', 'hankook-i-fit-ice-tire', 'The winter studdable ‘I FIT Ice’ provides improved safety and comfort in snow and ice covered road conditions. Enhanced braking and traction in snow and ice conditions. Reduced road noise and comfortable ride', 118.99, NULL, '2087170P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2087170/-hankook-i-fit-ice-175-65r14t-xl-1020287--31a8ec75-6c2e-47c5-a257-991f903cc747-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Laufenn', true, 17, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":35,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":423,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-000000000096', 'Bridgestone Blizzak 6 Winter Tire for Passenger & CUV', 'bridgestone-blizzak-6-winter-tire-for-passenger-cuv', '3-peak mountain snowflake certified for excellent winter traction and stopping power. Engineered for precision handling in snow. Advanced tread compound for extended mileage. ENLITEN technology optimizes this tire for electric vehicle compatibility', 49.99, NULL, '5087322P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5087322/-205-55r17-95v-bridgestone-blizzak-6-014611--c5c77854-cc35-4c4a-b39a-3fbc6d4701a3-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 11, false, false, false, '{}', 5, 2, '{"width":265,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":473,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000097', 'MotoMaster Winter Edge HD Tire for Truck & SUV', 'motomaster-winter-edge-hd-tire-for-truck-suv', 'Provides advanced winter performance on ice through the innovative silica tread compound and increased rubber-to-road contact surface. Snow grooves deliver excellent snow braking and acceleration. Solid centre rib and overall construction of the Winter Edge HD improve handling, especially when the vehicle is loaded or towing. Wheels sold separately. Road rated 88.7 overall: ice traction 74/100, snow traction 91.8/100, wet traction 100/100, dry traction 100/100, comfort/road noise 100/100, fuel economy 93.5/100. 96,000 km mileage rating, one of the highest available on a winter tire for trucks and SUVs. Load range E, 10-PLY construction with load index 121/119 (single/dual) for heavier loads, towing, and hauling. Snow peak rated (3PMSF) and M+S certified for severe weather conditions. Accepts studs for additional mechanical traction on icy surfaces. The silica tread compound maintains flexibility in extreme cold, increasing the contact area between tire and road for shorter stopping distances on ice', 49.99, NULL, '0061082P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0061082/-lt245-75r16-120-116r-motomaster-winter-edge-hd-330021003--ab9d6d51-6fe8-4eb5-bbfd-0ed4ccd057ae-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'MotoMaster', true, 33, false, false, false, '{}', 4, 35, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":465,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000098', 'Pirelli Ice Friction Snow/Winter Tire for Passenger & CUV', 'pirelli-ice-friction-snow-winter-tire-for-passenger-cuv', 'Wider working range for both ice and wet grip performance, while also enhancing Rolling Resistance. Ensures great Ice braking performance while maintaining excellent levels of comfort and mileage. Great aquaplaning and wet braking performance thanks to its high water evacuation capability. Enhanced snow traction performance. Enhanced snow braking performance. Wheels sold seperately', 49.99, NULL, '5087668P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5087668/-ev235-55r19-105h-xl-1806bac6-8605-4059-bd7b-7ecbb77ae712-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 14, false, true, false, '{}', 4, 1, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":406,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-000000000099', 'Hankook Winter i*cept evo2 SUV Winter Tire for Passenger & CUV', 'hankook-winter-i-cept-evo2-suv-winter-tire-for-passenger-cuv', 'Ultra-high performance winter tire designed to provide great performance in winter driving condition. Increased pitch numbers help effectively bite into the snow and improve the traction performance of the tires. Snow-pick traction groove which is made up of lateral ice ax shaped grooves. Have a scratching effect on roads which provides impressive performance on snow. Wheels sold separately', 49.99, NULL, '2086976P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2086976/-hankook-winter-i-cept-evo2-suv-215-65r17h-1022607--4215119e-91d1-49b4-adc9-677ca767f049-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 34, false, true, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":407,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000009a', 'Uniroyal Tiger Paw Ice & Snow 3 Winter Tire For Passenger & CUV', 'uniroyal-tiger-paw-ice-snow-3-winter-tire-for-passenger-cuv', 'Uniroyal Tiger Paw Ice & Snow 3 winter passenger Tire is molded for studs to enhance ice traction. Innovative winter compound technology improves grip in cold weather. 3D interlocking shoulder sipes stabilize tread blocks for improved handling and cornering performance. Patented DuraShield construction offer durability and reliability on wintery roads. Wheels sold separately', 49.99, NULL, '4080752P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4080752/-205-70r15-96t-uniroyal-tiger-paw-ice-snow-3-98443--1761eb22-a4e2-4fcb-ba2e-d78f20aced69-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Uniroyal', true, 23, false, false, false, '{}', 4.6667, 21, '{"width":245,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":440,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000009b', 'Goodyear WinterCommand SUV Winter Tire', 'goodyear-wintercommand-suv-winter-tire', 'Tread patterns with multiple biting edges specially designed for your vehicle help provide starting and stopping power on snow-covered roads. Winter Tread Compound maintains flexibility and offers consistent and confident grip at low temperatures. Full-depth zigzag sipes enhance snow and ice grip throughout the life of the tire. Wheels sold separately. Unidirectional tread pattern is perfect for efficient and fast evacuation of water and slush, thus eliminating the risk of hydroplaning. Studdable where permitted by law', 289.99, NULL, '4087763P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4087764/-265-70r16-112s-wintercommand-suv-132204788--ca1b94ee-a3e1-4234-8c87-b7980b7c74ac-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 12, false, false, false, '{}', 4.75, 20, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":411,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000009c', 'Pirelli Scorpion Winter 2 Performance Tire', 'pirelli-scorpion-winter-2-performance-tire', 'Staggered V-shape design for excellent performance on snow. Continuous edge from shoulder to shoulder. Optimized variable grooves for outstanding wet performance.. Wider and drafted on the shoulder and narrower in the center. Main groove chamfers for optimized aquaplaning performance. Additional flow for water evacuation. Brilliant braking performance on snow, wet, dry and excellent mileage. 3D-Sipe interlocking system and uniform block stiffness distribution', 49.99, NULL, '5081389P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5082453/-ev-245-45r20-103v-pirelli-scorpion-winter-2-4137800--8414cbff-e574-4c69-a8fd-61048a3506ec-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 10, false, false, false, '{}', 5, 1, '{"width":235,"aspect_ratio":55,"rim_diameter":17,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":411,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000009d', 'Yokohama GEOLANDAR I/T G072 Winter Tire For Passenger & CUV', 'yokohama-geolandar-i-t-g072-winter-tire-for-passenger-cuv', 'Yokohama GEOLANDAR I/T G072 sets a new standard for light truck and SUV performance in grueling winter weather conditions. Absorptive carbon flakes and resin-coated shelled microbubbles cut through the watery film and hugs icy surfaces with no holds barred. GO72 offers all the confidence you need to take on the most challenging terrain in snowy, icy situations. Offers exceptional handling and outstanding durability, even when the going gets tough. Wheels sold separately', 343.99, NULL, '4087334P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/4087334/p245-60r20-107r-gl-i-t-g072-110107240--f93b8f2a-91bc-4e46-855c-a4899c62c832-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Yokohama', true, 23, false, true, false, '{}', 5, 1, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":405,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000009e', 'Continental ContiWinterContact TS830 P Tire For Passenger & CUV', 'continental-contiwintercontact-ts830-p-tire-for-passenger-cuv', 'Designed for extreme braking manoeuvrability. Outstanding braking performance on icy and wet roads. Optimized for driving safety systems. Wheels sold separately', 328.99, NULL, '2083122P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4085775/225-50r17-94h-contiwintercontact-ts-830-p-03534640000--f1c1f0c0-c932-4f71-9d6b-06cfb8a6cafe-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 21, false, true, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":475,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-00000000009f', 'Bridgestone LM25 4x4 MOE Tire', 'bridgestone-lm25-4x4-moe-tire', 'The Bridgestone Blizzak LM-25 RFT is a winter tire engineered for drivers of performance sedans and coupes originally equipped with run-flat tires. Delivers impressive grip and control and provides dependable cornering and handling on wet, dry, icy, slushy and snowy roads. Branded with the three-peak mountain snowflake (3PMSF) symbol. Wheels sold separately', 488.99, NULL, '3081165P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3081165/-255-50r19xl-107h-bli-127305--9284e4ea-2ee2-441a-bc52-2aba44be4bfb-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 38, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":50,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":464,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000a0', 'Michelin Latitude Alpin Winter Tire For Passenger & CUV', 'michelin-latitude-alpin-winter-tire-for-passenger-cuv', 'Offers deep snow traction provided by the lug shoulder edge, step groove, and longitudinal zigzag grooves, which create grip on snow. Bi-Directional-Sipes are self-locking sipes that allow more biting density in snow and ice without compromising dry handling. Michelin Comfort Control Technology™ reduces vibrations and road noise through computer-optimized design and precision manufacturing. StabiliGrip Technology™ with variable geometry sipes provides enhanced stability at higher speeds. Wheels sold separately', 49.99, NULL, '0080557P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2080976/-255-55r18-109v-michelin-latitude-alpin-59395--4b7829e5-2c41-4679-9141-18ea3cefd13f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Michelin', true, 15, false, false, false, '{}', 4.5152, 33, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":422,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000a1', 'Bridgestone Blizzak LM80 RFT Winter Tire For Passenger & CUV', 'bridgestone-blizzak-lm80-rft-winter-tire-for-passenger-cuv', 'Run Flat Tire (RFT) technology with reinforced sidewalls keeps your vehicle travelling under control after a puncture. Advanced winter tread compound that remains pliable in cold temperatures to enhance traction in snow and on ice. High volume grooves remove water and slush from the contact patch. Wheels sold separately. Lug tread design and rigid shoulder blocks enhance the tire’s cornering and braking', 302.99, NULL, '3082587P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3082587/-p225-65r17-100h-bliz-bridgestone-000646--dda1246e-8b83-43bb-80dd-e6b1380d4969-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 17, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":498,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000a2', 'Continental ContiCrossContact Winter Tire For Passenger & CUV', 'continental-conticrosscontact-winter-tire-for-passenger-cuv', 'A dedicated Continental ContiCrossContact Winter Tire for fast, heavy all-wheel drive vehicles. Due to the optimized sipe concept with progressive sinus sipes, the stable outer shoulder guarantees outstanding characteristics on dry roads. Advanced silica compound with patented polymer type and strongly siped block design for excellent traction and braking performance. Outstanding driving characteristics on dry roads by stable outer shoulder thanks to optimised sipe concept with progressive sinus sipes. High aquaplaning safety due to wide circumferential tread grooves for draining and flow optimised pattern carvings on the outer shoulder. Wheels sold separately', 49.99, NULL, '0087458P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0080446/235-60r17-102h-conticrosscontactwinter-03540290000--9cf2fd07-539e-4b17-a651-08c1fbd6216f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 30, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":494,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000a3', 'Hankook i*Pike LT Winter Tire For Passenger & CUV', 'hankook-i-pike-lt-winter-tire-for-passenger-cuv', 'Hankook i*Pike LT is a premium winter SUV and light truck Tire. An intelligent tire design that employs 3D grooves to improve snow traction. Six rows of stud pins play a decisive role in increasing snow and ice performance. Aggressive 2-in-1 tire block lowers the degree of wear. Wide lateral groove maximizes snow traction performance. Wheels sold separately', 49.99, NULL, '4080349P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4080349/235-65r16-121-119r-rw09-winter-i-pike-lt-2020514--4a9c70bb-60e6-49a5-a644-605facb5c45c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 36, false, false, false, '{}', 5, 2, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":452,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
