('b2000000-0000-0000-0000-0000000000a5', 'Bridgestone Blizzak LM-80 EVO Winter Tire for Passenger & CUV', 'bridgestone-blizzak-lm-80-evo-winter-tire-for-passenger-cuv', 'Designed for SUVs and 4x4s. Excellent handling on snowy and slushy roads. Superior traction and stability in winter. Wide grooves help prevent aquaplaning. Wheels are sold separately', 49.99, NULL, '4086506P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4086506/-235-60r18-103h-bridgestone-blizzak-lm-80-evo-012434--4504b527-1c21-47be-ba58-f25155cfa2ba-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 28, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":478,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000a6', 'Yokohoma BluEarth V905 Winter Tire For Passenger & CUV', 'yokohoma-bluearth-v905-winter-tire-for-passenger-cuv', 'Wide slanting grooves and a directional tread pattern provide excellent drainage to combat hydroplaning. Triple 3D sipes create more biting edges for better performance on slick surfaces. Increased edge effect and all-new compound keeps your car ready to grip the winter roads. Wheels sold separately', 49.99, NULL, '4087135P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4087136/215-55r16-97v-xl-bluearth-v905-110190602--e3402e24-efd0-4d1d-935b-3324edafaa7d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Yokohama', true, 31, false, false, true, '{}', 4.75, 4, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":435,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000a7', 'Kumho WinterCraft Ice Wi31 Tire', 'kumho-wintercraft-ice-wi31-tire', 'Kumho WinterCraft Wi31 offers excellent braking and acceleration on ice. An exceptionally quiet tire. Engineered for cold traction with a high dispersion compound. Wheels sold separately. Studdable', 49.99, NULL, '3084513P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3084510/-155-80-r13-q04l-wintercraft-wi31-2167113--2b3b9bce-8448-4bbc-aade-4c1dea0e6269-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Kumho', true, 17, false, true, false, '{}', 5, 3, '{"width":255,"aspect_ratio":35,"rim_diameter":19,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":444,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000a8', 'Pirelli Scorpion Winter Tire for Passenger & CUV', 'pirelli-scorpion-winter-tire-for-passenger-cuv', 'Pirelli Scorpion Winter Tire is designed with a modular block layout to improve handling on snow surfaces, and reduce the braking distance in all weather conditions. Circumferential grooves improve water expulsion to deliver excellent wet handling and wet braking performance. Newly designed mould profile provides an optimized footprint area to deliver progressive and responsive handling in dry conditions. New tread pattern compound delivers maximum grip both on snow and wet road conditions. Wheels sold separately', 49.99, NULL, '2084472P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5081389/-245-45r21-104v-pirelli-scorpion-winter-2-4138900--1f23d9ae-95ff-41a2-9ed5-c50f1ab479f9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 33, false, false, false, '{}', 4.4444, 9, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":404,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000a9', 'Pirelli Sottozero 3 Winter Tire For Passenger & CUV', 'pirelli-sottozero-3-winter-tire-for-passenger-cuv', 'The Pirelli Winter Sottozero 3 Tire is Pirelli''s newest Sottozero performance winter tire developed for high performance vehicles. The directional double arrow pattern design increases the number of blocks which provide a higher traction in snowy conditions. The optimized compound provides a consistent grip throughout a wider working temperature range that provides better grip in all winter weather conditions. Wheels sold separately', 49.99, NULL, '4080593P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4086618/-ev-235-45r18-98v-xl-pirelli-winter-sottozero-3-2aad19b2-dc70-4177-b089-041be4a10fe7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 21, false, false, false, '{}', 4, 8, '{"width":265,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":438,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000aa', 'Bridgestone Blizzak W965 Winter Tire For Truck & SUV', 'bridgestone-blizzak-w965-winter-tire-for-truck-suv', 'Advanced winter tire. Features aggressive tread blocks which help improve snow traction for commercial use. Multi-Cell compound technology - Uses microscopic pores to remove water. Wheels sold separately', 49.99, NULL, '3081475P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3081475/lt215-85r16-10-115q-150770--80544570-742f-4582-8f25-246695dc900e-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 10, false, false, false, '{}', 4.3239, 71, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":465,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000ab', 'Pirelli Scorpion™ Ice & Snow Winter Tire For Truck & SUV', 'pirelli-scorpion-ice-snow-winter-tire-for-truck-suv', 'Designed to provide optimal performance on snow and ice for light trucks and SUVs. Designed for rough winters, but versatile enough for all road conditions. Specialized tread design for optimum traction and short braking distances on snow, which result in excellent winter road conditions with low noise levels. Four broad longitudinal grooves which is excellent for water expulsion, and optimum traction on snow and downhill driving. Robust off-road carcass design for high stability and strength which results in controlled responses and increased handling. Wheels sold separately', 49.99, NULL, '0087970P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4083771/195-65r15-91h-sl-as-110489545--f6dc8b9e-f77c-440f-9c29-7ba19617fefc-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 20, false, true, false, '{}', 4.3333, 3, '{"width":245,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":418,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000ac', 'Goodyear Ultra Grip Performance + SUV Tire', 'goodyear-ultra-grip-performance-suv-tire', 'Winter grip technology: Offers strong grip on snow and ice through a new compound mixture that leads to improved rubber elasticity at low temperatures. Traction protect technology: Helps transmit braking forces into tread quicker for shorter stopping distances. Directional tread pattern: Helps channel water and slush away from the tire for enhanced winter traction and handling', 49.99, NULL, '5080525P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5080525/-p215-60r17-100v-goodyear-ug-perf-suv-117077646--378dd698-086c-4e40-87a4-6687448b5507-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 19, false, false, false, '{}', 5, 3, '{"width":285,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":470,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000ad', 'Goodyear WinterCommand Ultra Tire, Winter Tire for Passenger & CUV', 'goodyear-wintercommand-ultra-tire-winter-tire-for-passenger-cuv', 'Helps to transfer lateral forces during maneuvers and maximum handling performance. Full-Depth, Continuous Track Sipes: Offers enhanced ice traction and braking throughout the life of the tire. Functionalized Elastomer Compound: Adds tread life, increases wet traction, increases flexibility in cold weather. ActiveGrip Technology: Delivers superior traction for performance handling in wet conditions. Wheels sold separately', 49.99, NULL, '3086441P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3086441/235-60r18-107h-xl-wntrcmd-ultra-781027579--e220dc9c-3e1d-41dd-90a4-f25c2ccd4734-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 39, false, false, false, '{}', 3.4, 5, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":466,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000ae', 'Hankook Winter i*Pike X Winter Specialty Tire', 'hankook-winter-i-pike-x-winter-specialty-tire', 'Belted with the ultra-high tensile steel, the new Winter i*Pike X from Hankook is the new specialty tire for the northern winter. The zigzag winter grooves and the wide centre block ensure grip performance in the deep snow while the optimized stud pin placement maximizes ice traction. A winter tire designed with superior traction and durability', 49.99, NULL, '2087128P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2087128/hankook-winter-i-pike-x-205-70r15t-1026809--baf29735-d205-480d-9125-2a7b564108a1-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 20, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":45,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":429,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000af', 'Bridgestone Blizzak LM001 Winter Tire For Passenger & CUV', 'bridgestone-blizzak-lm001-winter-tire-for-passenger-cuv', 'Winter performance tires that feature round corner junctions that improve water evacuation to reduce the risk of hydroplaning. 3D Sipes help provide precision cornering and handling in wet and dry conditions. Advanced tread compound provides confident grip and braking. Vari-width grooves removes water and slush efficiently from the tread', 49.99, NULL, '3083366P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4086456/-255-55r18-109h-bridgestone-blizzak-lm001-004051--c7e30718-384f-4df7-8aaa-63f6e1c85de7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 31, false, false, false, '{}', 4.4286, 7, '{"width":255,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":473,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000b0', 'Goodyear Ultra Grip Performance Gen-1 Tire', 'goodyear-ultra-grip-performance-gen-1-tire', 'Interlocking sipe system provides balance of dry handling and snow performance. High sipe density enhances braking on snow and ice. Block activators provide grip in snow and ice conditions. Hydrodynamic grooves help aquaplaning and slush resistance on wet and slushy roads. Treadwear indicator helps drivers monitor treadwear throughout the life of the tire. Helps drivers monitor treadwear throughout the life of the tire', 49.99, NULL, '2087422P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4080455/-235-55r19-105h-goodyear-ultragrip-perf-gen-1-117042564--2b745b78-12bd-440e-9ce2-584959676bce-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 24, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":60,"rim_diameter":17,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":416,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000b1', 'Goodyear Ultra Grip® 8 Performance Winter Tire for Passenger & CUV', 'goodyear-ultra-grip-8-performance-winter-tire-for-passenger-cuv', 'Directional tread pattern for superior performance in winter conditions. Numerous sipes with biting edges for superior braking power on hard-packed snow and ice. Channels water away from the tire surface for confident grip on wet and slushy roads. Helps maintain flexibility and provide consistent grip at low temperatures. Saw-shaped center rib grips snow-covered roads for enhanced snow traction. Optimized polymer blend and silica tread compound.. Wheels sold separately', 49.99, NULL, '2081870P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2088886/-255-60r18-108h-sl-ult-grip-8-perform-a0-117847373--80f8aa66-906f-44ca-8b49-159f4406f043-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 16, false, true, false, '{}', 5, 1, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":419,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000b2', 'Goodyear Ultra Grip + SUV 4X4 Tire', 'goodyear-ultra-grip-suv-4x4-tire', 'Winter grip technology: Offers strong grip on snow and ice through a new compound mixture that leads to improved rubber elasticity at low temperatures. Traction protect technology: Helps transmit braking forces into tread quicker for shorter stopping distances. Directional tread pattern: Helps channel water and slush away from the tire for enhanced winter traction and handling', 49.99, NULL, '5080518P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5080518/-p265-70r16-112t-goodyear-ultra-grip-suv-4x4-754317575--109fc23d-8ef3-44e5-801c-8aa60b4702c4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 38, false, false, false, '{}', NULL, NULL, '{"width":215,"aspect_ratio":75,"rim_diameter":15,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":464,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000b3', 'Continental ContiWinterContact TS 810 Tire For Passenger & CUV', 'continental-contiwintercontact-ts-810-tire-for-passenger-cuv', 'Continental ContiWinterContact TS 810 Tire is a comfortable, well balanced winter tire for medium and luxury-class cars. Designed to provide excellent handling in winter conditions, superb comfort, high mileage and good braking and wet-weather performance. Asymmetrical tread design with sturdy centre and inner shoulder blocks.. Enhanced grip in snow conditions and cnhanced snow absorption. 20% wider sipes on the inner shoulder. Wheels sold separately', 49.99, NULL, '0080478P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0080478/215-55r16-93h-ts810-89220a60-a5ee-4dcd-9e13-d43c8a9c0ea7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 38, false, false, false, '{}', 5, 1, '{"width":275,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":477,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000b4', 'Falken Espia EPX II Tire', 'falken-espia-epx-ii-tire', 'Confident winter traction. Deep snow capability. Comfortable ride', 49.99, NULL, '3086256P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3080419/-215-55r16-97r-xl-falken-espia-epz-ii-28317662--b583262e-0a30-45b1-8f78-6c66f46f6378-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Falken', true, 31, false, false, false, '{}', 5, 1, '{"width":265,"aspect_ratio":40,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":472,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000b5', 'Hankook Winter I*Cept Evo^2 Winter Tire For Passenger & CUV', 'hankook-winter-i-cept-evo-2-winter-tire-for-passenger-cuv', 'Hankook Winter I*Cept Evo^2 Tire is an ultra winter performance tire designed for SUV''s and light trucks. High grip silica compound improves snow and wet traction, and lowered rolling resistance. Snow-pick traction groove which is made up of lateral ice ax shaped grooves have a scratching effect on roads which provides impressive performance on snow. Zigzag traction groove on the tire tread improves snow traction and braking performance by increasing the cross point of contact. Wheels sold separately', 49.99, NULL, '4080394P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4080394/235-65r17v-xl-108v-w320a-winter-i-cept-evo2-1017056--22e26033-3c6c-43c0-8353-040b53398823-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 17, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":461,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000b6', 'Kumho WinterCraft SUV WS71 Winter Tire for Passenger & CUV', 'kumho-wintercraft-suv-ws71-winter-tire-for-passenger-cuv', 'The Kumho WinterCraft SUV WS71 is designed mainly for SUVS to provide them with excellent braking performance in snowy conditions which improves the safety of the driver during the winter season. The WS71 includes innovative technology added to it which is the bead enhancing which improves endurance and driving stability. A new tread wear indicator and sidewall design motif. Wheels sold separately', 49.99, NULL, '3084585P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3084562/-205-70-r15-t04l-wintercraft-suv-ws71-2207823--c954794c-b2cd-4175-b140-6b2e89f1a156-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Kumho', true, 15, false, false, false, '{}', 5, 1, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":463,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000b7', 'Kumho WinterCraft WP72 Winter Performance Tire', 'kumho-wintercraft-wp72-winter-performance-tire', 'Provides excellent grip and stable cornering in winter conditions. Improved handling through the maximization of interlocking between tread blocks using honeycomb structure. Maximized performance on snowy roads through best directional pattern design. Wheels sold separately', 49.99, NULL, '3084354P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3084342/-205-55-r17-v04l-wintercraft-wp-72-2247513--576516db-3ad2-4e04-aa27-b568c9a27a09-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Kumho', true, 19, false, false, false, '{}', 3.6667, 3, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":473,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000b8', 'Yokohama iceGuard iG51v Winter Tire For Truck & SUV', 'yokohama-iceguard-ig51v-winter-tire-for-truck-suv', 'Yokohama iceGuard iG51v Tire delivers durability and handling in winter conditions. Dual-action shoulder grooves are straight at the bottom to evacuate water. High-density reinforced compound allows for a more stable tread block, providing longer more even wear. Interlocking and adaptive 3D sipes work in tandem to enhance stability and grip on icy surfaces. Wheels sold separately', 49.99, NULL, '4087407P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4087407/215-65r16-98t-ig51v-110151108--7a9e5f71-5799-48a8-b1b4-f8f4abb41a81-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Yokohama', true, 13, false, false, false, '{}', 4.6901, 71, '{"width":265,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":440,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000b9', 'Michelin Latitude Alpin LA2 Winter Tire For Passenger & CUV', 'michelin-latitude-alpin-la2-winter-tire-for-passenger-cuv', 'Features exceptional braking on winter roads for CUV and passenger vehicles. 3-D Stabiligrip Technology™ with variable geometry sipes, rigid tread block reinforcement, adding firmness for more precise handling. Michelin Comfort Control Technology™ ensures a smooth ride by reducing vibrations and road noise through computer-optimized design and precision manufacturing. A new generation formula of full silica-based rubber Helio Compound 3G, allows it to remain flexible in low temperatures for better winter performance. Wheels sold separately', 49.99, NULL, '2088041P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4085025/-235-55r19-101h-latalpin-la2-75293--0f5aab74-76bc-4a6f-8d45-7b5e71d2f972-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Unknown', true, 10, false, true, false, '{}', 4.1, 10, '{"width":295,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":454,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000ba', 'Michelin Pilot Alpin 5 Winter Tire', 'michelin-pilot-alpin-5-winter-tire', 'Safety whatever the winter conditions. Improvement in braking performance on all types of winter road surfaces (snow, wet, dry). Improved snow, wet, and dry grip using the latest generation tread compound integrating a new functional polymer. Acclaimed by premium car manufacturers. Approved by AMG (E-Class, CLS Sport, E-Class Coupé, Cabriolet), Audi (A7,A8), BMW (M5), and Mercedes (B-Class, CLA). Wheels sold separately. Prominent sidewall appearance to complement the aesthetic look of your vehicle. A new directional tread pattern with a center groove increases resistance to hydroplaning. Provides confidence in winter mobility whatever the road condition', 49.99, NULL, '4082664P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5084447/-265-30r19-93w-michelin-pilot-alpin-5-82758--b30bd6f5-5371-45f8-8e7d-d7e7ba5d42b4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Michelin', true, 22, false, false, false, '{}', 4.6389, 36, '{"width":215,"aspect_ratio":55,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":457,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000bb', 'Continental ContiWinterContact TS800 Tire For Passenger & CUV', 'continental-contiwintercontact-ts800-tire-for-passenger-cuv', 'Specifically designed for compact cars. Innovative honeycomb sipes deliver transverse tread rigidity for excellent snow displacement.. V-shaped design accelerates water evacuation greatly reducing the danger of hydroplaning. Compact tread blocks provides maximum contact with the road significantly improving braking performance on icy surfaces. Wheels sold separately', 49.99, NULL, '0080476P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0080476/175-55r15-77t-contiwintercontact-ts800-03532490000--2360a83d-a614-4169-8fc5-2db337067b70-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 27, false, false, false, '{}', 4.8, 5, '{"width":265,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":482,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000bc', 'Bridgestone Blizzak LM-60 RFT Winter Tire For Passenger & CUV', 'bridgestone-blizzak-lm-60-rft-winter-tire-for-passenger-cuv', 'Run Flat Tire (RFT) technology allows you to drive up to 80 km on a flat tire. Circumferential grooves channel water to reduce hydroplaning risk. 3D sipes enhance dry performance while maintaining traction on snow ice and wet surfaces. Wheels sold separately. Unique rubber compound stays flexible in freezing temperatures for superior grip', 49.99, NULL, '3082656P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3082656/-195-55r16-87h-blizz-bridgestone-131487--40aa676f-323e-488d-8866-bd45f044db6a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 27, false, true, false, '{}', 4.1408, 142, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":480,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000bd', 'Bridgestone Blizzak LT Winter Tire For Truck & SUV', 'bridgestone-blizzak-lt-winter-tire-for-truck-suv', 'Suitable for commercial light trucks and vans. Confident stopping power on snow and ice. Reliable handling on snow and slush. Impressive grip and control in winter driving conditions. Wheels sold separately', 49.99, NULL, '3084693P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3084693/lt225-75r16-115r-blizzak-lt-000647--4bdd022c-3191-4c0d-bef7-d32944eee79b-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 24, false, false, false, '{}', 3.5517, 29, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":439,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000be', 'Kumho Wintercraft Ice WI31+ Tire for Passenger & CUV', 'kumho-wintercraft-ice-wi31-tire-for-passenger-cuv', 'Quiet winter tire engineered for superior cold weather traction. The tire’s high dispersion compound grips slick, icy roads while the aggressive tread pattern delivers dependable handling in snow and slush. With an emphasis on providing a smooth and quiet ride, this WinterCraft tire keeps road noise to a minimum without compromising performance. Studdable. Wheels sold separately', 49.99, NULL, '5083364P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5083364/-155-80r13-79q-kumho-wintercraft-ice-wi31-2322803--efd68820-a908-4792-960d-f349a1f287df-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Kumho', true, 19, false, false, false, '{}', NULL, NULL, '{"width":295,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":467,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000bf', 'Pirelli Cinturato Winter 2 Tire', 'pirelli-cinturato-winter-2-tire', 'Wider variable grooves section drafted on shoulder and narrower in center for better handling and reduced aquaplaning. Innovative rubber compound provides high mileage and strong performance on wet and snowy roads. Main grooves create second flow for water evacuation to reduce aquaplaning', 49.99, NULL, '5080595P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5080595/195-55r16-91h-pirelli-cinturato-winter-2-3931000--d9c69880-7b4f-4a30-961d-51fbd8b5ad26-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 37, false, false, false, '{}', 5, 1, '{"width":265,"aspect_ratio":40,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":487,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
