('b2000000-0000-0000-0000-0000000000c3', 'Kumho Wintercraft SUV WS71 Passenger & CUV Winter Tires', 'kumho-wintercraft-suv-ws71-passenger-cuv-winter-tires', 'Designed for SUV & Crossover vehicles to provide more aggression with the aggressive pattern. Improved braking performance in winter and icy conditions. Features new tread wear indicator and sidewall design motif. Highway Rating', 49.99, NULL, '3084562P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3084562/-205-70-r15-t04l-wintercraft-suv-ws71-2207823--c954794c-b2cd-4175-b140-6b2e89f1a156-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Kumho', true, 11, false, false, false, '{}', 4, 1, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":452,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000c4', 'Pirelli Winter Ice Zero Asimmetrico Tire', 'pirelli-winter-ice-zero-asimmetrico-tire', 'FULL DEPTH 3D SIPES - Higher contact pressure and increase in stiffness. Improved braking performance. NEW LIQUID POLYMERS - Tread compound softness. Long lasting performance. Improved wet and ice. LOW VOID RATIO -Increase contact area. Improved ice grip performance. SQUARED BLOCKS - Higher footprint efficiency with longer shoulders. Improved ice performance. DOUBLE SIDE TO SIDE GROOVE - Better footprint pressure distribution. Improved snow and wet performance', 49.99, NULL, '5080633P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5080651/225-65r17-106h-pirelli-ice-zero-asimmetrico-4072200--4855e44b-cf37-4948-8d38-db36ed36bdf0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 24, false, false, false, '{}', 4.0714, 14, '{"width":245,"aspect_ratio":50,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":488,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000c5', 'Goodyear WinterCommand LT Winter Tire for Passenger & CUV', 'goodyear-wintercommand-lt-winter-tire-for-passenger-cuv', 'Tread patterns with multiple biting edges specially designed for your vehicle help provide starting and stopping power on snow-covered roads. Winter Tread Compound maintains flexibility and offers consistent and confident grip at low temperatures. Traction comes from flexible sipes that bite into ice and snow and help keep you from getting stuck.. Wheels sold separately. Cut curves at every turn with corrugated, angled sipes that help provide stability when cornering. Tires designed for use in severe snow conditions and meet specific snow performance test requirements. Drive through harsh winter weather thanks to optional studs that offer enhanced traction', 49.99, NULL, '3086470P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3086470/-lt265-70r18-124r-e-wintercommand-lt-tl-184099786--83630b3d-f882-4683-8648-eabcef1eca4a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 25, false, false, false, '{}', 4.3333, 3, '{"width":265,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":477,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000c6', 'Goodyear Ultra Grip 9+ Tire', 'goodyear-ultra-grip-9-tire', 'Winter grip technology: Offers strong grip on snow and ice through a new compound mixture that leads to improved rubber elasticity at low temperatures. Mileage plus technology: Helps increase treadwear with high elasticity tread compound that has less fractures caused by rough road conditions. Directional tread pattern: Helps channel water and slush away from the tire for enhanced winter traction and handling', 49.99, NULL, '5080511P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5080511/-p185-65r15-88t-goodyear-ultragrip-9-117051645--44ba998e-7db0-4ef8-8027-30feda8f7f10.png', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 14, false, false, true, '{}', NULL, NULL, '{"width":215,"aspect_ratio":60,"rim_diameter":17,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":424,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000c7', 'Bridgestone Blizzak LM-32 Winter Tire For Passenger & CUV', 'bridgestone-blizzak-lm-32-winter-tire-for-passenger-cuv', 'Features a directional tread pattern for confident grip and effective snow shearing. Innovative tread compound ensures reliable grip and braking across wet, dry, icy, slushy, and snowy conditions. Next generation high sipe density pattern improves snow and ice traction by increasing the number of biting edges. Wheels sold separately. Designed for both passenger vehicles and CUVs', 49.99, NULL, '3080185P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3080184/225-40r18xl-92v-bliz-92d61d1d-3a70-453e-9df1-b7abdcdac8ff-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 31, false, true, false, '{}', 4, 7, '{"width":285,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":470,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000c8', 'Kumho WinterCraft WP51 Winter Tire for Passenger & CUV', 'kumho-wintercraft-wp51-winter-tire-for-passenger-cuv', 'The Kumho WinterCraft WP51 offers excellent grip on slush and in snowy conditions. Exception winter handling with a directional tread designed to clear snow and water quickly. Improved dry stability from an advanced interlocking block design. Excellent grip on ice, through a high-dispersion compound and advanced honeycomb snow-sipes. Wheels sold separately', 49.99, NULL, '3084424P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3084424/165-65-r14-t04l-wintercraft-wp-51-2159723--76d74c38-3e96-46cf-a072-29d4032d3e80-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Kumho', true, 28, false, false, false, '{}', NULL, NULL, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":489,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000c9', 'Pirelli P ZERO™ Winter Tire For Passenger & CUV', 'pirelli-p-zero-winter-tire-for-passenger-cuv', 'Engineered for the highest level of performance in winter weather conditions, based on co-development with car makers and the Perfect Fit. Developed for carmakers and end-users already familiar with the P ZERO™ performance in summer who want to enjoy a similar experience in winter weather. Internal shoulder with high sipe density and both transversal and crossed grooves maximize traction and braking on snow. Wheels sold separately', 49.99, NULL, '3086559P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5082667/-275-40r19-105h-xl-pirelli-pzero-winter-3965600--b22e07e7-cbb6-44c1-a98b-56282593c038-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 35, false, true, false, '{}', 5, 1, '{"width":265,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":487,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000ca', 'Pirelli Winter Sottozero 270 Series II Tire For Passenger & CUV', 'pirelli-winter-sottozero-270-series-ii-tire-for-passenger-cuv', 'Ultra high-performance tire that’s a leader in high-speed applications. Provides enhanced safety and driving pleasure and notable results in terms of handling on wet and dry surfaces. Asymmetrical tread pattern with internal and external area improves overall performance because of inclined grooves to increase lateral grip and reduce noise for snow traction and comfort. Patented I.B.S technology for sipe construction which increased contact area even on irregular roads, which helps with braking performance. New Temperature Dynamic Compound (TDC) is excellent for handling and grip in dry and wet conditions, which results in safety and enjoyment when driving in autumn and winter. Wheels sold separately', 650.99, NULL, '0088408P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0088408/pirelli-235-40r19-96w-xl-w270s2-am9-1821100-98aa610e-edbe-42db-b009-5526ce817bd1-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 20, false, true, true, '{}', 1, 1, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":483,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000cb', 'Michelin Pilot Alpin 5 SUV Winter Tire for Passenger & CUV', 'michelin-pilot-alpin-5-suv-winter-tire-for-passenger-cuv', 'Excellent braking performance on all types of winter road surfaces (snow, wet, dry). Provides confidence in winter mobility whatever the road condition. Prominent sidewall appearance to complement the aesthetic look for your vehicle. Approved by AMG (GLC), BMW (X3), Porsche (Cayenne). Improved snow, wet, and dry grip using the latest generation tread compound integrating a new functional polymer. A new directional tread pattern with a center groove increases resistance to hydroplaning. Wheels sold separately', 49.99, NULL, '4088482P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4083074/-225-60r18-104h-xl-pa-67319--b8607143-4670-4bf9-884d-b450918ef38d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Michelin', true, 11, false, false, false, '{}', 4.6286, 35, '{"width":295,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":423,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000cc', 'Michelin Pilot Alpin PA4 Winter Tire For Passenger & CUV', 'michelin-pilot-alpin-pa4-winter-tire-for-passenger-cuv', 'Exclusive tread design with Stabiligrip, a 3D sipe technology that delivers a 10% improvement on snow acceleration and over 5% enhancement in handling on snow-covered and icy roads. Helio compound allows the tire to remain flexible in low temperatures for better braking, stopping over 5% shorter on snow, ice and wet roads. Pilot Alpin PA4 bears the Michelin Green X marking, and its construction reduces rolling resistance for lower fuel consumption and CO2 emissions. Tires provide safe winter driving year after year, with controlled power. Wheels sold separately', 49.99, NULL, '2083430P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2088485/-295-40r19-108v-xltl-63145--7a2ca0cf-0e4d-40fe-a2c7-59971ee32ae8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Michelin', true, 32, false, true, false, '{}', 4.6923, 91, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":416,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000cd', 'Hankook Winter i*Pike RW11 Winter Tire for Passenger & CUV', 'hankook-winter-i-pike-rw11-winter-tire-for-passenger-cuv', 'Experience winter driving confidence with the i*Pike RW11. Designed as an all-terrain winter tire for SUVs and Light Trucks. The i*PikeRW11 takes the lead in stronger braking power. Tread block design and variable stepped grooves provide superior traction in snow. Wider tread width offers maximum performance. Wheels sold separately', 49.99, NULL, '5081628P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5081628/-lt235-75r15-104-101q-hankook-winter-i-pike-rw11-2021566--012b7a05-545e-4113-92d6-0af22406f7cc-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 16, false, false, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":441,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000ce', 'Yokohama BluEarth Winter V906 Truck & SUV Tire', 'yokohama-bluearth-winter-v906-truck-suv-tire', 'Yokohama BluEarth Winter V906 Tire is a passenger, CUVs and SUVs compatible tire. Features outstanding snow traction with its new compound and strategically placed 3D sipes enhance snow and ice traction. Tire''s directional tread design, effectively channels water away from the tire''s surface to minimize the risk of hydroplaning on wet roads. Optimized tread profile increases road contact, resulting in improved handling and responsiveness when driving, contributing to a better driving experience and increased safety. Wheels sold separately', 49.99, NULL, '5083042P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5083046/-225-55r18-102v-yokohama-bluearth-winter-v906-suv-110109622--7101c8b7-eac4-4606-b38b-1f837ad65bd0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Yokohama', true, 34, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":497,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000cf', 'Yokohama BluEarth Winter V906 Passenger & CUV Tires', 'yokohama-bluearth-winter-v906-passenger-cuv-tires', 'Yokohama BluEarth Winter V906 Tire is a passenger, CUVs and SUVs compatible tire. Features outstanding snow traction with its new compound and strategically placed 3D sipes enhance snow and ice traction. Tire''s directional tread design, effectively channels water away from the tire''s surface to minimize the risk of hydroplaning on wet roads. Optimized tread profile increases road contact, resulting in improved handling and responsiveness when driving, contributing to a better driving experience and increased safety. Wheels sold separately', 49.99, NULL, '5083027P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5083027/-205-55r16-94v-yokohama-bluearth-winter-v906-110109601--872391bb-e9cf-4d13-9bda-3980dc7fdda0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Yokohama', true, 27, false, true, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":454,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000d0', 'GT Radial Champiro IcePro SUV Studdable Winter Tire For Truck & SUV', 'gt-radial-champiro-icepro-suv-studdable-winter-tire-for-truck-suv', 'GT Radial Champiro IcePro SUV features the innovative IcePro stud design with sturdy construction for SUVs and light trucks. New Innovative Studdable Design: Reliable in extreme weather conditions. Lateral Groove Pattern Design: Effectively removes sluch and ice from the contact area. New Silica Compound: Enhances ice performance and snow traction. Wheels sold separately', 49.99, NULL, '3085377P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3085377/-255-55r18xl-109t-gtr-champiro-icepro-suv-bw-100a1672--a2529e8f-3005-4e6c-906b-6d9716288f2b-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Giti', true, 21, false, false, false, '{}', 3, 3, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":478,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000d1', 'General Tire Grabber Arctic Studdable Winter Tire For Truck & SUV', 'general-tire-grabber-arctic-studdable-winter-tire-for-truck-suv', 'General Tire Grabber Arctic Tire is a studdable winter tire that offers SUV/truck specific toughness with winter performance while maintaining a high level of comfort. Robust compound with excellent cut and chip resistance while maintaining flexibility in cold temperatures. The angled, interlocking sipe design reduces squirm and block deformation. This provides stable handling and strong braking in dry and wet conditions. The many sipe edges also offer exceptional grip in snow, ice and wet conditions. Wheels sold separately', 49.99, NULL, '4080059P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4080062/-235-70r16-109t-grabber-arctic-15503280000--94b5cd35-7cd8-4da2-9337-c3adc07b86b1-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'General Tire', true, 32, false, false, false, '{}', 4.5714, 7, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":443,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000d2', 'Hankook Winter i*cept iZ3 X Winter Tire for Truck & SUV', 'hankook-winter-i-cept-iz3-x-winter-tire-for-truck-suv', 'Provides confident driving and durability for extreme winters. Provides road assurance with outstanding ice braking and acceleration. Wheels sold separately. Improved handling and grip in winter conditions. Low rolling resistance for longer mileage', 49.99, NULL, '5085729P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5085729/-235-60r16-100t-hankook-winter-i-cept-iz3-x-1032441--13406ec1-21f0-42ae-b39a-cd42be102d83-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 18, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":409,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000d3', 'Gislaved Nord Frost 200 Winter Tire', 'gislaved-nord-frost-200-winter-tire', 'Pattern Technology - Adjusted outer shoulder for optimized handling performance reduced aqua planning performance and waterflow. Sharp Angled Shoulder Design - Allows improvement in lateral grip and increase pattern stiffness to offer better overall handling experience in all weather conditions. A combination of 3D stepped sipes on the inside and 3D sinusoidal sipes provide optimized grip for snow and ice while improving wear performance. Pinned for winter studs for those that desire the added ice grip winter studs provide. Option to have tires pre-studded with new Eco Tri-Star Studs. Three Peak Mountain Snowflake approved sizes meet the severe snow service requirements of the Tire and Rubber Association of Canada', 49.99, NULL, '5080696P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5080713/-225-40r18-92t-gislaved-nord-frost-200-03480840000--5f8510ec-ef96-41a6-b582-1ef81089ea4d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Gislaved', true, 22, false, false, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":448,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000d4', 'Bridgestone Blizzak LM001 RFT Winter Tire For Passenger & CUV', 'bridgestone-blizzak-lm001-rft-winter-tire-for-passenger-cuv', 'Features Run Flat Tire (RFT) technology with reinforced sidewalls keeps your vehicle traveling under control after a puncture. This winter performance tire features round corner junctions that improve water evacuation to reduce the risk of hydroplaning. 3D Sipes help provide precision cornering and handling in wet and dry conditions. Wheels sold separately. Advanced tread compound provides confident grip and braking', 293.99, NULL, '3083380P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4086456/-255-55r18-109h-bridgestone-blizzak-lm001-004051--c7e30718-384f-4df7-8aaa-63f6e1c85de7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 24, false, false, false, '{}', 4.5, 6, '{"width":265,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":448,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000d5', 'Bridgestone Blizzak LM005 Tire for Passenger & CUV', 'bridgestone-blizzak-lm005-tire-for-passenger-cuv', 'Premium touring studless tire with directional tread pattern, designed for passenger cars. Reliable handling on snow and slush. Impressive grip and control in winter driving conditions. Wheels sold separately', 49.99, NULL, '4086489P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5085814/-235-40r19-96w-blizz-25e80f62-7c6a-466e-9cdf-0ba33f0b2674-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 25, false, false, false, '{}', 2.25, 4, '{"width":245,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":439,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000d6', 'Kumho WinterCraft SUV Ice WS31 Winter Tire for Passenger & CUV', 'kumho-wintercraft-suv-ice-ws31-winter-tire-for-passenger-cuv', 'Turbine blade design enhances braking by quickly discharging dust and ice. 3D Sipes improve performance in snowy and wet conditions. Optimized groove pattern strengthens snow and wet performance. Studdable for added traction on icy roads. Wheels sold separately', 49.99, NULL, '3084636P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3084636/-225-55r19-99h-wintercraft-suv-ws31-2209233--639c4021-affb-4d85-8bb4-bdb47a060b5c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Kumho', true, 11, false, false, false, '{}', 1, 1, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":437,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000d7', 'Hankook Winter i*Pike RS2 Tire', 'hankook-winter-i-pike-rs2-tire', 'Belted with the ultra-high tensile steel, the new Winter i*Pike RS2 from Hankook is the new specialty tire for the northern winter. The zigzag winter grooves and the wide centre block ensure grip performance in the deep snow while the optimized stud pin placement maximizes ice traction. A winter tire designed with superior traction and durability', 49.99, NULL, '2087094P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2087094/hankook-winter-i-pike-rs2-175-70r14t-xl-1026793--4d088a7e-855a-4ce3-9e2d-94264032a9e9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 24, false, true, false, '{}', 1.5, 2, '{"width":265,"aspect_ratio":35,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":419,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000d8', 'Continental ContiWinterContact TS 830 P Winter Tire with Improved Braking', 'continental-contiwintercontact-ts-830-p-winter-tire-with-improved-braking', 'Continental ContiWinterContact TS 830 P Tire is an aggressive winter tire designed for extreme braking manoeuvres. Shoulder area tread blocks with more gripping edges guarantee that this tire will cut into snow more effectively, creating optimal grip in wintry conditions. Designed to work in harmony with electronic stability control (ESC) systems ESC selectively controls a braking intervention on one wheel to stabilize the vehicle. Unique tread design ensures the braking effect of the tire and consequently the ESC effect is optimized. Designed for high-performance vehicles. Wheels sold separately', 49.99, NULL, '0080466P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0080463/-225-45r17-91h-contiwintercontact-ts-830-p-03530770000--36c247ed-bf3d-4d0c-89be-baf980fdaebc-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 18, false, true, false, '{}', 4.5, 2, '{"width":285,"aspect_ratio":35,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":430,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000d9', 'General Altimax Arctic 12 Studded Winter Tire for Passenger & CUV', 'general-altimax-arctic-12-studded-winter-tire-for-passenger-cuv', 'Winter factory studded passenger tire. 3PMS Mountain Certified. Pre-studded. Wheels sold separately. Ensure compatibility with your vehicle before purchase', 49.99, NULL, '4089782P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4089782/-185-65r14-90t-12cd-altimax-arctic-12-cd-15573940000--603b8728-4151-4657-8bcf-e14bc6a5ff9c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'General Tire', true, 19, false, false, false, '{}', 4.25, 4, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":482,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000da', 'Goodyear UltraGrip Perf+ Tire', 'goodyear-ultragrip-perf-tire', 'Winter grip technology: Offers strong grip on snow and ice through a new compound mixture that leads to improved rubber elasticity at low temperatures. Traction protect technology: Helps transmit braking forces into tread quicker for shorter stopping distances. Directional tread pattern: Helps channel water and slush away from the tire for enhanced winter traction and handling', 49.99, NULL, '5080490P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5080490/-p215-55r16-97h-goodyear-ultragrip-perf-117079637--2b0443e8-13c7-425f-8e0c-ca2de6ff2393-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 23, false, false, false, '{}', 4, 1, '{"width":265,"aspect_ratio":60,"rim_diameter":18,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":442,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000db', 'Kumho WinterCraft WP71 Tire For Passenger & CUV', 'kumho-wintercraft-wp71-tire-for-passenger-cuv', 'Excellent grip and stable cornering in winter conditions. Improved handling through maximization of interlocking between tread blocks using honeycomb structure. Maximized performance on snowy roads through best directional pattern design. Driving comfort with improved grip force while maintaining the best angle of lateral direction during driving. Wheels sold separately', 49.99, NULL, '3084382P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3084382/205-55-r16-vxll-wintercraft-wp-71-2183353--024f41c6-bb04-4c50-a2e3-4a37aa4398ef-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Kumho', true, 39, false, false, false, '{}', NULL, NULL, '{"width":215,"aspect_ratio":75,"rim_diameter":15,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":460,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000dc', 'Pirelli Winter 210 Sottozero Series II Tire For Passenger & CUV', 'pirelli-winter-210-sottozero-series-ii-tire-for-passenger-cuv', 'An ultra high performance winter tire that is a leader in high speed applications. Asymmetrical tread pattern with internal and external area improves overall performance because of inclined grooves to increase lateral grip and reduce noise for snow traction and comfort. Patented I.B.S technology for sipe construction which increased contact area even on irregular roads, which helps with braking performance. New Temperature Dynamic Compound (TDC) is excellent for handling and grip in dry and wet conditions, which results in safety and enjoyment when driving in autumn and winter. Wheels sold separately. Stiff shoulder blocks improve handling', 49.99, NULL, '0088319P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0088319/205-65r15-94h-w210s2-55f2b019-4344-47ce-8d83-1abbbf002ce4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 12, false, false, false, '{}', 3, 8, '{"width":285,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":452,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000dd', 'General Tire Grabber Arctic LT Studdable Winter Tire For Truck & SUV', 'general-tire-grabber-arctic-lt-studdable-winter-tire-for-truck-suv', 'General Tire''s first studdable, symmetric winter tire developed specifically with work trucks in mind.. Snow traction ridges are a series of raised ridges in the groove bottom arranged at strategic angles to provide additional deep snow grip during cornering, accelerating and braking. Stepped reinforcement bars are used to strengthen the shoulder blocks which improve handling and braking in all weather conditions while the stepped ridges provide additional edges for deep snow grip. Wheels sold separately', 441.99, NULL, '2088234P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2088234/lt225-75r16-115-112r-grabber-lt-04504420000--526110fa-bf91-45b6-b16a-e43c5d940249-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'General Tire', true, 32, false, false, false, '{}', 4.8, 5, '{"width":245,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":473,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000de', 'Continental WinterContact TS860 S Winter Tire', 'continental-wintercontact-ts860-s-winter-tire', 'High angular edges beside the grooves offer additional grip on snow-covered surfaces. Large and wide shoulder tread blocks increase lateral stiffness for tight handling and steering response. Specially designed sipes open up the tread pattern for smooth and flexible adaptation on icy and snowy roads. Strong centre rib with unique sipe pattern provides a rigid block structure for optimized dry handling and braking performance. Wheels sold separately', 49.99, NULL, '4085878P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4085881/-295-35r20-105v-wintercontact-ts-860-s-03553780000--59a59898-72b1-4444-a6cf-958a4bd3cc4a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 13, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":45,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":406,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000df', 'Hankook iON I*CEPT Quiet Winter Tire for Electric SUV', 'hankook-ion-i-cept-quiet-winter-tire-for-electric-suv', 'iON i*cept is Hankook''s winter EV tire optimized to last longer with reduced rolling resistance and extended battery life, while boasting exceptional grip and handling in snow and ice conditions. High-concentration silica and eco-friendly materials extend tread life and lower rolling resistance. Three Peak Mountain Snowflake certified for performance in severe winter weather. Angled sipes improve braking and traction on snow. Optimized pitch sequence for a quiet, more comfortable ride. Wheels sold separately', 49.99, NULL, '5082840P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5082840/-ev-235-50r20-100v-hankook-ion-i-cept-suv-1033390--3aedc2fe-b878-41c1-a533-a3838f08c0b4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 21, false, false, false, '{}', 5, 1, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":484,"traction":"B","temperature":"A","noise_level":"73 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000e0', 'Hankook Winter i*cept iZ3 Winter Tire for Passenger & CUV', 'hankook-winter-i-cept-iz3-winter-tire-for-passenger-cuv', 'Provides confident driving and durability for extreme winters. Provides road assurance with outstanding ice braking and acceleration. Wheels sold separately. Improved handling and grip in winter conditions. Low rolling resistance for longer mileage', 49.99, NULL, '5085704P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5085704/-185-60r15-84t-hankook-winter-i-cept-iz3-1032725--2c2b840f-85bd-4b1e-894d-84f789c29ddf-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 10, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":408,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000e1', 'Kumho Portran CW11 Winter Tire for Passenger & CUV', 'kumho-portran-cw11-winter-tire-for-passenger-cuv', 'Improved ice traction with the latest 3D Sipe and diagonal centre block groove. New tread compound improves wear performance and offer more mileage. Optimized structure and design offers higher load durability. Wheels sold separately', 49.99, NULL, '3086857P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3086857/-kumho-portran-cw11-195-75r16cr08l-cw11-2264123--46b86b3e-aac1-4443-b465-552895a9788c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Kumho', true, 38, false, false, false, '{}', NULL, NULL, '{"width":295,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":452,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000e2', 'Hankook iON I*CEPT Winter Tire for Electric Vehicle', 'hankook-ion-i-cept-winter-tire-for-electric-vehicle', 'The iON i*cept is Hankook''s winter EV tire optimized to last longer with reduced rolling resistance and extended battery life, while boasting exceptional grip and handling in snow and ice conditions. Angled sipes improve braking and traction on snow. Three Peak Mountain Snowflake certified for performance in severe winter weather. High-concentration silica and eco-friendly materials extend tread life and lower rolling resistance. Optimized pitch sequence for a quiet, more comfortable ride. Wheels sold separately', 49.99, NULL, '5082828P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5082840/-ev-235-50r20-100v-hankook-ion-i-cept-suv-1033390--3aedc2fe-b878-41c1-a533-a3838f08c0b4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 12, false, true, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":35,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":428,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000e3', 'Hankook Winter i*cept evo3 Winter Tire for Passenger & CUV', 'hankook-winter-i-cept-evo3-winter-tire-for-passenger-cuv', 'The Hankook Winter i*cept evo 3 provides top snow performance by applying 3D winter sipe in a new unidirectional snow groove design. Incorporating water pipe kerf and wide lateral grooves within the V-shaped pattern reduces the risks of hydroplaning and improves performance on wet road surfaces. A winter perfection in all conditions. Wheels sold separately', 49.99, NULL, '2086988P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2086981/hankook-winter-i-cept-evo3-225-60r17h-1026304--dcccd04b-17ed-4a76-9de2-752b97d72d0d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 18, false, false, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":483,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000e4', 'Gislaved Nord Frost 200 ID Winter Tire', 'gislaved-nord-frost-200-id-winter-tire', 'Pattern Technology - Adjusted outer shoulder for optimized handling performance reduced aqua planning performance and waterflow. Sharp Angled Shoulder Design - Allows improvement in lateral grip and increase pattern stiffness to offer better overall handling experience in all weather conditions. A combination of 3D stepped sipes on the inside and 3D sinusoidal sipes provide optimized grip for snow and ice while improving wear performance. Pinned for winter studs for those that desire the added ice grip winter studs provide. Option to have tires pre-studded with new Eco Tri-Star Studs. Three Peak Mountain Snowflake approved sizes meet the severe snow service requirements of the Tire and Rubber Association of Canada', 168.99, NULL, '5080697P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5080697/-205-70r15-96t-gislaved-nord-frost-200-id-03480970000--bf46a6a0-8b71-4bc0-8ecb-a96741d0deb6-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Gislaved', true, 33, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":35,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":495,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000e5', 'Goodyear UltraGrip Perf 3 Tire', 'goodyear-ultragrip-perf-3-tire', 'A winter tire designed for luxury and high-performance vehicles. High sipe density for better braking and handling on snow. Designed with proprietary WetGrip+ Technology. A directional tread pattern disperses water out to the sides of the tire to help increase grip in wet and slushy conditions', 49.99, NULL, '5085324P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5085332/-215-65r17-99h-goodyear-ultragrip-perf-3-117108679--b52e2999-8a1e-48ab-b5bd-159a8c30abf2-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Goodyear', true, 17, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":60,"rim_diameter":18,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":421,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000e6', 'Hankook Winter i*cept evo3 X Winter Tire For Passenger & CUV', 'hankook-winter-i-cept-evo3-x-winter-tire-for-passenger-cuv', 'The Hankook Winter i*cept evo3 X provides top snow performance by applying 3D winter sipe in a new unidirectional snow groove design. Incorporating water pipe kerf and wide lateral grooves within the V-shaped pattern reduces the risks of hydroplaning and improves performance on wet road surfaces. A winter perfection in all conditions. Wheels sold separately', 49.99, NULL, '2087088P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2087070/-hankook-winter-i-cept-evo3-x-225-65r17h-1026386--e2ad9874-2720-4b79-a0a8-a75c7cbcab15-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 36, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":469,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000e7', 'Pirelli P Zero™ Winter 2 Performance Tire For Passenger & CUV', 'pirelli-p-zero-winter-2-performance-tire-for-passenger-cuv', 'Main grooves with a curved shaped design. Longer sipes parallel to main grooves. 3D sipes wider on top. Network groove pattern. Optimized directional tread pattern. Wheels sold separately', 49.99, NULL, '5085579P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5085579/-295-35r20-105w-pirelli-p-zero-winter-2-4451400--b7b05fe0-6274-4536-a9fa-677879a36e11-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 21, false, true, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":450,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000e8', 'Hankook i*Pike RW11 Studdable Winter Tire For Passenger & CUV', 'hankook-i-pike-rw11-studdable-winter-tire-for-passenger-cuv', 'i*Pike RW11 takes the lead in stronger braking power and superior traction in snow condition. Maximized snow traction implemented with the Edge Block at center. Enhanced ice performance with the pin arrangement optimized through computer simulation. Stone ejectors in the centre and shoulder grooves help prevent tire damage from stones or external impacts. Features a wide tread width which enhances braking perfromance on snow and ice. A tiered groove reduces angle of tread block movement in cornering to secure safer turns. Wheels sold separately', 49.99, NULL, '2083007P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2083007/-215-70r16-100t-ipk-1010480--6292c7ad-db5a-442d-b826-7c3dd6ec77f4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Hankook', true, 38, false, true, false, '{}', 4.2778, 18, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":495,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000e9', 'Pirelli Winter 240 Sottozero Series II Tire For Passenger & CUV', 'pirelli-winter-240-sottozero-series-ii-tire-for-passenger-cuv', 'An ultra high performance winter tire that is a leader in high speed applications. Asymmetrical tread pattern with internal and external area improves overall performance because of inclined grooves to increase lateral grip and reduce noise for snow traction and comfort. Patented I.B.S technology for sipe construction which increased contact area even on irregular roads, which helps with braking performance. New Temperature Dynamic Compound (TDC) is excellent for handling and grip in dry and wet conditions, which results in safety and enjoyment when driving in autumn and winter. Wheels sold separately. Stiff shoulder blocks improve handling', 49.99, NULL, '0088424P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0088459/-pirelli-235-35r19-91v-xl-w240s2-l-1857700-9a11a331-c8c6-494b-9b31-1e76c8d87e77-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Pirelli', true, 14, false, false, false, '{}', 1.6667, 3, '{"width":235,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":433,"traction":"B","temperature":"A","noise_level":"72 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000ea', 'Bridgestone Blizzak LM-25 RFT Tire', 'bridgestone-blizzak-lm-25-rft-tire', 'Molds a high-silica content tread compound that remains pliable in cold temperatures to combine winter traction with run-flat durability. Designed to allow drivers to maintain their vehicle''s sporty appearance while providing wintertime traction on cold, dry, wet and snow-covered roads. Branded with the three-peak mountain snowflake (3PMSF) symbol. Wheels sold separately. Tough reinforced sidewalls designed to keep you on the road longer. Touring-tire comfort and responsive handling. Wet and dry performance meets fuel efficiency', 49.99, NULL, '3082648P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3082648/245-45r18-96v-blizz-bridgestone-040248--e506c3bf-fb14-4466-a362-5f66ed404409-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 30, false, false, false, '{}', 4.0227, 44, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":452,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000eb', 'Continental 4x4 WinterContact Tire For Passenger & CUV', 'continental-4x4-wintercontact-tire-for-passenger-cuv', 'Continental Winter Contact Tire delivers excellent braking performance on snow for 4x4 vehicles. Asymmetrical tread pattern provides excellent handling even in the winter, while progressive sipe technology means outstanding driving stability and traction. Designed for severe snow, ice and winter conditions. Rated for speeds up to 210 km/h and 240 km/h. Wheels sold separately', 49.99, NULL, '0080439P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/0080439/255-55r18-109h-conti4x4wintercontact-03545550000--5da50749-5252-439d-92bf-b337ec33f53e-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 25, false, false, true, '{}', NULL, NULL, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":454,"traction":"B","temperature":"A","noise_level":"74 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000ec', 'Kumho KC11 Power Grip Winter Tire for Truck & SUV', 'kumho-kc11-power-grip-winter-tire-for-truck-suv', 'Kumho KC11 Power Grip Winter Tires'' main feature is its improved snow traction via tooth-edged block pattern. Snow traction and appearance is enhanced with variable sipping. V-Groove tread proves improves water drainage', 49.99, NULL, '3084645P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3084645/-265-70r16-112q-power-grip-kc11-2145743--7d9dc06a-61e2-4f09-ac0e-f101da1fe6bf-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Kumho', true, 21, false, false, true, '{}', NULL, NULL, '{"width":275,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":405,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}'),
('b2000000-0000-0000-0000-0000000000ed', 'Bridgestone Blizzak LM 4X4 RFT Tire', 'bridgestone-blizzak-lm-4x4-rft-tire', 'Run Flat Tire (RFT) technology with reinforced sidewalls keeps your vehicle traveling under control after a puncture. Zig-zag sipes improves snow and ice traction by increasing the number of biting edges. Wide straight groove enhances snow traction and water evacuation. Wheels sold separately. Ultra-high performance tire', 49.99, NULL, '3082588P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/3082651/-255-50r19-107v-bliz-bridgestone-096654--2a5e8691-8563-4633-a395-d00109f680c8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Bridgestone', true, 11, false, false, false, '{}', NULL, NULL, '{"width":205,"aspect_ratio":65,"rim_diameter":16,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":434,"traction":"B","temperature":"A","noise_level":"69 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000ee', 'Michelin Agilis Alpin Winter Tire For Truck & SUV', 'michelin-agilis-alpin-winter-tire-for-truck-suv', 'Features the same impact-resistance sidewalls as its predecessor, while also providing better protection from abrasion. A unique tread that features open shoulders and widely spaced blocks to improve traction in the snow and on icy roads. Self-blocking, variable-geometry sipes give the tread blocks and tire greater stability. Wheels sold separately. Designed to reduce road vibrations and noise, offering a quiet and comfortable experience for daily or commercial journeys', 49.99, NULL, '4082255P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4082255/225-75r16c121-120r-michelin-agilis-alpin-18018--08f04173-b7d2-4fc9-9e16-2682d161a46e-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Michelin', true, 32, false, true, false, '{}', 4.7143, 7, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":420,"traction":"B","temperature":"A","noise_level":"71 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000ef', 'Continental ContiWinterContact TS 830 P SSR Tire', 'continental-contiwintercontact-ts-830-p-ssr-tire', 'Designed for high-performance vehicles, the Continental ContiWinterContact TS830 P SSR Tire offers exceptional braking power and wet and icy roads. Improved stopping on snow with a high number of blocks in the shoulder area with more gripping edges guarantee that this tire will cut into snow more effectively, creating optimal grip in wintery conditions which provide better stopping performance on snow. Outstanding braking performance on icy and wet roads. High block rigidity in the tread pattern centre coupled with a high number of sipes lead to enhanced braking performance on icy and wet roads. Wheels sold separately', 49.99, NULL, '2083096P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/2083096/-225-50r18-99v-xl-tl-cwntrcnct-ts-830-p-ssr-03532580000--ebc863c1-dece-4bce-ae1a-c2c25f17956f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 26, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":50,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Winter","runflat":false,"treadwear":429,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true}'),
('b2000000-0000-0000-0000-0000000000f0', 'Continental VanContact Winter Tire For Truck & SUV', 'continental-vancontact-winter-tire-for-truck-suv', 'Continental VanContact Winter Tire features shorter braking distances and improved traction on snow. High aquaplaning safety and shorter braking distances on wet roads. Improved rolling resistance. Wheels sold separately', 640.99, NULL, '4081006P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/4081007/-185-60r15c-94-92t-vancontact-winter-6pr-04531660000--13da1d03-aba6-4f56-b024-c4ca999c5ef4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000003', 'Continental', true, 10, false, true, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Winter","runflat":false,"treadwear":477,"traction":"B","temperature":"A","noise_level":"70 dB","warranty_miles":40000,"three_peak_mountain_snowflake":true,"studdable":true}')
