('b2000000-0000-0000-0000-0000000000f1', 'Continental ExtremeContact DWS06 Plus Performance Tire For Passenger & CUV', 'continental-extremecontact-dws06-plus-performance-tire-for-passenger-cuv', 'Enhanced performance in dry conditions and improved water evacuation for wet handling. 80,000 KM mileage rating. Solid outer shoulder and chamfered tread blocks. High Void-to-Tread ratio with enhanced groove. Dynamic Temperature Distribution technology. Tuned Performance Indicators alert drivers to tire’s health', 49.99, NULL, '0063017P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0063017/p205-55r16-91w-conti-extremecontact-dws06-plus-15572660000--155f8fea-2a74-450f-9181-b51ed5247876-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 17, false, false, false, '{}', 4.6287, 272, '{"width":255,"aspect_ratio":70,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":339,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000f2', 'Michelin Pilot Sport A/S 4 Tire for Passenger & CUV', 'michelin-pilot-sport-a-s-4-tire-for-passenger-cuv', 'The Michelin Pilot Sport A/S 4 is designed with superior performance that stands out from the crowd. Asymmetric tread pattern has more rubber on the outer shoulder to deliver exceptional lateral grip. Extreme Silica + tread compound offers a race inspired tread compound engineered with maximum levels of silica to grab hold of slick pavement. 360-degree variable sipe technology has distinctive full depth and interlocking sipes provide biting edges for improved traction in wet and snowy conditions. The Helio+ technology ensures enhance control on the road even in freezing conditions. Biting edges in the tread grooves grab loose snow to help control acceleration and braking in winter conditions. Wheels sold separately', 49.99, NULL, '3085780P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/1080105/225-40zr18-92y-xl-michelin-pilot-sport-a-s-4-34320--47537d96-7f48-44bc-bbd2-43566d8e0ca0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Michelin', true, 36, false, false, false, '{}', 4.4168, 511, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":293,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000f3', 'Michelin Latitude Sport 3 Performance Tire For Passenger & CUV', 'michelin-latitude-sport-3-performance-tire-for-passenger-cuv', 'An ultra high-performance SUV and crossover tire with sport performance capabilities. Engineered to excel in wet conditions. A new tread compound and increased void ratio offer improved wet grip. Variable thickness sipes reduce tread block deformation, which improves rolling resistance. Wheels sold separately. Supported by the Michelin Promise Plan of a 60-day satisfaction guarantee, roadside assistance, and a limited warranty of 30,000 kilometres. Performance tire design enhances handling and responsiveness for an engaging driving experience', 49.99, NULL, '2086277P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4084533/265-50r19-110w-xl-ls3-zp-gr-31529--a4cdf2f3-c797-4fbd-b17a-bd7140ad9c78-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Michelin', true, 17, false, false, false, '{}', 4.156, 359, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":327,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000f4', 'Bridgestone Potenza RE-71R Performance Tire For Passenger & CUV', 'bridgestone-potenza-re-71r-performance-tire-for-passenger-cuv', 'Engineered with technology inspired by racing. Designed for maximum grip under braking and cornering conditions the Potenza RE-71R responds to your driving in wet or dry conditions. Hydro evacuation surface provides effective drainage in wet conditions. A wide centre rib promotes agile steering response. Wheels sold separately', 49.99, NULL, '3082536P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3082536/225-35r19-88w-poten-bridgestone-002976--7e81fd55-09ee-4eb7-8604-fb82a40273c9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 14, false, false, false, '{}', 4.3571, 14, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":319,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000f5', 'Goodyear Eagle F1 SuperCar SCT Performance Tire For Passenger & CUV', 'goodyear-eagle-f1-supercar-sct-performance-tire-for-passenger-cuv', 'Goodyear Eagle F1 SuperCar is a race inspired, ultra high-performance tire. Asymmetric, directional tread design with massive tread blocks on the outboard side of the tread helps enhance dry cornering grip. Sweeping Aquachannel grooves on the inboard side of the tread helps enhance wet cornering grip. Wheels sold separately', 386.99, NULL, '4083199P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4083199/255-35r22-99w-xl-eag-389357001--f7b99c60-660d-4bc7-9aab-49fc0815739c-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 38, false, false, true, '{}', 3.8788, 33, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":296,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000f6', 'Continental SportContact 6 High Performance Sports Tire', 'continental-sportcontact-6-high-performance-sports-tire', 'Designed for sports and high-performance vehicles. Perfect steering precision and sporty handling. Outstanding grip and stability during cornering. Optimised to meet the specific requirements of front and rear axle positions. Tuned for original equipment applications. Responsive handling. High-speed stability. Uncompromised grip. Wheels sold separately', 49.99, NULL, '3080337P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2087203/continental-sportcontact-6-285-45r22-03572160000--ba9a1ae5-17b1-4910-845a-f7bafc7c40ec-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 23, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":293,"traction":"AA","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000f7', 'Firestone Firehawk Indy 500 V2 Performance Passenger & CUV Tires', 'firestone-firehawk-indy-500-v2-performance-passenger-cuv-tires', 'Inspired by Firestone''s racing heritage. Responsive steering. Connecting block tread built for cornering stability. Long-lasting wear. Advanced rain pulse groove to help evacuate water from the tread pattern', 49.99, NULL, '5089034P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5089073/215-45r17-91w-xl-firestone-firehawk-indy-500-v2-008033--91da9094-60b4-4bb9-b447-91a50d35fe50-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Firestone', true, 14, false, false, false, '{}', 4.6667, 6, '{"width":275,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":294,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000f8', 'Firestone All Season Tire For Passenger & CUV', 'firestone-all-season-tire-for-passenger-cuv', 'Deep sipes retain wet and all-season performance. Specially engineered to provide performance in wet, dry, and snowy conditions with traction and handling all year long. 90,000 kilometre limited treadwear warranty (CUV sizes) & 105,000 kilometre limited treadwear warranty on all other sizes. Wheels sold separately. Highway-rated for enhanced stability and comfort on paved surfaces. Low rolling resistance contributes to improved fuel efficiency. Symmetrical tread pattern enhances grip and traction for confident handling. Designed for durability, offering long-lasting tread life under typical driving conditions. Ideal for everyday driving, balancing performance and comfort seamlessly', 49.99, NULL, '3083423P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3083423/175-65r15-84t-firestone-all-season-004054--7789c583-263c-446f-95a3-f26116ae5d06-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Firestone', true, 27, false, false, false, '{}', 4.0602, 133, '{"width":285,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":332,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000f9', 'Bridgestone Potenza Sport Performance Passenger & CUV Tires', 'bridgestone-potenza-sport-performance-passenger-cuv-tires', 'Original equipment on many popular vehicles. Engineered to empower drivers, the Potenza Sport high performance summer tires let you take control of the track. Whether the conditions are damp or you’re taking curves at high speeds, these tires offer an exhilarating experience. Wheels sold separately', 49.99, NULL, '0081730P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0081730/235-45r18-98y-xl-bridgestone-potenza-sport-008121--5ceb428f-0bdf-4f20-aeab-575a755f6579-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 33, false, false, false, '{}', 4.1635, 318, '{"width":215,"aspect_ratio":75,"rim_diameter":15,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":304,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000fa', 'Michelin Pilot Sport S 5 Performance Tire for Passenger & CUV', 'michelin-pilot-sport-s-5-performance-tire-for-passenger-cuv', 'Tailor-made for the most demanding sports car manufacturers. Silica-enriched tread compound for superior road grip. Razor sharp handling for assertive control. Optimized for high-speed driving and track use. Wheels sold separately. Quiet ride technology minimizes road noise for a comfortable drive. Lightweight construction improves acceleration and fuel efficiency. Backed by Michelin’s limited warranty for peace of mind', 49.99, NULL, '5082939P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5082939/245-40r21-96y-michelin-pilot-sport-s-5-01321--faa68804-72c7-469d-b3aa-e60b80815177-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Michelin', true, 12, false, false, false, '{}', 4.6667, 3, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":327,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000fb', 'BFGoodrich G-Force Comp-2 A/S+ Tire For Passenger & CUV', 'bfgoodrich-g-force-comp-2-a-s-tire-for-passenger-cuv', 'Best wet and dry grip vs. competitors. Control in all seasons. Good treadlife. 70,000km warranty', 49.99, NULL, '3085744P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0080887/-bfgoodrich-g-force-comp-2-a-s-215-45r17-25463--951d7085-43e4-41f6-b1f1-1b25fd5cebe2-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'BFGoodrich', true, 26, false, false, false, '{}', 4.3875, 351, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":356,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000fc', 'Goodyear Eagle F1 Supercar 3 Performance Tire For Passenger & CUV', 'goodyear-eagle-f1-supercar-3-performance-tire-for-passenger-cuv', 'Ultra high-performance tread compound helps provide excellent dry traction. Race-derived, multi-radius mold shape offers precise handling and smooth, even wear. Large outer shoulder blocks and asymmetric tread design helps enhance cornering grip. Wheels sold separately', 49.99, NULL, '4081230P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0081008/p215-45r18-89w-sl-goodyear-eagle-f1-a-s-c-480686273--78360282-e91d-4418-9619-5c02cf489cd3-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 15, false, false, false, '{}', 4.52, 25, '{"width":255,"aspect_ratio":70,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":290,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000fd', 'BFGoodrich Radial T/A Performance Tire For Passenger & CUV', 'bfgoodrich-radial-t-a-performance-tire-for-passenger-cuv', 'BFGoodrich Radial T/A Tire offers new tread compounding yields longer wear and better wet traction characteristics, while maintaining dry traction. G-Wedge technology advanced sidewall stabilizer improves lateral stability. Unique tread block phasing permits and aggressive, high performance block tread with low "touring" noise levels. The two full width steel belts deliver stiffened tread, for better steering response more cornering force and improved grip. The Equal Tension Containment System provides high speed durabiltiy and stable handling. Wheels sold separately', 49.99, NULL, '0083084P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0083084/p225-60r14-94s-radta-1b1e85ac-a331-4a8b-8c73-056819e1f7cf-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'BFGoodrich', true, 37, false, false, false, '{}', 3.6135, 207, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":302,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000fe', 'Continental ContiProContact All Season Tire For Passenger & CUV', 'continental-contiprocontact-all-season-tire-for-passenger-cuv', 'The Continental ContiProContact Tire is a high-performance Tire for top-of-the-line performance vehicles. Designed for performance and touring, it features excellent wet-braking capacity and traction. Special shoulder groove geometry fosters secure cornering and standout performance in wet conditions. Interlocking tread sipes deliver improved steering precision and dry performance. Alternating convex and concave sipe design promotes multidirectional grip and low noise. Wheels sold separately', 49.99, NULL, '0081440P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0081442/continental-contiprocontact-m0-235-45r17-94h-03500210000--fb970756-d76d-4136-b880-909ccf788129-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 37, false, false, false, '{}', 3.6, 35, '{"width":245,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":284,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-0000000000ff', 'Michelin Pilot® Sport 4S High Performance Tire For Passenger & CUV', 'michelin-pilot-sport-4s-high-performance-tire-for-passenger-cuv', 'Perfect choice for driving enthusiasts and CUV owners alike. Designed for road and track use. Outstanding handling and control at high speeds. Superior grip on dry surfaces and excellent wet braking. Developed from endurance racing technology. Wheels are sold separately', 49.99, NULL, '0080854P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5082140/michelin-pilot-sport-4-s-255-35r22-99-y--7a0d7b8a-1ef9-46f6-ac7a-1784ea4d169f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Michelin', true, 20, false, false, false, '{}', 4.1458, 1824, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":275,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000100', 'Bridgestone Turanza LS100 MOE Tire for Passenger & CUV', 'bridgestone-turanza-ls100-moe-tire-for-passenger-cuv', 'Original equipment on many popular vehicles, including sedans, SUVs, and luxury vehicles. Radial construction absorbs road noise and provides a smooth, quiet and reliable ride. Innovative technology provides optimal traction and handling in both wet and dry conditions. Wheels sold separately. Rim size: 18"/45cm', 473.99, NULL, '0081780P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5081191/265-40r21-105hh-bridgestone-turanza-ls100-moe-sp-014161--0e761537-6ca4-4c13-90aa-ef78ac8c4f76-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 15, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":265,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000101', 'Vredestein Hypertrac for Performance Passenger & CUV', 'vredestein-hypertrac-for-performance-passenger-cuv', 'Precise dry road handling for agility. Heightened control during cornering. All Season for a year-round enhanced performance. Acoustic comfort reduces road noise. Intended to give you a smooth ride. All-season design ensures year-round reliability', 49.99, NULL, '0074941P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0074945/225-45r17-vredestein-hypertrac-0c476d5d-2f71-4851-a7a2-95b0862121c1-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Vredestein', true, 24, false, false, false, '{}', 4.5476, 84, '{"width":265,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":341,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000102', 'Yokohama Advan Fleva Performance Tire For Passenger & CUV', 'yokohama-advan-fleva-performance-tire-for-passenger-cuv', 'Yokohama ADVAN FLEVA Tire features an advanced profile that helps control contact pressure for balanced wet performance and steering stability at top speeds. nanoBLEND compound provides optimum balance of superior wet grip performance, high fuel efficiency and exceptional wear performance. Non-penetrating Lug Groove pattern suppresses heel and toe friction as well as the popping noise for a quieter ride. Wheels sold separately', 49.99, NULL, '4086799P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4086799/195-50r15-82v-fleva-v701-110170130--b4bad83f-1219-4050-937d-677972e58d52.png', 'a1000000-0000-0000-0000-000000000002', 'Yokohama', true, 31, false, false, false, '{}', 4.7407, 54, '{"width":275,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":322,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000103', 'Bridgestone Dueler H/P Sport AS Performance Tire For Passenger & CUV', 'bridgestone-dueler-h-p-sport-as-performance-tire-for-passenger-cuv', 'Designed to high performance standards for your sport truck or SUV. Circumferential grooves deliver confident wet performance. High stiffness, closed shoulder and high angle slots deliver confident wet performance. Performance tire design enhances handling and responsiveness for an engaging driving experience. Wheels sold separately', 49.99, NULL, '3080015P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/3080003/p215-70r16-99h-duele-000010--0e29a0df-9841-44fe-8ae8-31fb1ce8f9d3-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 22, false, false, false, '{}', 2.62, 100, '{"width":235,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":300,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000104', 'Pirelli Scorpion Verde All Season Tire for Passenger & CUV', 'pirelli-scorpion-verde-all-season-tire-for-passenger-cuv', 'Green performance tire developed specifically for crossovers and SUVs. Innovative materials used in the compound provide lower rolling resistance. Reduced fuel consumption. Large contact patch and four wide longitudinal grooves help control and evacuate water which provide enhanced grip in wet conditions. The lateral stability and the traction on wet surfaces, ensures all season performances. Wheels sold separately', 49.99, NULL, '4080514P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/0089165/pirelli-p235-70r16-106h-s-veas-1961200-6c843cf2-27c2-4b13-917e-c75d27c3fa13-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 17, false, false, false, '{}', 4.3077, 13, '{"width":285,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":346,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000105', 'Pirelli Cinturato P7™ All-Season Plus II Tire For Passenger and CUV', 'pirelli-cinturato-p7-all-season-plus-ii-tire-for-passenger-and-cuv', 'Formula contains silica functionalized polymer with higher silica content for improved wet performance and fuel consumption. Optimized design and innovative materials deliver lower rolling resistance and weight to help reduce fuel consumption and CO2 emissions while also improving mileage. Pitch sequencing and phasing from optimized tread design to provide lower internal noise. Delivers exceptional performance and handling in all weather conditions including wet, dry and light snow. Provides excellent water expulsion and greater lateral stability. Wheels sold separately', 49.99, NULL, '4089037P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4089396/225-65r17-102h-cinturato-p7-all-season-plus-ii-3737500--fb1fc7f7-d273-400f-a2cc-a76fb67d6dbc-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 39, false, true, false, '{}', 4.5, 14, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":343,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000106', 'Goodyear Eagle Touring', 'goodyear-eagle-touring', 'For enhanced handling and responsiveness. Help to provide confident all-season traction in wet, dry and snowy conditions. Helps to quiet noise from on-road driving', 49.99, NULL, '2088873P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2088873/245-45r19-98v-eagle-touring-vsb-rptl-102839387--e5fc9142-2239-48b7-891e-8f2eb12c5d0f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 27, false, false, false, '{}', 2.6796, 103, '{"width":225,"aspect_ratio":55,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":330,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000107', 'Firestone Firehawk Indy 500 Performance Tire For Passenger & CUV', 'firestone-firehawk-indy-500-performance-tire-for-passenger-cuv', 'Ultra high summer performance tire. Wide shoulder blocks provide impressive handling and cornering in dry conditions. Improved wet rubber compound and tread design for more control on wet roads. Wheels sold separately. Performance tire design enhances handling and responsiveness for an engaging driving experience. Low rolling resistance contributes to improved fuel efficiency. Designed for durability, offering long-lasting tread life under typical driving conditions. Excellent grip on highway surfaces, enhancing overall driving safety and performance. Non-studdable construction simplifies maintenance and provides a smooth ride', 49.99, NULL, '3083420P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3083420/235-55r17-99w-firestone-firehawk-indy-500-002930--c1cd8467-d2df-48e9-b1ba-6bca1b858006-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Firestone', true, 33, false, true, false, '{}', 4.4783, 138, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":300,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000108', 'Goodyear Eagle F1 Asymmetric 3 ROF High-Performance Tire', 'goodyear-eagle-f1-asymmetric-3-rof-high-performance-tire', 'The Goodyear Eagle F1 Asymmetric 3 ROF Tire tread design offers powerful traction in turns and enhanced wet traction. Grip-boosting tread compound enhances road adhesion for superior traction. This tire is tuned for ultra high-performance suspension systems. Wheels sold separately', 49.99, NULL, '2088877P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2081854/goodyear-eagle-f1-asym-3-rof-225-45r19-783153385--71eda38b-ae9a-4473-b6c7-4d554380ed75-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 17, false, true, false, '{}', 3.963, 27, '{"width":195,"aspect_ratio":65,"rim_diameter":15,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":275,"traction":"AA","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000109', 'Yokohama Advan Sport A/S+ Performance Passenger & CUV Tires', 'yokohama-advan-sport-a-s-performance-passenger-cuv-tires', 'Yokohama Advan Sport A/S+ Performance Passenger & CUV Tires are all-season tires specifically engineered to deliver ultra-high performance at every turn. Featuring the new HS-2 Compound, this tire offers a serious upgrade in braking and effortless handling in wet and cold conditions. Made for usage on passenger and CUVs', 49.99, NULL, '0061090P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0061090/205-55r16-yokohama-advan-sport-a-s-110140610--6c1390c7-ba6c-42a0-a368-072c34ac18a0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Yokohama', true, 29, false, false, false, '{}', 4.5745, 94, '{"width":265,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":323,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000010a', 'Continental ProContact RX Tire', 'continental-procontact-rx-tire', 'Original equipment design tailored to your vehicle. Improved traction on snowy and wet roads. Outstanding braking performance in wet conditions. Low density undertread for better efficiency. Absorbs road impacts for a comfortable drive. Wheels are not included', 49.99, NULL, '3086628P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2087176/continental-procontact-rx-235-50r19-03118780000--613c5dde-a52c-40dd-a2c9-771d61e423bc-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 19, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":55,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":357,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000010b', 'Hankook Kinergy GT All Season Tire For Passenger & CUV', 'hankook-kinergy-gt-all-season-tire-for-passenger-cuv', 'Hankook Kinergy GT is an ultra high performance all season Tire that is the perfect fit for passenger vehicles. Having a tire with wider grooves provides maximum water evacuation which promotes wet traction. Rigid center rib provides excellent grip for outstanding handling and braking performance. Wide contact area maximizes steering response and stability even in extreme driving conditions. Wide lateral grooves provide excellent snow grip and enhance snow traction. Wheels sold separately', 49.99, NULL, '4080100P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4080100/235-45r18-94h-h436-kinergy-gt-1014973--4b7c2ce3-e6c1-4d9f-8bd0-e476529a0846-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Hankook', true, 31, false, false, false, '{}', 2.6316, 19, '{"width":275,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":291,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000010c', 'Continental CrossContact LX Sport All-Season Tire for Passenger & CUV', 'continental-crosscontact-lx-sport-all-season-tire-for-passenger-cuv', 'Open outer shoulder provides good handling and braking properties even on easy terrain. The Tri-Net Silica Tread Compound allows it to adjust to road conditions and improves traction. Asymmetric tread design provides high traction performance on wet, dry and snow covered roads. The four deep and broad circumferential grooves widen towards the opening, ensuring very good aquaplaning resistance and reducing tire damage. Wheels sold separately. The ContiCrossContact LX Sport guarantees improved dry handling and an enhanced transmission of force from the tire to the road', 49.99, NULL, '3080035P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/2081091/255-50r19-107h-crosscontact-lx-sport-ssr-3507620000--0781d682-a5a4-41ff-bbe6-9ca4900d2fa8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 19, false, false, false, '{}', 5, 1, '{"width":215,"aspect_ratio":75,"rim_diameter":15,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":292,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000010d', 'Bridgestone Turanza EL450 RFT Tire', 'bridgestone-turanza-el450-rft-tire', 'Original Equipment on Popular Run Flat Equipped Vehicles. Comfortable ride. Confident wet and dry performance', 538.99, NULL, '3084911P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5082116/255-55r18-105v-bridgestone-turanza-el450-014952--31c243b9-4eeb-4857-ad11-067620fb89d8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 37, false, false, false, '{}', NULL, NULL, '{"width":205,"aspect_ratio":55,"rim_diameter":16,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":321,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000010e', 'Pirelli P ZERO (PZ4-Sport) Summer Performance Tire For Passenger & CUV', 'pirelli-p-zero-pz4-sport-summer-performance-tire-for-passenger-cuv', 'An ultra high-performance tire designed for sports cars. Pitch sequence and siping design provides great performance for low roll resistance and low noise. Customized inner tread design provides superior safety in wet due to the high silica construction. Customized tread compound improves rolling resistance, wet performance and mileage. Wheels sold separately', 49.99, NULL, '4081281P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4087877/255-45r19-104y-p-zero-pz4-sport-2817100--798b5aac-9316-4ca4-b27a-03e27e58c85b-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 25, false, false, false, '{}', 5, 1, '{"width":295,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":327,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000010f', 'Michelin Pilot Sport 4 Performance Tire For Passenger & CUV', 'michelin-pilot-sport-4-performance-tire-for-passenger-cuv', 'Formula-E Tread Pattern ensures superior grip on all surfaces. Advanced elastomer compound enhances traction in all weather conditions. Offers 13% less rolling resistance than its predecessor improving overall efficiency. Wheels sold separately. Engineered to excel in wet conditions, with the ability to hold curves without slipping', 49.99, NULL, '4082655P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5082135/michelin-pilot-sport-4-245-35r19-93-y-10383--9ca0fbd8-4647-45e8-8af7-6ee9be3903a8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Michelin', true, 39, false, false, false, '{}', 4.3751, 893, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":329,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000110', 'Uniroyal Power Paw Tire', 'uniroyal-power-paw-tire', 'Available in a variety of sizes. Long-lasting treadlife, now backed by a 45,000-mile warranty. Tru-Last Technology gives you long, even treadwear by managing stress within the tire footprint. When tested for treadwear, the UNIROYAL® Power Paw® All Season tire lasted at least 20% longer than its predecessor. Engineered to give you a confident ride. Wide, circumferential tread grooves and a new all season compound', 49.99, NULL, '5082286P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5082286/205-50zr17-93y-xl-uniroyal-power-paw-14782--1066d5b7-bef3-44cc-9067-ab149215fae2-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Uniroyal', true, 33, false, true, false, '{}', 3.4286, 7, '{"width":235,"aspect_ratio":60,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":274,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000111', 'Goodyear Eagle F1 Asymmetric 6 Tire for Passenger & CUV', 'goodyear-eagle-f1-asymmetric-6-tire-for-passenger-cuv', 'Goodyear Eagle F1 Asymmetrical 6 has highly refined compound with extra silica load. Asymmetric tread pattern helps to provide quick response and traction in turns when the weather changes. Shorter braking distance with excellent grip in both dry and wet. Tread pattern designed for minimal road noise, and light weight construction. Rim protectors built into the tire. Wheels sold separately', 49.99, NULL, '5085298P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5085300/235-40r18-95y-goodyear-eagle-f1-asym-6-112111668--74743941-7f78-46ae-a924-437723a214cc-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 24, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":297,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000112', 'Pirelli Cinturato P1 RFT Performance Tire For Passenger & CUV', 'pirelli-cinturato-p1-rft-performance-tire-for-passenger-cuv', 'A perfect synergy in terms of performance, safety, driving pleasure and attention to the environment. Hybrid materials and innovative tread pattern design create a more stable footprint to increases safety on both dry and wet conditions. Optimized tread design with specific pitch sequence reduces noise emissions. New materials and innovative compounds, aerodynamic sidewalls and lower weight reduce rolling resistance to lower fuel consumption and CO2 emissions. Wheels sold separately', 49.99, NULL, '2084763P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2084763/195-55r16-10-cinturato-p1-1961900--b2b14821-a2f0-490f-99c7-322e76c4a419-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 21, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":290,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000113', 'Goodyear Eagle F1 Asymmetric 3 SCT Tire', 'goodyear-eagle-f1-asymmetric-3-sct-tire', 'Asymmetric Tread Pattern: Offers powerful traction in turns and enhanced wet traction. Grip-Boosting Tread Compound: Enhances road adhesion for superior traction. Solid Center Rib - Helps to provide quick response and accurate on-center feel', 372.99, NULL, '5080437P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5080437/p265-40r20-104y-goodyear-eagle-f1-asym-3-sct-783158394--b6725ef5-b8db-47a9-94ff-62122b073406-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 10, false, false, false, '{}', NULL, NULL, '{"width":195,"aspect_ratio":60,"rim_diameter":16,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":312,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000114', 'Pirelli P ZERO Corsa Asimmetrico 2 Performance Tire For Passenger & CUV', 'pirelli-p-zero-corsa-asimmetrico-2-performance-tire-for-passenger-cuv', 'Combines directional (front axle fitment) and asymmetric (rear axle fitment or all-round application) tread designs to enhance not only performance, but also styling. Directional design with longitudinal grooves improve water expulsion and precise steering to improve safety in wet conditions and cornering capabilities. Asymmetric pattern designed wide contact area delivers extreme levels of handling in all situations. Wheels sold separately', 49.99, NULL, '2082050P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2084902/205-60r16-10-cinturato-p7-all-season-plus-2253400--fea3d39e-e4fa-4fce-a196-67f50e3847e7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 24, false, false, false, '{}', 5, 1, '{"width":245,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":331,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000115', 'Continental ContiSportContact 5 - SSR Tire', 'continental-contisportcontact-5-ssr-tire', 'The Continental ContiSportContact 5 - SSR Tire adapts to the road surface, giving improved grip and handling when accelerating and cornering. Excellent road grip, handling and safety when cornering. Featuring Black Chilli Technology. the ContiSportContact™ 5 is reactive, giving shorter braking distances on wet and dry roads. The unique tire composition ensures considerably reduced rolling resistance – for higher mileage and reduced fuel consumption. Reduced fuel consumption and improved mileage. Wheels sold separately', 49.99, NULL, '2083523P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2083523/245-40r17-91w-contisportcontact-5-03509520000--27596f6b-22a8-410e-bda4-63f6c796104d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 29, false, false, false, '{}', NULL, NULL, '{"width":195,"aspect_ratio":65,"rim_diameter":15,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":307,"traction":"AA","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000116', 'Goodyear Eagle Sport A/S RFT Performance Tire For Passenger & CUV', 'goodyear-eagle-sport-a-s-rft-performance-tire-for-passenger-cuv', 'Goodyear Eagle Sport All-Season ROF Tire features a proven asymmetric tread offers both responsive handling and exceptional all-season grip. An innovative tread compound that delivers outstanding wet and dry performance, with enhanced grip in ice and snow. Run On Flat tires are designed to perform when deflating or even once deflated. Allows you to drive at a top speed of 80 kph for up to 80 km to help you reach a safe place or service area. Wheels sold separately', 49.99, NULL, '2088880P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0051000/195-55r15-85v-eagle-as-109911366--65033b61-d114-4ae6-8252-479f50439488.png', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 17, false, true, false, '{}', 3.9667, 30, '{"width":265,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":288,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000117', 'Goodyear Eagle Touring SoundComfort Technology® Tire', 'goodyear-eagle-touring-soundcomfort-technology-tire', 'Optimized tire contact area with road for enhanced handling and responsiveness. Biting edges help to provide confident all-season traction in wet, dry and snowy conditions. Optimized tread pattern helps to quiet noise from on-road driving', 461.99, NULL, '5080419P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2081865/goodyear-eagle-touring-sct-245-40r20-102003387--aa0b031d-04b7-454d-a775-9c1dc1b5ee76-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 37, false, false, false, '{}', 4.5, 6, '{"width":225,"aspect_ratio":45,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":260,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000118', 'Goodyear EfficientGrip RFT Performance Tire For Passenger Vehicles & CUVs', 'goodyear-efficientgrip-rft-performance-tire-for-passenger-vehicles-cuvs', 'Original equipment on many models and makes of vehicles. Wide circumferential grooves help evacuate water for great rain performance. Special tread block sequence helps improve handling and traction while reducing tread noise. Premium side wall styling with a contemporary look. Optimized silica tread compound. Original equipment tuned asymmetric tread design. Provides responsive handling and smooth touring ride. Advanced Run On Flat technology keeps on going even when punctured. Wheels sold separately', 49.99, NULL, '2088585P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2088598/195-55r16-87w-efficientgrip-perfrofstr-112015379--b24ae3ae-e562-43d2-a388-bdc3385a9cc9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 13, false, false, true, '{}', 5, 1, '{"width":275,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":308,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000119', 'Bridgestone Turanza T001 RFT Tire', 'bridgestone-turanza-t001-rft-tire', 'The Turanza tire model offers luxury performance with a quiet ride. Confident wet and dry performance. Long wear life. Wheels sold separately', 49.99, NULL, '3083354P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3083415/-225-50r18-95w-bridgestone-turanza-t001-rft-005323--3bd1b73d-480b-409b-9cee-ea38ca6812d5-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 21, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":40,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":326,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000011a', 'Yokohama ADVAN Sport V107E Tire', 'yokohama-advan-sport-v107e-tire', 'The Yokohama ADVAN Sport V107E tire is built to provide drivers of high-performance sedans, CUVs and SUVs with confident performance and handling on wet or dry roads. Improves grip for cornering and braking on both wet and dry roads. Improves steering performance on dry roads by efficiently transferring power to the road surface. Improved contour profile creates an expanded contact patch and even pressure on the road for enhanced stability at high speeds. Specially designed sipes provide a quiet ride. Wheels sold separately', 49.99, NULL, '5084056P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5081704/225-45zr18-95y-yokohama-advan-sport-v107-110110711--9c0f6c0c-346f-47bb-8315-d09fed32401f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Yokohama', true, 18, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":45,"rim_diameter":19,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":322,"traction":"AA","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000011b', 'Bridgestone Turanza T005 AD Tires for Passenger & CUV', 'bridgestone-turanza-t005-ad-tires-for-passenger-cuv', 'A premium Grand Touring summer tire designed to be fitted to passenger sedans and sport utility vehicles. For drivers who want a combination of sophisticated appearance, competent handling and H-speed rated (or higher) durability, along with dry and wet traction from their tires. Wheels sold separately. NanoPro-Tech technology improves the dispersion of silica in the mix of silicone-rich compound to maximize traction power on wet pavement.. Large number of shoulder lugs improve water evacuation and drainage. Available in a wide range of sizes, from 14 to 21"', 49.99, NULL, '0081799P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4087520/245-40r21-100y-bridgestone-turanza-t005-ad-008944--e40f3aaf-d826-4ba5-9786-85c7dd834660-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 36, false, true, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":324,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000011c', 'Bridgestone Potenza S005 All Season Tire for Passenger & CUV', 'bridgestone-potenza-s005-all-season-tire-for-passenger-cuv', 'Excellent handling with precise steering responsiveness. Optimized contact patch improves high-speed stability and wet performance. "Enliten" technology on some sizes provides reduced weight, lower rolling resistance, and improved fuel consumption. Enhanced braking capabilities in dry and wet conditions alike. Wheels sold separately', 49.99, NULL, '5084608P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5082105/235-35r19-91y-bridgestone-potenza-s005-011594--fe322d2e-e853-476d-a2a2-0c93e2a2bbb5-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 12, false, false, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":307,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000011d', 'Bridgestone Turanza EL42 Tire', 'bridgestone-turanza-el42-tire', 'Luxury performance tire with a quiet ride. This all-season tire provides great wet and dry performance. As found as Original Equipment on popular vehicles. Wheels sold separately', 49.99, NULL, '3080204P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3080204/p245-45r19-98v-turan-007906--838198f5-7500-46b8-ad88-941d5423ccb5-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 26, false, false, false, '{}', 3.4013, 304, '{"width":255,"aspect_ratio":60,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":261,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000011e', 'Bridgestone Turanza 6 SP All-Season Tire for Passenger & CUV, for Dry/Wet Roads & Light Snow', 'bridgestone-turanza-6-sp-all-season-tire-for-passenger-cuv-for-dry-wet-roads-lig', 'Responsive driving on dry, wet, and lightly snow-covered surfaces. Offers precise handling and road-holding. Improved fuel/energy efficiency. Superior mileage. Combines comfort and performance thanks to a design that promotes a pleasant, quiet ride on the road', 49.99, NULL, '5082112P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5086015/275-30r21-95y-turanz-f171808f-1f85-44f8-988f-5d8431cdaa36-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 34, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":354,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000011f', 'Goodyear Eagle F1 Super Car EMT Performance Tire For Passenger & CUV', 'goodyear-eagle-f1-super-car-emt-performance-tire-for-passenger-cuv', 'Goodyear Eagle F1 Super Car EMT Tire is an ultra high-performance all-season tire with carbon fibre reinforced sidewalls for crisp and responsive handling. Designed with multiple "zones" for different tractions in different conditions.. Specialized ultra high-performance construction tire for select high-end OE fitments for supercars. Wheels sold separately', 49.99, NULL, '0081875P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0081875/goodyear-eag-f1-super-car-emt-p275-35zr18-87y-412561506--d9929287-540e-45f1-b5c0-3be586da9eda-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 23, false, true, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":285,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000120', 'Bridgestone Potenza S001 Tire For Passenger & CUV', 'bridgestone-potenza-s001-tire-for-passenger-cuv', 'Engineered to meet the demands of a variety of top-tier cars. Original equipment (OE) fitment. Maximum sports performance in all weather conditions. Industry leading stopping distances. Very high resistance to hydroplaning. Outstanding agility and grip. Optimized for precision handling and control during spirited driving. Delivers consistent traction for confident driving in tight corners', 49.99, NULL, '3080171P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5082104/275-35rf21-99y-bridgestone-potenza-s001l-rft-013746--c79056b4-7c1b-490b-8384-122fddcf84d8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 31, false, false, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":300,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000121', 'Continental ContiSportContact 5P Performance Tire', 'continental-contisportcontact-5p-performance-tire', 'Designed with Electric Vehicles (EVs) in mind. Asymmetrical tread pattern and compact outer shoulders provide excellent cornering stability. Solid central ribs improve tire stability and steering precision. Comes with Total Confidence Plan: Includes a 60-day trial and 3 years of roadside assistance. Wheels sold separately', 490.99, NULL, '3081219P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5080114/255-35zr19-96-y-conti-contisportcontact-5p-03589890000--71157a24-8729-4a2b-b8ea-686d397e80ee-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 15, false, false, true, '{}', NULL, NULL, '{"width":235,"aspect_ratio":60,"rim_diameter":17,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":275,"traction":"AA","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000122', 'Bridgestone Turanza T005 SP Tire For Passenger & CUV Tires', 'bridgestone-turanza-t005-sp-tire-for-passenger-cuv-tires', 'Original equipment on many popular vehicles. Quiet, comfortable ride. Confident wet and dry performance. Wheels sold separately', 49.99, NULL, '4087522P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4087520/245-40r21-100y-bridgestone-turanza-t005-ad-008944--e40f3aaf-d826-4ba5-9786-85c7dd834660-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 27, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":335,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000123', 'Bridgestone Potenza RE980AS Plus Tire for Passenger & CUV', 'bridgestone-potenza-re980as-plus-tire-for-passenger-cuv', 'New ultra-high compound delivers improved snow traction while providing confident wet and dry performance and a more comfortable ride. Intense stopping power in the winter plus grip and handling in both wet and dry conditions. Precise handling and steering response.. Wheels sold separately. Advanced tread pattern is engineered with 3D full depth sipes and chamfered slots to provide reliable wet and dry braking. See-through void and open shoulder slots help reduce the risk of hydroplaning by channeling water away from the contact patch. Tire size: 205/45R17. Blackwall sidewall styling. Tire diameter: 24.3"/61/7cm', 49.99, NULL, '0081509P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0081509/-265-40r18-bridgestone-potenza-re980as-plus-012779--bec69c95-df5c-4283-9f21-0cc14d69c725-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 34, false, true, false, '{}', 4.4634, 41, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":324,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000124', 'Continental ContiPremiumContact 2 Performance Tire For Passenger & CUV', 'continental-contipremiumcontact-2-performance-tire-for-passenger-cuv', 'Continental ContiPremiumContact 2 Tire features a 3-D groove technology allows water to be dispersed more efficiently, providing great traction in wet conditions. Designed to provide great stability and handling. Due to an increased number of tread blocks and an open inner shoulder, water is dispersed more efficiently. The harmonious round shape of the ground contact patch provides excellent protection against aquaplaning. The asymmetric tread pattern stiffens the tire shoulder and provides optimum road contact. Wheels sold separately', 49.99, NULL, '2081065P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/2081065/205-55r16-91v-contipremiumcontact-2-3502220000--fa21c89e-8904-4557-a372-b4d0f371da28-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 20, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":346,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000125', 'Bridgestone Potenza Sport Evo for Performance Passenger & CUV', 'bridgestone-potenza-sport-evo-for-performance-passenger-cuv', 'ENLITEN Technology delivers a remarkable balance of performance and sustainability elements. Responsive steering. Wide shoulder design to increase contact area with the road to maximize dry performance. Advanced tread compound delivers dynamic sporty grip for stability and confident handling. Confident wet performance', 49.99, NULL, '7080052P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/7080100/275-35r21-103y-bridgestone-potenza-sport-evo-014245--a24039d1-16f3-45d1-84be-e35c45e7168f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 15, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":348,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000126', 'Continental ContiSportContact 2 Performance Tire For Passenger & CUV', 'continental-contisportcontact-2-performance-tire-for-passenger-cuv', 'This Continental ContiSportContact 2 Tire is designed for performance sport coupes and sedans. Engineered with extra-wide circumferential and lateral grooves which help to evacuate water and reduce the changes of hydroplaning. The asymmetrical pattern guarantees maximum ground adhesion in any driving situation. This is ensured by the closed outer shoulder section and the pronounced strips of tread rubber around the tire''s circumference. Wheels sold separately', 49.99, NULL, '0088804P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0081431/245-40r18-93y-tl-fr-889fe358-9d20-4195-98d6-f49348d4a7aa-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 31, false, false, false, '{}', 5, 1, '{"width":275,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":280,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000127', 'Bridgestone Turanza ER300 RFT Tire', 'bridgestone-turanza-er300-rft-tire', 'Original Equipment (OE) on popular vehicles, typically purchased as direct replacements for worn-out pairs/sets of the vehicle''s original tires; they can also be used for other vehicle applications when accurately matched. Grand touring, run-flat tires (RFT) provide temporary self-supporting run-flat mobility for a distance of 50 miles/80km at up to 50 mph/80 kph, even after a puncture has allowed complete air pressure loss. Confident wet and dry performance; not intended to be driven in near-freezing temperatures, through snow or on ice. Wheels sold separately. Low-profile, black sidewall. Engineered for comfort, safety and long miles', 484.99, NULL, '3080074P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3085979/215-55r17-94h-turanza-ls100-011875--4165315d-f978-4440-b4ea-7c85085846c5-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 24, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":55,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":308,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000128', 'Bridgestone Potenza S007 Tire', 'bridgestone-potenza-s007-tire', 'Original equipment on high performance vehicles. Engineered for response, control and cornering. Confident wet and dry performance. Offers a quiet ride', 49.99, NULL, '3084885P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5084610/245-35r19-93y-bridgestone-potenza-s007-018902--f52200e3-dc5b-4100-8adc-1484e6402220-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 15, false, false, false, '{}', 4.0444, 270, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":314,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000129', 'Bridgestone Dueler A/T 002 RFT Tire for Passenger & CU', 'bridgestone-dueler-a-t-002-rft-tire-for-passenger-cu', 'A quiet and enjoyable driving experience. Exceptional all-terrain performance. Remarkable traction on all road surfaces. An elegant and high-performance design. Wheels sold separately', 49.99, NULL, '5084573P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5084573/rf235-40zr19-96y-bridgestone-dueler-a-t-002-rft-014836--5033a356-07c7-4f67-a430-154a4ee5cc2b-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 22, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":60,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":335,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000012a', 'Continental Conti4x4SportContact All Season Tire For Passenger & CUV', 'continental-conti4x4sportcontact-all-season-tire-for-passenger-cuv', 'The asymmetrical tread pattern of the Continental Conti4x4SportContact Tire ensures excellent cornering stability. Good cornering stability. The tire''s grooves are designed to provide good contact patch drainage, offering excellent protection against aquaplaning. The tire''s design allows for ultimate road performance. Suitable for high-speed road use. Wheels sold separately', 612.99, NULL, '0086306P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/0086306/continental-4x4-sport-contact-275-45r19-108y-03546310000-bd204b82-ddbc-42c0-9754-ef4aa39ce8dd-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 19, false, true, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":328,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000012b', 'Goodyear Eagle F1 Asymmetric 5 ROF Performance Tire', 'goodyear-eagle-f1-asymmetric-5-rof-performance-tire', 'Chosen as original equipment by global vehicle manufacturers. Next-generation polymer tread compound enhances grip on dry roads, and enhances wet traction. Active CornerGrip® technology helps maintain even tread pressure. Enhanced grip while cornering', 49.99, NULL, '5084872P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5085214/265-40r21-105h-goodyear-eag-f1-asym5-rofsct-103020633--f6eb650c-c89d-4b07-b487-e670df81c38a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 38, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":40,"rim_diameter":18,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":279,"traction":"AA","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000012c', 'Continental ContiSportContact 5 SUV Tire', 'continental-contisportcontact-5-suv-tire', 'Continental ContiSportContact 5 SUV Tire is designed for high-performance and luxury vehicles. Excellent road grip, handling and safety when cornering. Shorter braking distances in all weather conditions. Reduced fuel consumption and high mileage. Wheels sold separately', 49.99, NULL, '2083070P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2083070/295-40r22-112y-tl-xl-fr-csptcnct-5-suvcontislnt-03544230000--e6a3c6db-73bd-468f-ad10-01fe144d8110-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 11, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":305,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000012d', 'Bridgestone Turanza LS100 RFT Tire for Passenger & CUV', 'bridgestone-turanza-ls100-rft-tire-for-passenger-cuv', 'Designed for drivers who want a combination of sophisticated appearance, competent handling and high speed-rated durability. Grand touring tire, often used as Original Equipment (O.E.) on sophisticated coupes and luxurious performance sedans. All-season traction, including in light snow. High-quality materials minimize vibrations and road noise for a smooth and quiet ride. Specially designed tread pattern offers exceptional grip on all road surfaces for optimal stability and maneuverability. Typically purchased as direct replacements for worn-out pairs/sets of the vehicle''s original tires. They can also be used for other vehicle applications when correctly matched', 49.99, NULL, '3085622P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3085622/225-45r18-turanza-ls100-a-rft-011744--cea12c34-a39f-4c42-9393-8c6a7b2bf63d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 28, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":291,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000012e', 'Bridgestone Turanza EL400-02 RFT Tire for Passenger & CUV', 'bridgestone-turanza-el400-02-rft-tire-for-passenger-cuv', 'Features an all-season rubber compound molded into a symmetric tread design. Straight circumferential grooves to balance dry and wet road traction. Side Support Run-Flat technology-reinforced sidewalls specifically tuned to support the vehicle. Includes twin steel belts reinforced by spirally wrapped nylon to blend high-speed durability with uniform ride quality. Noise comfort and hydroplaning resistance', 49.99, NULL, '3082496P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3082496/205-50r17-89v-turan-bridgestone-000237--a70ef88a-1c0f-4641-9e4d-7a2ff88da7fc-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 26, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":301,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000012f', 'Goodyear Eagle F1 Asymmetric 2 ROF Tire for Passenger & CUV', 'goodyear-eagle-f1-asymmetric-2-rof-tire-for-passenger-cuv', 'Goodyear Eagle F1 Asymmetric 2 ROF Tire is built for responsive handling and control in both dry and wet conditions. Lightweight, racing-derived construction reduces unsprung mass for enhanced steering precision and handling. Active Braking Technology offers enhanced stopping power on wet and dry roads. Advanced tread block pattern helps reduce excessive road noise. RunOnFlat® technology allows for driving up to 50 mi.on a deflating or deflated tire at a top speed of 50 mph', 49.99, NULL, '5085224P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5085224/225-40r19-89y-goodyear-eagle-f1-asym-2-rof-784196359--4080b110-aee1-42b9-965d-71d050d90343-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 10, false, true, false, '{}', 3.3846, 13, '{"width":245,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":302,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000130', 'Bridgestone Turanza EL400 02 RFT Tire', 'bridgestone-turanza-el400-02-rft-tire', 'Original Equipment on Popular Vehicles. Comfortable ride. Confident wet and dry performance', 49.99, NULL, '3080320P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3080181/245-45r17-95h-turanz-002738--f88a5636-bc8e-49fe-9fbb-48f1a6e31e67-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 39, false, false, false, '{}', NULL, NULL, '{"width":205,"aspect_ratio":65,"rim_diameter":16,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":287,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000131', 'Bridgestone Potenza RE050A Scuderia Tire for Passenger & CUV', 'bridgestone-potenza-re050a-scuderia-tire-for-passenger-cuv', 'The Potenza RE050A Scuderia was developed to provide excellent traction along with responsive and predictable handling on dry and wet roads. Features a high-grip tread compound molded into an asymmetric tread design. Continuous rib adjacent to the inboard shoulder blocks promotes even wear and resists inside wear. Includes twin steel belts reinforced by spiral-wrapped nylon to stabilize the tread area and enhance handling as well as high-speed capability. Stable outboard shoulder elements, intermediate tread blocks and a continuous center rib provide responsive handling, high-speed stability and traction on dry roads', 49.99, NULL, '3080090P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3080090/245-35r19-89y-bridgestone-potenza-re050a-000927--7130f330-d6b0-4756-b870-b578f842acb9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 23, false, false, false, '{}', NULL, NULL, '{"width":215,"aspect_ratio":75,"rim_diameter":15,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":266,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000132', 'Goodyear Eagle F1 Asymmetric 3 ROFSCT Performance Tire', 'goodyear-eagle-f1-asymmetric-3-rofsct-performance-tire', 'Offers enhanced wet and dry traction across all seasons. TredLock technology uses microgrooves to provide biting edges for commanding wet traction and grip when turning. Proven asymmetric tire tread for precise, race-inspired handling on wet or dry roads. Dry handling zone puts more rubber on the road for superb dry traction and handling', 587.99, NULL, '5085243P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5085243/245-35r20-95y-goodyear-eag-f1-asym-3-rofsct-783129394--6ead0457-ec37-4ed6-852f-336b7784c7e0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 38, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":40,"rim_diameter":20,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":325,"traction":"AA","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000133', 'Goodyear Eagle F1 Asymmetric 5 ST Tire', 'goodyear-eagle-f1-asymmetric-5-st-tire', 'Highly Refined Compound with Extra Silica Load: Provides predictable traction in turns when the weather changes. Contact Patch Extension - Shorter braking distance with excellent grip in both dry and wet. Stiff Coupling of Carcass & Pattern - Rim protectors built into the tire', 49.99, NULL, '5080427P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5080427/p285-35r21-105y-goodyear-eagle-f1-asym-5-st-103027654--5e48cf4e-056f-4082-b3cd-e898697fffea-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 27, false, false, true, '{}', NULL, NULL, '{"width":255,"aspect_ratio":50,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":337,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000134', 'Pirelli PZero Nero Tire', 'pirelli-pzero-nero-tire', 'Feature wide continuous ribs and asymmetric design. Provides stability for fast cornering reaction and improved handling. The technologically enhanced profile structure provides even footprint pressure distribution for high speed braking in both wet and dry conditions. High performance compound provides reduced temperature sensitivity for constant performance at high speeds', 49.99, NULL, '2084838P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2081249/pirelli-p-zero-nero-205-40zr17-3994200--c8159a49-6623-47a9-a20e-c3a7115b5422-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 21, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":45,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":262,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000135', 'Bridgestone Potenza S001L Tire', 'bridgestone-potenza-s001l-tire', 'Original equipment on many popular vehicles. Often used as Original Equipment (O.E.) on powerful sports cars, performance coupes and high performance sedans. Designed for serious driving enthusiasts who want a combination of a performance appearance, competent handling. Z-speed rated (or higher) durability with enhanced dry and wet traction. Wheels sold separately', 49.99, NULL, '4087422P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4087422/235-40r19-92y-bridgestone-potenza-s001l-012808--27df9343-c675-469c-b327-dd71531cfbca-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 14, false, true, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":45,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":278,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000136', 'Pirelli P-Zero Corsa (PZC4) Tire for Passenger & CUV', 'pirelli-p-zero-corsa-pzc4-tire-for-passenger-cuv', 'Delivers exceptional performance both on the road and track. Dual-compound tread technology ensures an ideal balance between high-speed driving and exceptional grip and traction, offering drivers a superior performance and handling experience. Motorsport-inspired materials that improve resistance to high thermo-mechanical stress, ensuring greater durability and reliability in extreme driving conditions. Hard handling performance, high speed cornering and impressive lateral acceleration managed by the massive tread blocks on the shoulder and the central continuous rib. Wheels sold separately', 49.99, NULL, '5083991P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5083991/255-40r22-103y-pirelli-p-zero-corsa-pzc4-3785900--9732d16e-17df-4c9a-beda-db3ca99948c8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 24, false, true, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":357,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000137', 'Bridgestone Potenza RE040 Performance Tire For Passenger & CUV', 'bridgestone-potenza-re040-performance-tire-for-passenger-cuv', 'Features Innovative tread compound which improves tire wear and enhances wet-weather performance. Engineered for control, response and cornering. As found as Original Equipment on popular vehicles. Wheels sold separately. Ultra responsive on all four corners', 49.99, NULL, '3080788P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3080549/235-60r16-100w-poten-065187--b1df0131-2e9c-436c-9d48-bbbba8dbe06b.png', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 10, false, false, true, '{}', 3.52, 175, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":353,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000138', 'Goodyear Eagle F1 SUV AT Self Seal All Season Tire', 'goodyear-eagle-f1-suv-at-self-seal-all-season-tire', 'Offers enhanced braking in light snow and off-road conditions. For increased traction on snow covered roads. Provides maximum grip on soft soil, mud, and wet grass. Self-Seal technology offers convenience and safety by automatically sealing minor punctures, reducing the likelihood of needing immediate tire changes. Features designed to reduce road noise and vibrations contribute to a more enjoyable driving experience', 612.99, NULL, '5085303P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5085303/255-50r20-109w-goodyear-eag-f1suvat-selfseal-784154670--966829da-7049-4922-9af1-dc9e2897ffc9-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 35, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":301,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000139', 'Bridgestone Potenza RE97AS RFT Tire', 'bridgestone-potenza-re97as-rft-tire', 'Original Equipment on Popular Vehicles. All-season performance. Run-Flat Technology. Reliable wet and dry performance', 430.99, NULL, '3085600P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3080017/p225-55rf17-95v-pote-000236--bea84d64-06b0-4ee4-8522-119483bda763-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 22, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":35,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":292,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000013a', 'Yokohama ADVAN Neova AD07 Tire', 'yokohama-advan-neova-ad07-tire', 'Yokohama ADVAN Neova AD07 is a summer extreme performance tire made for performance sedans, sports cars and coupes. ADVAN Neova will allow you to push your car to new levels while maintaining constant, predictable control. Delivers true driving vigor to those demanding ultimate performance', 49.99, NULL, '4087577P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4087577/175-55r16-80w-neova-ad07-110107035--eee625f9-ef42-4501-aac2-c762f58bbc7f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Yokohama', true, 18, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":45,"rim_diameter":19,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":260,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000013b', 'Goodyear Eagle F1 Asymmetric 3 SUV All Season Tire For Passenger & CUV - FD', 'goodyear-eagle-f1-asymmetric-3-suv-all-season-tire-for-passenger-cuv-fd', 'Asymmetric tread pattern with grip-boosting tread compound. Advanced construction with a solid center rib. Offers powerful traction in turns and enhanced wet traction. Enhances road adhesion for superior traction. Tuned for ultra high-performance suspension system. Helps to provide quick response and accurate on-center feel', 49.99, NULL, '4083194P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4083198/245-45r21-104y-xl-ea-783043544--5338e1c2-32f1-42fd-9e4c-f17d6fcf3c7b-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 19, false, false, false, '{}', 4.5714, 7, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":294,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000013c', 'Bridgestone Potenza RE050A II RFT Tire', 'bridgestone-potenza-re050a-ii-rft-tire', 'Run Flat Tire (RFT) technology with reinforced sidewalls keeps your vehicle traveling under control after a puncture. This tire delivers ultimate handling and response, allowing you to take sharp turns with maximum precision. As found as Original Equipment on popular vehicles. Wheels sold separately', 49.99, NULL, '3080558P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3080558/225-45r17-91v-potenz-067346--258aaa29-f968-4e1d-b466-40975b8ed038-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 16, false, false, false, '{}', NULL, NULL, '{"width":225,"aspect_ratio":60,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":348,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000013d', 'Bridgestone Turanza T001 Tire for Passenger & CUV', 'bridgestone-turanza-t001-tire-for-passenger-cuv', 'Smooth and comfortable ride. Safe and secure handling under all conditions. Noise reduction technology. Wheels sold separately', 255.99, NULL, '5084709P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5084709/215-65r16-98h-bridgestone-turanza-t001-005557--b1a74623-088b-47a1-80cd-3634a4b92b42-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 23, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":266,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000013e', 'Continental ContiSportContact 5P RFT Performance Tire For Passenger & CUV', 'continental-contisportcontact-5p-rft-performance-tire-for-passenger-cuv', 'Its most innovative technology makes the Continental ContiSportContact 5P SSR Tire is a safe, ultra-high performance tire for sporty cars, and gives maximum fun at the wheel. The solid, sturdy central ribs, attached tread lugs, plus asymmetrical tread ribs ensure optimum, longitudinal stiffness in the tire and reduced movement in the tread. This means steering forces are transmitted straight to the road.. Outstanding grip and stability during cornering. Wheels sold separately', 49.99, NULL, '2083530P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2083530/255-35r19-96y-contisportcontact-5p-03519580000--44e5bbee-5cc1-42f1-ba71-3ffc5582fe0d.png', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 32, false, true, true, '{}', 1, 1, '{"width":285,"aspect_ratio":50,"rim_diameter":20,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":321,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000013f', 'Bridgestone Potenza RE050A I RFT Tire', 'bridgestone-potenza-re050a-i-rft-tire', 'Run Flat Tire (RFT) technology with reinforced sidewalls keeps your vehicle travelling under control after a puncture. Stabilized centre blocks with tie bar rib improve cornering and the wide circumferential grooves improve wet traction. As found as Original Equipment on popular vehicles. Wheels sold separately. Specially shaped block edges with slanted mid-grooves enhance wet performance. Alternating block dimensions and block shape helps reduce noise', 49.99, NULL, '3081193P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3080503/255-55r18xl-109h-due-058234--5012b648-311b-4f17-b0a0-1dd880abc9db-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 33, false, true, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":40,"rim_diameter":19,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":274,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000140', 'Bridgestone Turanza EL400-02 Tire', 'bridgestone-turanza-el400-02-tire', 'Offers wet and dry traction while providing a surprisingly comfortable ride. Innovative compound increases wear resistance. Silica improves traction in wet conditions by increasing flexibility of tread compound. Wheels sold separately. Ideal for everyday driving, balancing performance and comfort seamlessly. Highway-rated for enhanced stability and comfort on paved surfaces', 223.99, NULL, '3080058P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3080064/p205-60r15-90h-turan-dcbee6aa-fa41-4dc7-9418-ddffd8a97adf-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 13, false, true, false, '{}', NULL, NULL, '{"width":225,"aspect_ratio":50,"rim_diameter":17,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":338,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000141', 'Pirelli P ZERO Plus Performance Tire For Passenger & CUV', 'pirelli-p-zero-plus-performance-tire-for-passenger-cuv', 'Combines two different tread designs for ultra-high performance. Twin steel belts reinforced with nylon cap plies on top of a rayon casing. Blends responsive handling with high-speed durability. Heightened performance in wet and dry conditions', 519.99, NULL, '2089775P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2085339/245-45r18-100w-xl-pzras--1be3ca84-cbe2-434c-92e6-829c69d42647-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 28, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":271,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000142', 'Goodyear Eagle F1 GS EMT Performance Tire For Passenger & CUV', 'goodyear-eagle-f1-gs-emt-performance-tire-for-passenger-cuv', 'Goodyear Eagle F1 GS EMT is an ultra high-performance tire for specialty and OE applications. Solid centreline and large shoulder elements to help provide responsive steering and confident cornering. Multi-radius profile for confident steering and consistent, uniform wear. Wheels sold separately', 49.99, NULL, '0081871P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0081871/goodyear-eagle-f1-gs-emt-p245-45zr17-89y-406375063--b828d93f-f956-4e01-aa8a-ce97cf14ce60-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 37, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":330,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000143', 'Bridgestone Potenza RE070 Tire', 'bridgestone-potenza-re070-tire', 'A high-performance summer tire for passenger-style sports cars; not for use when temperatures are below 45 degrees Fahrenheit. Steel-belted radial design and a tread pattern that enhances traction in wet or dry weather. As found as Original Equipment (OE) on popular vehicles. Wheels sold separately. Outstanding steering response and cornering. Low-profile, blackwall sidewall', 49.99, NULL, '3080024P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3082546/205-45r17-84w-poten-bridgestone-004663--2be8fbdb-0909-4f51-9c67-a9d65c1362d8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 11, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":40,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":325,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000144', 'Bridgestone Ecopia EP600 Tire', 'bridgestone-ecopia-ep600-tire', 'Designed to deliver significant improvements in tire rolling resistance. Reduces energy consumption to enhance vehicle range. Helps drivers maintain their vehicle''s sporty appearance. As found as Original Equipment on popular vehicles. Wheels sold separately', 49.99, NULL, '3080148P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/3080148/-ev155-70r19-84q-ecopia-001475--66374e40-c09d-4e65-ace4-08e6c0ec2533-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 25, false, false, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":312,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000145', 'Yokohama ADVAN Sport® V105 Tire', 'yokohama-advan-sport-v105-tire', 'The ADVAN Sport V105 delivers an exceptional driving experience. Wider tread blocks on the outside of the tread enhance dry performance while the increased groove area on the inner portion maximizes wet performance. Variable pitch tread reduces pattern noise offering a quiet and comfortable ride', 437.99, NULL, '4088512P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4088512/245-50r18-advan-v105c-110110640--89281d4a-6e91-453d-8a5e-a3b744199d8d-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Yokohama', true, 21, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":45,"rim_diameter":18,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":316,"traction":"AA","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000146', 'Pirelli P-Zero R Performance Tire for Passenger & CUV with Durable Tread', 'pirelli-p-zero-r-performance-tire-for-passenger-cuv-with-durable-tread', 'Enhanced footprint pressure distribution in dynamic condition (braking/handling) to guarantee balanced and predictable behavior. New compound to reduce the trade off between grip/ rolling resistance/ wet. Lighter construction to reduce weight with same lateral stiffness characteristics. Multi-compound tread to maximize performance of each tread area. Wheels sold separately', 49.99, NULL, '5083993P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5085582/-ev255-35zr20-97y-pirelli-pzero-r-4455200--0c1d64d7-0260-4c78-92c9-34e2c17cbad7-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 28, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":311,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000147', 'Michelin Latitude Sport All Season Tire For Passenger & CUV', 'michelin-latitude-sport-all-season-tire-for-passenger-cuv', 'World-class dry and wet road traction summer tires. FAZ Technology™ adds reinforcement under the tread for enhanced stability and precise handling at high speeds. This is the choice of preeminent SUV and Crossover manufacturers. Ultra high performance tire that delivers sport performance handling. Wheels sold separately. Optimized tread pattern reduces road noise for a quieter ride. Provides long-lasting performance with wear-resistant materials. Built to maintain traction during high-speed maneuvers', 49.99, NULL, '0086831P', 'https://media-www.canadiantire.ca/product/automotive/tires/light-truck-tires/0086831/michelin-latitude-sport-255-55r18-109y-91991--4f7f3795-0406-4501-a470-909adae79bfd-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Michelin', true, 36, false, false, false, '{}', 4.3233, 133, '{"width":265,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":286,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000148', 'Pirelli P-Zero™ Asimmetrico Performance Tire For Passenger & CUV', 'pirelli-p-zero-asimmetrico-performance-tire-for-passenger-cuv', 'Delivers superb road handling performance with excellent resistance to aquaplaning and maximum braking performance. Full and compact external shoulder blocks increase dry handling performance and safety, while the inner shoulder with its deeper and more regular cuts is geared towards maximizing traction. Four wide longitudinal grooves help evacuate water to reduce the risk of hydroplaning. Wheels sold separately', 49.99, NULL, '0089337P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0089337/205-50zr15-86w-zero-0731900--11b6fd57-61c8-4116-9eed-94081f58d74a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 15, false, false, false, '{}', NULL, NULL, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":307,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000149', 'Cooper Zeon CrossRange NRT Performance Passenger & CUV Tires', 'cooper-zeon-crossrange-nrt-performance-passenger-cuv-tires', 'Cooper Zeon CrossRange NRT features an advanced all-season tread pattern designed to provide balanced performance across different weather conditions. Tread includes an array of grooves, sipes, and patterns to handle dry, wet, and light snow conditions. Design focus ensures a quieter and smoother driving experience, which is beneficial for both daily commutes and longer journeys', 49.99, NULL, '5084851P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5085416/255-45r20-105h-cooper-zeon-crossrange-160085014--67e4526b-46df-499a-bee9-d3310687b341-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Cooper Tires', true, 15, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":345,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000014a', 'Goodyear Eagle F1 Asymmetric 2 High Performance SUV Tires', 'goodyear-eagle-f1-asymmetric-2-high-performance-suv-tires', 'High performance tire. Features a tread compound with motosport resins which help provide superior dry handling. Lightweight, racing derived construction. Advanced tread block pattern reduces excessive road noise. Wheels sold separately', 49.99, NULL, '2088968P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/2088966/235-55r19-101y-sl-eagle-f1-asym2-suv-nof-784437348--e6f3a98e-0c60-4d31-87b2-478c2dbb1d84-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 18, false, false, false, '{}', 4.3667, 30, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":266,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000014b', 'Goodyear Eagle Sport A/S SCT All-Season Tire', 'goodyear-eagle-sport-a-s-sct-all-season-tire', 'Proven Asymmetric Tread - Offers both responsive handling and exceptional all-season grip. Innovative Tread Compound - Offers outstanding wet and dry performance, with enhanced grip in ice and snow. Full-Depth Sipes - Offer biting edges for confident grip as the tire wears', 49.99, NULL, '5080422P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5080422/p255-45r19-104h-goodyear-eagle-sport-a-s-sct-109166382--cfc1e0c3-c381-43e8-b753-4db75d3b634b-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 11, false, false, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":40,"rim_diameter":19,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":353,"traction":"AA","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000014c', 'Pirelli P-Zero™ Corsa Asimmetrico Performance Tire For Passenger & CUV', 'pirelli-p-zero-corsa-asimmetrico-performance-tire-for-passenger-cuv', 'Ultra high-performance tire for supercars and racing enthusiasts. Uses a race class rubber compound. Delivers extreme levels of handling in all situations. Wheels sold separately. Asymmetrical tread pattern for added stability. Designed for maximum traction and braking levels', 49.99, NULL, '0089900P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5084329/335-30r18-102y-pirelli-pzero-corsa-asimmetrico-4214300--d821b9fd-8137-4b8d-a8c5-b111439ceded-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 32, false, false, false, '{}', 5, 1, '{"width":275,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":269,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000014d', 'Bridgestone Turanza EL400 02 MOE Tire', 'bridgestone-turanza-el400-02-moe-tire', 'Original Equipment on Popular Vehicles (Mercedes-Benz). Comfortable ride. Confident wet and dry performance. Quiet performance', 49.99, NULL, '3080165P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3080181/245-45r17-95h-turanz-002738--f88a5636-bc8e-49fe-9fbb-48f1a6e31e67-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 25, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":45,"rim_diameter":19,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":346,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000014e', 'Goodyear Eagle F1 AT Self Seal All Season Tire for Passenger & CUV', 'goodyear-eagle-f1-at-self-seal-all-season-tire-for-passenger-cuv', 'Offers enhanced braking in light snow and off-road conditions. For increased traction on snow covered roads. Provides maximum grip on soft soil, mud, and wet grass. Self-Seal technology offers convenience and safety by automatically sealing minor punctures, reducing the likelihood of needing immediate tire changes. Features designed to reduce road noise and vibrations contribute to a more enjoyable driving experience', 602.99, NULL, '5085302P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5085302/235-55r19-105w-goodyear-eag-f1-at-self-seal-784042669--e4016e31-4819-4a49-bbc1-6e49422a856f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 19, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":300,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000014f', 'Goodyear Eagle LS 2 RFT Performance Tire For Passenger & CUV', 'goodyear-eagle-ls-2-rft-performance-tire-for-passenger-cuv', 'Wide circumferential grooves that help efficiently evacuate water from beneath the tread. Special tread block sequence helps enhance handling and traction and reduces tread noise. Premium sidewall styling features a contemporary appearance. Wheels sold separately', 619.99, NULL, '0085425P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0085425/goodyear-eagle-ls-2-rof-245-50r18-100v-706070322--0ed1a6ba-b612-4a20-bd2b-36bffe8eb25a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 17, false, false, false, '{}', 4, 331, '{"width":245,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":290,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000150', 'Bridgestone Turanza T005A Tire For Passenger & CUV', 'bridgestone-turanza-t005a-tire-for-passenger-cuv', 'Premium touring summer tyre designed to be fitted to Passenger Car. Grand Touring Summer tires are for drivers who want a combination of sophisticated appearance, competent handling and H-speed rated (or higher) durability, along with dry and wet traction from their tires. Original equipment on many popular vehicles. Wheels sold separately', 475.99, NULL, '0081908P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5081202/215-65r16-98hh-bridgestone-turanza-t005a-011754--1160ab0d-a5ae-4006-8579-0191a8f078cf-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 33, false, false, false, '{}', NULL, NULL, '{"width":225,"aspect_ratio":70,"rim_diameter":16,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":291,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000151', 'Michelin Pilot Sport Cup Performance Tire For Passenger & CUV', 'michelin-pilot-sport-cup-performance-tire-for-passenger-cuv', 'Features race-inspired tread compound strategy to maximize overall wet and dry performance. Outside shoulder compound is optimized for dry handling. Unique semislick outer tread and wet-styled inner tread ensure superior cornering in both wet and dry conditions. The inside shoulder has more potential for wet adherence', 49.99, NULL, '0081182P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0081182/michelin-pilot-sport-cup-235-35r19-87y-7299--68ee9092-0669-46ea-bbe5-42b39033939e-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Michelin', true, 38, false, false, false, '{}', 4.3542, 48, '{"width":255,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":287,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000152', 'Goodyear Eagle F1 SuperSport R Performance Tire for Passenger & CUV', 'goodyear-eagle-f1-supersport-r-performance-tire-for-passenger-cuv', 'Innovative U-shaped compound creates specialist power zones to improve wet and dry performance. The tread pattern and the tire shoulder is designed to provide responsive directional change with effective control when engaging corners. Delivers exceptional wet braking and wet handling performance. Tire shoulders feature more rubber and less cutaway tread than conventional rivals which maximises contact with the tarmac', 49.99, NULL, '5085267P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5085267/335-30zr21-109y-goodyear-eag-f1-supersport-r-112110627--0bde8f27-1732-446c-a73c-529ca99c1b7a-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 39, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":354,"traction":"A","temperature":"A","noise_level":"70 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000153', 'Goodyear Eagle F1 SS R Performance Tire', 'goodyear-eagle-f1-ss-r-performance-tire', 'Next-generation polymer tread compound. Excellent grip on dry roads and enhances wet traction. Rim protector helps protect wheels against accidental curb damage. Active CornerGrip® technology helps maintain even tread pressure to enhance grip while cornering. Not Winter Rated', 49.99, NULL, '4085625P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4085625/315-30zr2-eag-f1-ssr-57de3a4b-aaa7-4199-a648-ca1e0ca48419-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 34, false, false, false, '{}', NULL, NULL, '{"width":255,"aspect_ratio":55,"rim_diameter":18,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":318,"traction":"AA","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000154', 'Pirelli P-Zero™ Rosso Direzionale Performance Tire For Passenger & CUV', 'pirelli-p-zero-rosso-direzionale-performance-tire-for-passenger-cuv', 'Developed for modern, medium to high-powered cars. Satisfying, ultra high performance summer tire that embodies technology and functionality. Wheels sold separately', 49.99, NULL, '0089332P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0089332/pirelli-245-45zr18-100y-xl-rossod-1540100-30bdd1a3-1338-4591-82e8-2f1d68d0669f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Pirelli', true, 21, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":356,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
