('b2000000-0000-0000-0000-000000000156', 'Bridgestone Turanza EL42 RFT Tire', 'bridgestone-turanza-el42-rft-tire', 'Original Equipment on Popular Vehicles. Comfortable ride. Confident wet and dry performance. Quiet performance', 337.99, NULL, '3081024P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3081024/205-55r16-91h-turanz-116833--d88ad1ab-5b32-4b39-8482-320e8363aff8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 13, false, false, false, '{}', NULL, NULL, '{"width":205,"aspect_ratio":55,"rim_diameter":16,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":281,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000157', 'Continental SportContact 7 Performance Tire for Passenger & CUV', 'continental-sportcontact-7-performance-tire-for-passenger-cuv', 'Gives you confidence with safe and stable driving behaviour on wet and dry surfaces. Perfect interplay of extra-soft BlackChili compound and extra-stiff pattern. For long-lasting, next-level driving pleasure. Tailor-made for different vehicle classes to give you the typical SportContact™ feeling', 49.99, NULL, '3080364P', 'https://media-www.canadiantire.ca/product/automotive/tires/winter-tires/5082611/-265-35zr21-101y-xl-continental-sportcontact-7-03140050000--f86cd831-bd5f-4fe6-8ebf-dcafc8d7219f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 28, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":285,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000158', 'Firestone Firehawk Pursuit Tire For Passenger & CUV, Wet & Dry Handling', 'firestone-firehawk-pursuit-tire-for-passenger-cuv-wet-dry-handling', 'Engineered for use on pursuit vehicles. Combines excellent wet and dry handling with an emphasis on quick steering response.. Built for durability, the Firehawk Pursuit gives you good wear without sacrificing ride quality.. Wheels sold separately', 49.99, NULL, '4086706P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5084586/265-50r20-107v-firestone-firehawk-pursuit-013789--cf919922-5ada-4e90-b1f0-bc192b500405-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Firestone', true, 16, false, true, false, '{}', NULL, NULL, '{"width":215,"aspect_ratio":75,"rim_diameter":15,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":272,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000159', 'Michelin Pilot Sport PS2 Performance Tire For Passenger & CUV', 'michelin-pilot-sport-ps2-performance-tire-for-passenger-cuv', 'Features advanced tread rubber compounds. High performance cornering. Outstanding performance in wet and dry conditions. High-tensile steel belts react instantly to input, giving you a connected feel with the road. Wheels sold separately', 49.99, NULL, '0083648P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0088096/michelin-pilot-sport-ps2-295-30r19-100y-62471--7b13b144-b7dd-4350-9a84-6275b1d3ff2f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Unknown', true, 33, false, true, true, '{}', 4.4527, 1732, '{"width":235,"aspect_ratio":75,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":272,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000015a', 'Cooper Zeon RS3-G1 Performance Tire For Passenger & CUV', 'cooper-zeon-rs3-g1-performance-tire-for-passenger-cuv', 'Cooper Zeon RS3-G1 Tire is for high performance vehicles and enthusiast drivers. Tread compound and design features great grip, stability and durability. Delivers great performance on dry and wet pavement. 3-D Micro Gauge sipes improve the stability of tread elements providing enhanced handling in wet and dry roads. Asymmetrical tread pattern provides grip and stability during cornering maneuvers and reduced tire noise. Made with a silica tread compound that is specially formulated to provide maximum dry and wet traction. Cooper’s trademarked visual wear indicator provides peace of mind through informing drivers how worn their tires are. Wheels sold separately', 49.99, NULL, '4081904P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/0071035/205-50r17xl-93w-cooper-zeon-rs3-g1-74f05f78-5c78-44bf-9bad-681058188fa8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Goodyear', true, 21, false, true, false, '{}', 4.1828, 290, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":341,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000015b', 'Bridgestone Turanza EL440 Tire', 'bridgestone-turanza-el440-tire', 'Bridgestone Turanza EL400 offers wet and dry traction while providing a surprisingly comfortable ride.. Luxury performance with a quiet ride with a confident wet and dry performance. Engineered to provide long wear life. Wheels sold separately', 323.99, NULL, '3083347P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3083347/-235-40r19-92v-bridgestone-turanza-el440-000221--6d90ff79-78ce-4340-98a5-bff1cb3348a4-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 31, false, true, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":40,"rim_diameter":20,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":345,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000015c', 'Hankook Ventus S1 Evo3 Tire For Passenger & CUVs, All Season Tire', 'hankook-ventus-s1-evo3-tire-for-passenger-cuvs-all-season-tire', 'Delivers powerful performance and superior handling for luxury vehicles. High-grip silica compound and the chamfer edge sipes provide excellent traction in wet and snowy conditions. Circumferential grooves help resist hydroplaning and provide superior wet traction. Wheels sold separately', 49.99, NULL, '4086446P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4083898/285-40zr21-xl-109y-k-ventus-s1-evo3-suv-1020785--c257dc2e-308c-4a20-964b-1099b1cc3f40-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Hankook', true, 38, false, false, false, '{}', NULL, NULL, '{"width":235,"aspect_ratio":70,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":289,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000015d', 'Michelin Pilot® Sport Cup 2 R Summer Performance Tire For Passenger & CUV', 'michelin-pilot-sport-cup-2-r-summer-performance-tire-for-passenger-cuv', 'Optimized for summer conditions to enhance lap times. Original equipment on top track models. Superior traction on dry surfaces. Outstanding grip in tight corners. Wheels are not included', 49.99, NULL, '5087290P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5087295/325-30r20-102-y-michelin-pilot-sport-cup-2-r-15083--288975dc-5798-4902-9b7b-b57c4bb45801-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Michelin', true, 35, false, false, false, '{}', 1, 1, '{"width":235,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":291,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000015e', 'Continental sContact', 'continental-scontact', 'Approved for speeds up to 80 km/h. Compatible with most passenger and SUV vehicles. Wheels are sold separately', 49.99, NULL, '3086634P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/4089817/t125-70r18-99m-sc-scontact-03115250000--dce7d417-9383-44ca-8569-82ef0ffad6a2-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 37, false, false, false, '{}', NULL, NULL, '{"width":275,"aspect_ratio":55,"rim_diameter":19,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":320,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-00000000015f', 'Continental PremiumContact™ 6 Performance Tire for Passenger & CUV', 'continental-premiumcontact-6-performance-tire-for-passenger-cuv', 'Confidence when it rains - Crystal silica composition provides outstanding grip on wet roads. Responsive handling - Advanced macro-block shoulders and asymmetric rib geometry strenghtens the tread pattern for sport driving. Comfortable and quiet ride - smooth pattern stiffness improves the ride quality and lowers the noise levels. Wheels sold separately', 49.99, NULL, '3086632P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5082628/275-35r22-104y-xl-continental-premiumcontact-6-03588650000--2aecd7a7-a9ca-492d-8984-dd1521584d93-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 37, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":350,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000160', 'Bridgestone Potenza Race Performance Tire', 'bridgestone-potenza-race-performance-tire', 'Ensures confident wet handling with a tread inspired by the INDYCAR Firehawk rain tire. Supported by circumferential grooves and open shoulder slots provide hydroplaning resistance. Excellent snow performance in light snow conditions', 49.99, NULL, '5081098P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5081098/245-30zr20-90y-y-bridgestone-potenza-race-013631--63ff60e4-a189-4671-8182-9d1f4859aff0-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 29, false, true, false, '{}', 5, 1, '{"width":285,"aspect_ratio":40,"rim_diameter":20,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":289,"traction":"AA","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000161', 'Continental ContiProContact RFT All Season Tire For Passenger & CUV', 'continental-contiprocontact-rft-all-season-tire-for-passenger-cuv', 'Continental ContiProContact - SSR Tire is a high-performance tire for top-of-the-line performance vehicles. Designed for performance and touring, it features excellent wet-braking capacity and traction. Special shoulder groove geometry fosters secure cornering and standout performance in wet conditions. Interlocking tread sipes deliver improved steering precision and dry performance. Alternating convex and concave sipe design promotes multidirectional grip and low noise. Wheels sold separately', 49.99, NULL, '0088829P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/0088829/195-55r16-87v-sl-conti-procontact-ssr-03526260000--48b62ab3-c001-4a28-9720-c546947c0e12-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Continental', true, 31, false, false, false, '{}', 5, 1, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":318,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000162', 'Kumho Ecsta Sport S PS72 Performance Passenger & CUV Tires', 'kumho-ecsta-sport-s-ps72-performance-passenger-cuv-tires', 'For drivers requiring ultimate driving dynamics. A premium tire especially well suited to powerful cars. High level of dry traction, high-speed stability and precise handling. Perfect for petrol, hybrid, and electric vehicles. EV Compatible across the range, including high load variants, with K Silent noise reducing technology (where specified). Wheels sold separately', 49.99, NULL, '5088310P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5088341/265-40r19-102-y-kumho-ecsta-sport-s-ps72-2310683--c040a6a5-a3fe-4e42-a902-e5eba9954cc1-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Kumho', true, 16, false, false, false, '{}', NULL, NULL, '{"width":245,"aspect_ratio":60,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":291,"traction":"A","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000163', 'Falken Azenis RT660 Tire', 'falken-azenis-rt660-tire', 'Track-ready performance tire. DOT-approved. Performance winter traction. Ice braking capability. Winter driving confidence. Wheels sold separately', 49.99, NULL, '3086142P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/3080417/315-30zr19-100w-sl-falken-azenis-rt660-28679574--685e4d39-5b96-4c3e-bed8-1ec72e813054-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Falken', true, 39, false, false, false, '{}', NULL, NULL, '{"width":265,"aspect_ratio":60,"rim_diameter":18,"load_index":"94","speed_rating":"V","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":337,"traction":"A","temperature":"A","noise_level":"73 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000164', 'Bridgestone Turanza EL450 Touring Tire for Passenger & CUV', 'bridgestone-turanza-el450-touring-tire-for-passenger-cuv', 'Luxury performance with a quiet comfortable ride. Confident wet and dry performance. Improved performance all season long. Engineered to provide long wear life. Wheels sold separately', 49.99, NULL, '3083336P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5082116/255-55r18-105v-bridgestone-turanza-el450-014952--31c243b9-4eeb-4857-ad11-067620fb89d8-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 15, false, false, false, '{}', 4, 1, '{"width":265,"aspect_ratio":55,"rim_diameter":19,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":276,"traction":"A","temperature":"A","noise_level":"74 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000165', 'Yokohama ADVAN Sport V107 Tire', 'yokohama-advan-sport-v107-tire', 'Designed to perform better, keep you safer, and take you further.. The ADVAN Sport V107 delivers an exceptional driving experience. Wider tread blocks on the outside of the tread enhance dry performance. Variable pitch tread reduces pattern noise offering a quiet and comfortable ride. Increased groove area on the inner portion maximizes wet performance', 49.99, NULL, '5080956P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/5081704/225-45zr18-95y-yokohama-advan-sport-v107-110110711--9c0f6c0c-346f-47bb-8315-d09fed32401f-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Yokohama', true, 16, false, false, true, '{}', NULL, NULL, '{"width":265,"aspect_ratio":50,"rim_diameter":19,"load_index":"96","speed_rating":"Y","tire_type":"Passenger","season":"Summer","runflat":false,"treadwear":353,"traction":"AA","temperature":"A","noise_level":"72 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000166', 'Bridgestone Turanza T005 RFT Touring Tire For Passenger & CUV', 'bridgestone-turanza-t005-rft-touring-tire-for-passenger-cuv', 'Luxury performance with a quiet ride. Confident wet and dry performance. Long wear life. Improved performance all season long.. Wheels sold separately', 49.99, NULL, '3083337P', 'https://media-www.canadiantire.ca/product/automotive/tires/all-season-tires/5082125/235-55r18-100y-bridgestone-turanza-t005-011573--8ac47099-d9f6-49a2-b94e-f29b40189991-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Bridgestone', true, 37, false, false, false, '{}', NULL, NULL, '{"width":285,"aspect_ratio":65,"rim_diameter":18,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":267,"traction":"A","temperature":"A","noise_level":"71 dB","warranty_miles":0}'),
('b2000000-0000-0000-0000-000000000167', 'Yokohama ADVAN A048 Performance Tire For Passenger & CUV', 'yokohama-advan-a048-performance-tire-for-passenger-cuv', 'Yokohama ADVAN A048 Tire easily transitions from straight-line sprints to high-speed cornering, enabling predictable handling. ADVAN A048 is a street legal tire-created for short-track racing. Single block design increases stiffness, enhances cornering and optimizes power transitions during acceleration, and braking. Race-Ready Compound delivers phenomenal grip under a broad range of temperatures. Wheels sold separately', 311.99, NULL, '4087576P', 'https://media-www.canadiantire.ca/product/automotive/tires/performance-tires/4087576/225-45r17-90w-a048-110104805--e4382a65-bacd-4b51-809c-c5e84a2ec497-jpgrendition.jpg', 'a1000000-0000-0000-0000-000000000002', 'Yokohama', true, 32, false, false, false, '{}', NULL, NULL, '{"width":225,"aspect_ratio":65,"rim_diameter":17,"load_index":"104","speed_rating":"T","tire_type":"Light Truck","season":"Summer","runflat":false,"treadwear":350,"traction":"A","temperature":"A","noise_level":"69 dB","warranty_miles":0}'),
